<?php
declare(strict_types=1);

use Phalcon\Mvc\View;
use ElephantIO\Client;
use Phalcon\Db\Column;
use Phalcon\Image\Enum;
use Phalcon\Mvc\Model\Resultset;
use Symfony\Component\Process\Process;
use Symfony\Component\Process\Exception\ProcessFailedException;
require_once __DIR__ . '/../library/QueueName.php';
    
class ApiController extends ControllerBase  
{
    public $version = '9.2.0.59.65102326';

    public function indexAction($mode = 0)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth"); 
        if ($session) {
            if ($this->request->isGet()) {
                $this->redis->set("serverVersion", $this->version);
                $whiteLabelLogo = "";
                $whiteLabelAbout = "";
                if ($this->redis->exists("companyBanner")) {
                    $whiteLabelLogo = $this->redis->get("companyBanner");
                }
                if ($this->redis->exists("whiteLabelAbout")) {
                    $whiteLabelAbout  = $this->redis->get("whiteLabelAbout");
                }
                $index = 0;
                $content = array();
                $firstname = "";
                $lastname = "";
                $userRecord = 0;
                $agentstatus = "Offline";
                $outboundCallerID = "";
                $supportExtensions = ["9997", "9998", "9999"];
                // static names for support extensions so old accounts (created with bare-number
                // effective_caller_id_name) still display correctly without a DB backfill
                $supportNames = ["9997" => "Partner Account", "9998" => "RingQ L1 Support", "9999" => "RingQ L2 Support"];
                $extensions2 = [];
                $queueAssigned = false;
                $allRegistrations = Registrations::find()->toArray();
                $activeUsers = array_column($allRegistrations, 'reg_user', 'reg_user');
                $allDialplans = [];                
                if ($this->redis->exists('allDialplans-' . $session["subdomain"])) {
                    $allDialplans = json_decode($this->redis->get('allDialplans-' . $session["subdomain"]));
                } else {
                    $allDialplans = VDialplans::find([
                        "conditions" => "domain_uuid = :domain_uuid: AND dialplan_number IS NOT NULL",
                        "bind"       => ["domain_uuid" => $session["domain_uuid"]]
                    ]);
                    $this->redis->set('allDialplans-' . $session["subdomain"], json_encode($allDialplans));
                }
                $dialplansByExt = [];
                foreach ($allDialplans as $dp) {
                    $dialplansByExt[$dp->dialplan_number][] = $dp->dialplan_description; 
                }                
                $vExtensions;
                if ($this->redis->exists('vExtensions-' . $session["subdomain"])) {
                    $vExtensions = json_decode($this->redis->get('vExtensions-' . $session["subdomain"]));
                } else {
                    $vExtensionsResult = VExtensions::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                            "order" => "extension ASC"
                        ]
                    );
                    $vExtensions = [];
                    if ($vExtensionsResult) {
                        foreach ($vExtensionsResult as $row) {
                            // This strips Phalcon internal mechanics and leaves a clean, generic PHP object
                            $vExtensions[] = (object) $row->toArray(); 
                        }
                    }
                    $this->redis->set('vExtensions-' . $session["subdomain"], json_encode($vExtensions));
                }
                $allVusers = [];
                if ($this->redis->exists('allVusers-' . $session["subdomain"])) {
                    $allVusers = json_decode($this->redis->get('allVusers-' . $session["subdomain"]));
                } else {
                    $allVusers = VUsers::find(
                        [
                            
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                        ]
                    )->toArray();
                    $this->redis->set('allVusers-' . $session["subdomain"], json_encode($allVusers));
                }
                $activeExtensions = array_column($vExtensions, 'extension', 'username');
                $activeUsers2 = array_column($allVusers, 'user_status', 'username');
                $activeUserUuids = array_column($allVusers, 'user_uuid', 'username');
                $activeUsersEmails = array_column($allVusers, 'user_email', 'username');
                $allQUsers = [];
                if ($this->redis->exists('allQUsers-' . $session["subdomain"])) {
                    $allQUsers = json_decode($this->redis->get('allQUsers-' . $session["subdomain"]));
                } else {
                    $allQUsers = QUsers::find()->toArray();
                    $this->redis->set('allQUsers-' . $session["subdomain"], json_encode($allQUsers));
                }
                $activeQUsers = array_column($allQUsers, 'image', 'user_uuid');
                $activeQUserFirstNames = array_column($allQUsers, 'first_name', 'user_uuid');
                $activeQUserLastNames = array_column($allQUsers, 'last_name', 'user_uuid');
                // Names come from q_users (as accounts/extension does); the caller-ID split is only a fallback
                // for extensions without a q_users row, since it mis-splits multi-word first names.
                $resolveNames = function ($vExtension) use ($supportNames, $activeUserUuids, $activeQUserFirstNames, $activeQUserLastNames) {
                    if (!isset($supportNames[$vExtension->extension])) {
                        $userUuid = $activeUserUuids[$vExtension->number_alias] ?? null;
                        if ($userUuid !== null && (array_key_exists($userUuid, $activeQUserFirstNames) || array_key_exists($userUuid, $activeQUserLastNames))) {
                            return [(string) ($activeQUserFirstNames[$userUuid] ?? ''), (string) ($activeQUserLastNames[$userUuid] ?? '')];
                        }
                    }
                    $effName = $supportNames[$vExtension->extension] ?? ($vExtension->effective_caller_id_name ?? '');
                    $parts = explode(' ', trim($effName), 2);
                    return [$parts[0] ?? '', $parts[1] ?? ''];
                };
                $vFaxes = array();
                $activeExtensions = [];
                foreach ($vExtensions as $vExtension) {
                    if ((is_numeric($vExtension->extension) && in_array($session["extension"], $supportExtensions)) || ($vExtension->extension != "9997" && $vExtension->extension != "9998" && $vExtension->extension != "9999")) {
                        if (strlen($vExtension->extension) <= 4) {
                            if ($session["extension"] == $vExtension->extension) {
                                $outboundCallerID = isset($vExtension->outbound_caller_id_number) ? $vExtension->outbound_caller_id_number : "";
                                [$firstname, $lastname] = $resolveNames($vExtension);
                                if (!empty($vExtension->user_record) && $vExtension->user_record != null) {
                                    if ($vExtension->user_record == "All") {
                                        $userRecord = 1;
                                    } elseif ($vExtension->user_record == "Inbound") {
                                        $userRecord = 2;
                                    } elseif ($vExtension->user_record == "Outbound") {
                                        $userRecord = 3;
                                    }
                                }
                            }
                            array_push($vFaxes,[
                                "fax_uuid" => $vExtension->extension_uuid,
                                "fax_extension" => $vExtension->extension,
                                "fax_name" => $vExtension->effective_caller_id_name,
                                "fax_destination_number" => $vExtension->extension,

                            ]);
                            $activeExtensions[$vExtension->number_alias][] = $vExtension->extension;
                            $content[$index]["domain_uuid"] = $vExtension->domain_uuid;
                            $content[$index]["extension"] = $vExtension->extension;
                            $content[$index]["extension2"] = $vExtension->number_alias;
                            $content[$index]["username"] = $vExtension->number_alias;
                            $content[$index]["email"] = isset($activeUsersEmails[$vExtension->number_alias]) ? $activeUsersEmails[$vExtension->number_alias] : ""; // $vExtension->vExtensionUsers->vUsers->user_email;
                            [$content[$index]["firstname"], $content[$index]["lastname"]] = $resolveNames($vExtension);
                            $content[$index]["image"] = '';
                            // $content[$index]["image"] = $vExtension->vExtensionUsers->qUsers->image;
                            if (isset($activeUserUuids[$vExtension->number_alias])) {
                                if (isset($activeQUsers[$activeUserUuids[$vExtension->number_alias]])) {
                                    $content[$index]["image"] = $activeQUsers[$activeUserUuids[$vExtension->number_alias]];
                                }
                            }
                            $profileStatus = $this->redis->get($vExtension->extension . "+" . $session["subdomain"]);
                            $content[$index]["status"] = $profileStatus ? $profileStatus : 0;
                            $content[$index]["showContactModule2"] = $this->redis->get($vExtension->extension . "+" . $session["subdomain"] . "-contact-page-enabled") != null ? $this->redis->get($vExtension->extension . "+" . $session["subdomain"] . "-contact-page-enabled") : "0";
                            $username = $vExtension->number_alias;
                            $status2 = $activeUsers2[$username] ?? 'Logged Out';
                            if (isset($activeUsers[$username])) {
                                $status2 = 'Available';
                            }
                            $content[$index]["status2"] = $status2;
                            $content[$index]["status3"] = $this->redis->get("wallstatus:" . $session["subdomain"] . ":". $vExtension->extension);
                            $content[$index]["status4"] = $this->redis->get("callstatus:" . $session["subdomain"] . ":". $vExtension->extension);
                            $call_profiles_colors = [];
                            // if ($session["extension"] == $vExtension->extension) {
                                $qCallBehavior = QCallBehaviors::findFirst(
                                    [
                                        
                                        "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
                                        "bind" =>
                                            [
                                                "domain_uuid" => $session["domain_uuid"],
                                                "extension" => $vExtension->extension,
                                            ],
                                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                                    ]
                                );
                                if (isset($qCallBehavior)) {
                                    $call_profiles_colors = explode(",", $qCallBehavior->call_profiles_colors);
                                }
                                $content[$index]["sso_qr"] = $qCallBehavior->sso_qr;
                                $content[$index]["sso_number"] = $qCallBehavior->sso_number;
                                $content[$index]["custom"] = $call_profiles_colors[3];
                                $content[$index]["custom2"] = $call_profiles_colors[4];
                            // }
                            $content[$index]["call_timeout"] = $vExtension->call_timeout;
                            $content[$index]["forward_no_answer_destination"] = $vExtension->forward_no_answer_destination;
                            $workHours = array();
                            $breakHours = array();
                            if (!empty($dialplansByExt[$vExtension->extension])) {
                                foreach ($dialplansByExt[$vExtension->extension] as $description) {
                                    if (empty($description)) continue;
                                    $parameters = explode("-", $description);
                                    if (!empty($parameters)) {
                                        if ($parameters[0] === "1") {
                                            $workHours[] = $parameters;
                                        } else {
                                            $breakHours[] = $parameters;
                                        }
                                    }
                                }
                            }
                            $content[$index]["workhours"] = $workHours;
                            $content[$index]["breakhours"] = $breakHours;
                            $index++;
                        }
                    } else {
                        $extensions2 = [...$extensions2, [$vExtension->number_alias => $vExtension->extension]];
                    }
                }
                $extensions2 = array_merge(...$extensions2);
                $walltoken = $this->security->hash($session["user_uuid"]);
                $walldata = array(
                    "answered_wallboard" => 0, 
                    "waiting_wallboard" => 0, 
                    "abandoned_wallboard" => 0,
                    "total_wallboard" => 0, 
                    "missed_calls" => 0, 
                    "answered_calls" => 0, 
                    "total" => 0, 
                    "active" => 0, 
                    "waiting" => 0, 
                    "abandoned" => 
                    0
