                $this->redis->sadd("wallboard:" . $session["subdomain"], $walltoken);
                if (!$this->redis->exists("walldata:" . $session["subdomain"])) {
                    $this->redis->hmset("walldata:" . $session["subdomain"], $walldata);
                    $this->redis->expire("walldata:" . $session["subdomain"], 86400);
                } else {
                    $walldata = $this->redis->hgetall("walldata:" . $session["subdomain"]);
                }
                if (!array_key_exists("total", $walldata)) {
                    $walldata = array(
                        "answered_calls" => 0, 
                        "answered_wallboard" => 0, 
                        "waiting_wallboard" => 0, 
                        "abandoned_wallboard" => 0, 
                        "total_wallboard" => 0, 
                        "missed_calls" => 0, 
                        "total" => 0, 
                        "active" => 0, 
                        "waiting" => 0, 
                        "abandoned" => 0
                    );
                }
                $wallinfo = array();
                $vUsersCount = VUsers::count(
