                if ($this->redis->exists('allVCallCenterTiers-' . $session["subdomain"])) {
                    $allVCallCenterTiers = json_decode($this->redis->get('allVCallCenterTiers-' . $session["subdomain"]), true);
                } else {
                    $allVCallCenterTiers = VCallCenterTiers::find(
                        [
                            
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                        ]
                    )->toArray();
                    $this->redis->set('allVCallCenterTiers-' . $session["subdomain"], json_encode($allVCallCenterTiers));
                }
                $activeallVCallCenterTiers = array_column($allVCallCenterTiers, 'tier_level', 'call_center_agent_uuid');
                $activeallVCallCenterTiers2 = array_column($allVCallCenterTiers, 'tier_position', 'call_center_agent_uuid');
                $vCallCenterAgents5;
                if ($this->redis->exists('vCallCenterAgents5-' . $session["subdomain"])) {
                    $vCallCenterAgents5 = json_decode($this->redis->get('vCallCenterAgents5-' . $session["subdomain"]), true);
                } else {
                    $vCallCenterAgents5 = VCallCenterAgents::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND agent_id != :agent_id: AND agent_id != :agent_id2: AND agent_id != :agent_id3: AND queue_extension IS NOT NULL",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "agent_id" => "9997",
                                    "agent_id2" => "9998",
                                    "agent_id3" => "9999",
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                            "order" => "agent_id ASC"
                        ]
                    )->toArray();
                    $this->redis->set('vCallCenterAgents5-' . $session["subdomain"], json_encode($vCallCenterAgents5));
                }
                $activeallCallCenterAgents = array_column($vCallCenterAgents5, 'agent_name', 'call_center_agent_uuid');
                $activeallCallCenterAgents2 = array_column($vCallCenterAgents5, 'agent_id', 'call_center_agent_uuid');
                if (in_array($session["username"], $activeallCallCenterAgents2)) {
                    $queueAssigned = true;
                }
                $agents5 = array();
                $agents6 = array();
                $wallAuxcodes = array();
                foreach ($vCallCenterAgents5 as $vCallCenterAgent) {
                    if ($vCallCenterAgent["queue_extension"] != null) {
                        if (isset($activeallVCallCenterTiers[$vCallCenterAgent["call_center_agent_uuid"]])) {
                            if (isset($activeExtensions[$vCallCenterAgent["agent_id"]])) {
                                array_push($agents5, [strval($vCallCenterAgent["call_center_agent_uuid"]) => $vCallCenterAgent["agent_name"] . " (". $activeExtensions[$vCallCenterAgent["agent_id"]][0] . ")"]);
                            } else {
                                array_push($agents5, [strval($vCallCenterAgent["call_center_agent_uuid"]) => $vCallCenterAgent["agent_name"] . " (". $vCallCenterAgent["agent_id"] . ")"]);
                            }
                            array_push($agents6, [strval($vCallCenterAgent["call_center_agent_uuid"]) => ["level" => $activeallVCallCenterTiers[$vCallCenterAgent["call_center_agent_uuid"]], "position" => $activeallVCallCenterTiers2[$vCallCenterAgent["call_center_agent_uuid"]]]]);
                        }
                        array_push($wallAuxcodes, [strval($vCallCenterAgent["call_center_agent_uuid"]) => $vCallCenterAgent["agent_status"]]);
                    } else {
                        array_push($wallAuxcodes, [strval($vCallCenterAgent["agent_id"]) => $vCallCenterAgent["agent_status"]]);
                    }
                }
                $qDids = QDids::find(
                    [
                        
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "columns" => "did_uuid, did_number, type, name, extension, outbound, sip_trunk_name, country",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                $vIvrMenus = [];
                if ($this->redis->exists('vIvrMenus-' . $session["subdomain"])) {
                    $vIvrMenus = json_decode($this->redis->get('vIvrMenus-' . $session["subdomain"]));
                } else {
                    $vIvrMenus = VIvrMenus::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND ivr_menu_extension > '5000'",
                            "columns" => "ivr_menu_uuid, ivr_menu_name, ivr_menu_extension, ivr_menu_greet_long, ivr_menu_exit_data, ivr_menu_timeout, ivr_menu_direct_dial",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                            "order" => "ivr_menu_extension ASC",
                        ]
                    )->toArray();
                    $this->redis->set('vIvrMenus-' . $session["subdomain"], json_encode($vIvrMenus));
                }
                $activeIvrMenus = array_column($vIvrMenus, 'ivr_menu_uuid', 'ivr_menu_extension');
                $vIvrMenuOptionsRaw = [];
                if ($this->redis->exists('vIvrMenuOptionsRaw-' . $session["subdomain"])) {
                    $vIvrMenuOptionsRaw = json_decode($this->redis->get('vIvrMenuOptionsRaw-' . $session["subdomain"]), true);
                } else {
                    $vIvrMenuOptionsRaw = VIvrMenuOptions::find([
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "columns" => "ivr_menu_uuid, ivr_menu_option_digits, ivr_menu_option_action, ivr_menu_option_param",
                        "bind" => [
                            "domain_uuid" => $session["domain_uuid"],
                        ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ])->toArray();
                    $this->redis->set('vIvrMenuOptionsRaw-' . $session["subdomain"], json_encode($vIvrMenuOptionsRaw));
                }
                $grouped = [];
                foreach ($vIvrMenuOptionsRaw as $option) {
                    $uuid = $option['ivr_menu_uuid'];
                    $grouped[$uuid][] = [
                        "ivr_menu_option_digits" => $option['ivr_menu_option_digits'],
                        "ivr_menu_option_action" => $option['ivr_menu_option_action'],
                        "ivr_menu_option_param"  => $option['ivr_menu_option_param']
                    ];
                }
                $vIvrMenuOptions = array();
                $vIvrMenuWorkHours = array();
                $vIvrMenuBreakHours = array();
                if ($mode != 1) {
                    foreach ($activeIvrMenus as $key => $value) {
                        $menuOptions = $grouped[$value] ?? [];
                        $vIvrMenuOptions[] = [
                            $key => $menuOptions
                        ];
                        $workHours = array();
                        $breakHours = array();
                        if (!empty($dialplansByExt[$key])) {
                            foreach ($dialplansByExt[$key] as $description) {
                                if (empty($description)) continue;
                                $parameters = explode("-", $description);
                                if (!empty($parameters)) {
                                    if ($parameters[0] === "1") {
                                        $workHours[] = $parameters;
                                    } else {
                                        $breakHours[] = $parameters;
                                    }
                                }
                            }
                        }
                        array_push($vIvrMenuWorkHours, [$key => $workHours]);
                        array_push($vIvrMenuBreakHours, [$key => $breakHours]);
                    }
                }
                $vCallCenterQueues;
                if ($this->redis->exists('vCallCenterQueues-' . $session["subdomain"])) {
                    $vCallCenterQueues = unserialize($this->redis->get('vCallCenterQueues-' . $session["subdomain"]));
                } else {
