                            "siPgateways" => $siPgateways,
                            "sipStatus" => $sipStatus,
                            "onlineExtensions" => $onlineExtensions,
                            "queueWallboardCallStatus" =>  $queueWallboardCallStatus,
                            "queueWallboardAgentBoard" =>  $queueWallboardAgentBoard,
                            "queueWallboardConfigBoard" =>  $queueWallboardConfigBoard,
                            "facebookSettings" => isset($facebookSettings) ? $facebookSettings : null,
                            "whatsappSettings" => isset($whatsappSettings) ? $whatsappSettings : null,
                            "lineSettings" => isset($lineSettings) ? $lineSettings : null,
                            "telegramSettings" => isset($telegramSettings) ? $telegramSettings : null,
                            "callcenterFacebookChats" => isset($callcenterFacebookChats) ? $callcenterFacebookChats : null,
                            "callcenterWhatsappChats" => isset($callcenterWhatsappChats) ? $callcenterWhatsappChats : null,
                            "callcenterWebChats" => isset($callcenterWebChats) ? $callcenterWebChats : null,
                            "callcenterLineChats" => isset($callcenterLineChats) ? $callcenterLineChats : null,
                            "callcenterTelegramChats" => isset($callcenterTelegramChats) ? $callcenterTelegramChats : null,
                            "callcenterTelnyxChats" => isset($callcenterTelnyxChats) ? $callcenterTelnyxChats : null,
                            "callcenterTwilioChats" => isset($callcenterTwilioChats) ? $callcenterTwilioChats : null,
                            "smsGenericSettings" => isset($smsGenericSettings) ? $smsGenericSettings : null,
                            "smsTikoSettings" => isset($smsTikoSettings) ? $smsTikoSettings : null,
                            "smsTwilioSettings" => isset($smsTwilioSettings) ? $smsTwilioSettings : null,
                            //ryan 092926 start
                            "smsChatSettings" => isset($smsChatSettings) ? $smsChatSettings : null,
                            //ryan 092926 end
                            "smsTelnyxSettings" => isset($smsTelnyxSettings) ? $smsTelnyxSettings : null,
                            "webChatSettings" => isset($webChatSettings) ? $webChatSettings : null,
                            "enableOwnerManagerAssign" => $enableOwnerManagerAssign,
                            "enableEveryAgentQ" => $enableEveryAgentQ,
                            "enableRoundRobin" => $enableRoundRobin,
                            "defaultChatSound" => isset($defaultChatSound) ? $defaultChatSound : 0,
                            "ssoQR" => $ssoQR,
                            "ssoNumber" => $ssoNumber,
                            "webPassword" => $webPassword,
                            "appEnabled" => $appEnabled,
                            "webappEnabled" => $webappEnabled,
                            "callcontrolEnabled" => $callcontrolEnabled,
                            "contactChecker" => $contactChecker,
                            "emailBanner" => $emailBanner,
                            "emailFooter" => $emailFooter,
                            "outboundRules" => isset($qOutboundRules) ? $qOutboundRules : [],
                            "sipProfiles" => isset($vSipProfiles) ? $vSipProfiles : [],
                            // "wallboardSettings" => $this->redis->get($session["extension"] . "@". $session["subdomain"] ."-walldataSettings") != null ? json_decode($this->redis->get($session["extension"] . "@". $session["subdomain"] ."-walldataSettings")) : []
                        ]
                    );
                    $client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
                        "persistent" => false,
                    ]));
                    $client->initialize();
                    $client->emit("logoutStatus", ["subdomain" => $session["subdomain"], "extension" => $session["extension"], "status" => 1]);
                    $this->response->setContent($response);
                    return $this->response;
                }
            }
            if ($this->request->isPost()) {
                $parameters = array();
                $parameters["type"] = intval($this->request->getPost("type", "int"));
                $parameters["push_token"] = $this->request->getPost("push_token", "string");
                $parameters["push_token2"] = $this->request->getPost("push_token2", "string");
                $parameters["device_name"] = $this->request->getPost("device_name", "string");
                $parameters["device_version"] = $this->request->getPost("device_version", "string");
                $parameters["device_uuid"] = $this->request->getPost("device_uuid", "string");
                $parameters["version"] = $this->request->getPost("version", "string");
                $parameters["device_signed_out"] = $this->request->getPost("device_signed_out", "string");
                $parameters["mobile_type"] = "android2";
                if (empty($parameters["push_token"])) {
                    $contents = file_get_contents("php://input");
                    $decodedParameters = json_decode($contents, true);
                    if (is_array($decodedParameters)) {
                        $parameters = $decodedParameters;
                    }
                }
                if (!is_array($parameters)) {
                    $parameters = array();
                }
                if (!empty($parameters["device_signed_out"])) {
                    $qDeviceOut = QDevices::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid: AND device_name = :device_name: AND device_type = :device_type:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "user_uuid" => $session["user_uuid"],
                                    "device_name" => strval($parameters["device_name"] ?? ""),
                                    "device_type" => intval($parameters["type"] ?? 0),
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT]
                        ]
                    );
                    if ($qDeviceOut) {
                        try {
                            $this->redis->setex("deviceSignedOut:" . $qDeviceOut->id, 2592000, "1");
                        } catch (\Throwable $signedOutError) {
                        }
                    }
                    $response = json_encode(
                        [
                            "result" => "success",
                            "content" => $qDeviceOut ? $qDeviceOut->id : "",
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $length = strlen(strval($parameters["push_token"] ?? ""));
                if ($length > 160) {
                    $parameters["mobile_type"] = "android/web";
                }
                if ($length < 65 && $length > 32) {
                    $parameters["mobile_type"] = "iOS";
                }
                if (!empty($parameters["device_uuid"])) {
                    if (!is_string($parameters["device_uuid"]) && !preg_match("/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i", $parameters["device_uuid"])) {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Invalid device ID (Code AI1000)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                }
                if (is_array($parameters)) {
                    foreach (["push_token2", "push_token3", "device_name", "device_version", "version"] as $optionalField) {
                        if (isset($parameters[$optionalField]) && is_string($parameters[$optionalField])) {
                            if (in_array(strtolower(trim($parameters[$optionalField])), ["null", "undefined", "nil"], true)) {
                                $parameters[$optionalField] = "";
                            }
                        }
                    }
                }
                $pushTokenPlaceholder = "693aa721556325f440a886";
                $pushTokenSubstituted = false;
                if (is_array($parameters)) {
                    if (!isset($parameters["push_token"]) || trim(strval($parameters["push_token"])) === "") {
                        $parameters["push_token"] = $pushTokenPlaceholder . "-" . substr(hash("sha256", implode("|", [
                            strval($session["domain_uuid"]),
                            strval($session["user_uuid"]),
                            strval(isset($parameters["device_name"]) ? $parameters["device_name"] : ""),
                            strval(intval(isset($parameters["type"]) ? $parameters["type"] : 0)),
                        ])), 0, 24);
                        $pushTokenSubstituted = true;
                    }
                }
                $pushtokenForm = new PushtokenForm();
                if (!$pushtokenForm->isValid($parameters)) {
                    $messages = $pushtokenForm->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AI1000)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                } else {
                    $vUser = VUsers::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "user_uuid" => $session["user_uuid"],
                                ],
                            "bindTypes" =>
                                [
                                    Column::BIND_PARAM_STR,
                                    Column::BIND_PARAM_STR,
                                ]
                        ]
                    );
                    if ($vUser) {
                        if ($vUser->user_status == "Logged Out") {
                            $vUser->user_status = "Available";
                            $vUser->update();
                        }
                    }
                    $qUser = QUsers::findFirst(
                        [
                            "conditions" => "user_uuid = :user_uuid:",
                            "bind" =>
                                [
                                    "user_uuid" => $session["user_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR]
                        ]
                    );
                    if ($qUser) {
                        $pushTokens = $qUser->push_token;
                        if (!$pushTokenSubstituted) {
                            $qUser->push_token = $parameters["push_token"];
                        }
                        $qUser->mobile_type = $parameters["mobile_type"];
                        if (!$qUser->update()) {
                            $messages = $qUser->getMessages();
                            $message = "";
                            foreach ($messages as $error) {
                                $message .= $error;
                            }
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => trim($message) . " (Code AI1002)",
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                        $cache = $session["extension"] . "@" . $session["subdomain"];
                        $cache2 = $session["extension"] . "@@" . $session["subdomain"];
                        $cache3 = $session["extension"] . ":" . $session["subdomain"];
                        $cache4 = $session["extension"] . "@@@" . $session["subdomain"];
                        if ($parameters["type"] != 3) {
                            // REMOVAL OF ALL PUSH TOKENS ON ADROID WITH BELOW AS PLACEHOLDER
                            if (!$pushTokenSubstituted && strpos(strval($parameters["push_token"]), $pushTokenPlaceholder) !== 0) {
                                $pushMember = $parameters["push_token"];
                                if (!empty($parameters["device_uuid"])) {
                                    $pushMember = $parameters["push_token"] . ":" . $parameters["device_uuid"];
                                }
                                if ($this->redis->exists($cache) && strval($this->redis->type($cache)) !== "set") {
                                    $this->redis->del($cache);
                                }
                                try {
                                    // One device id per token: the same app token listed under ids from
                                    // earlier sign-ins made ringPush.js read a stale id and send a stop
                                    // push to a phone that had the call (a blank "RingQ" call on iOS).
                                    foreach ((array) $this->redis->smembers($cache) as $existingMember) {
                                        $existingMember = strval($existingMember);
                                        if ($existingMember !== $pushMember && strpos($existingMember, $parameters["push_token"] . ":") === 0) {
                                            $this->redis->srem($cache, $existingMember);
                                        }
                                    }
                                    $this->redis->sadd($cache, $pushMember);
                                } catch (\Throwable $pushTokenError) {
                                    $this->redis->del($cache);
                                    $this->redis->sadd($cache, $pushMember);
                                }
                            }
                            if (isset($parameters["push_token2"])) {
                                $cache2 = "SSO-". $session["extension"] . "@@" . $session["subdomain"];
                                $this->redis->set($cache2, $parameters["push_token2"]);
                            }
                        }
                        if ($parameters["type"] == 3 || intval($parameters["type"]) == 3) {
                            if (!$pushTokenSubstituted) {
                                $this->redis->set($cache4, $parameters["push_token"]);
                            }
                        }
                        $this->redis->set($cache3, $session["image"]);
                        $qDevice = QDevices::findFirst(
                            [
                                "conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid: AND device_name = :device_name: AND device_type = :device_type:",
                                "bind" =>
                                    [
                                        "domain_uuid" => $session["domain_uuid"],
                                        "user_uuid" => $session["user_uuid"],
                                        "device_name" => $parameters["device_name"],
                                        "device_type" => intval($parameters["type"]),
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT]
                            ]
                        );
                        if ($qDevice) {
                            $qDevice->device_type = intval($parameters["type"]);
                            $qDevice->device_name = $parameters["device_name"];
                            $qDevice->device_version = $parameters["device_version"];
                            $qDevice->extension = $session["extension"];
                            $storedPushToken = trim(strval($qDevice->push_token));
                            if (!$pushTokenSubstituted || $storedPushToken === "" || strpos($storedPushToken, $pushTokenPlaceholder) === 0) {
                                $qDevice->push_token = $parameters["push_token"];
                            }
                            $qDevice->version = $parameters["version"];
                            $qDevice->update_login = date("Y-m-d H:i:s");
                            if (!$qDevice->update()) {
                                $messages = $qDevice->getMessages();
                                $message = "";
                                foreach ($messages as $error) {
                                    $message .= $error;
                                }
                                $response = json_encode(
                                    [
                                        "result" => "error",
                                        "message" => trim($message) . " (Code AI1004)",
                                    ]
                                );
                                $this->response->setContent($response);
                                return $this->response;
                            }
                        } else {
                            $qDevice = new QDevices();
                            $qDevice->domain_uuid = $session["domain_uuid"];
                            $qDevice->user_uuid = $session["user_uuid"];
                            $qDevice->device_type = intval($parameters["type"]);
                            $qDevice->device_name = $parameters["device_name"];
                            $qDevice->device_version = $parameters["device_version"];
                            $qDevice->extension = $session["extension"];
                            $qDevice->push_token = $parameters["push_token"];
                            $qDevice->version = $parameters["version"];
                            $qDevice->insert_date = date("Y-m-d H:i:s");
                            $qDevice->insert_user = $session["user_uuid"];
                            if (!$qDevice->create()) {
                                $messages = $qDevice->getMessages();
                                $message = "";
                                foreach ($messages as $error) {
                                    $message .= $error;
                                }
                                $response = json_encode(
                                    [
                                        "result" => "error",
                                        "message" => trim($message) . " (Code AI1005)",
                                    ]
                                );
                                $this->response->setContent($response);
                                return $this->response;
                            }
                        }
                        // [one-token-one-signin] A push token belongs to one app on one phone, and that app is
                        // signed in to one extension at a time: this one. Rows left from earlier sign-ins (other
                        // extensions, other tenants, other device names) kept ringing the phone for calls it
                        // can't take. Forget the token everywhere else.
                        $ownToken = trim(strval($qDevice->push_token));
                        if ($ownToken !== "" && intval($parameters["type"]) != 3 && strpos($ownToken, $pushTokenPlaceholder) !== 0) {
                            try {
                                $staleDevices = QDevices::find(
                                    [
                                        "conditions" => "push_token = :push_token: AND id <> :id:",
                                        "bind" => ["push_token" => $ownToken, "id" => intval($qDevice->id)],
                                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT]
                                    ]
                                );
                                foreach ($staleDevices as $staleDevice) {
                                    $staleDomain = VDomains::findFirst(
                                        [
                                            "conditions" => "domain_uuid = :domain_uuid:",
                                            "bind" => ["domain_uuid" => $staleDevice->domain_uuid],
                                            "bindTypes" => [Column::BIND_PARAM_STR]
                                        ]
                                    );
                                    if ($staleDomain) {
                                        $staleBase = $staleDevice->extension . "@" . $staleDomain->domain_name;
                                        if ($staleBase !== $session["extension"] . "@" . $session["subdomain"]) {
                                            $this->redis->srem("iosDevicePushToken-" . $staleBase, $ownToken);
                                            $this->redis->srem("iosSucessPushToken-" . $staleBase, $ownToken);
                                            if (strval($this->redis->type($staleBase)) === "set") {
                                                foreach ((array) $this->redis->smembers($staleBase) as $staleMember) {
                                                    if ($staleMember === $ownToken || strpos($staleMember, $ownToken . ":") === 0) {
                                                        $this->redis->srem($staleBase, $staleMember);
                                                    }
                                                }
                                            }
                                            $staleAndroid = "android:" . $staleDevice->extension . ":" . $staleDomain->domain_name;
                                            if ($this->redis->get($staleAndroid) === $ownToken) {
                                                $this->redis->del($staleAndroid);
                                            }
                                        }
                                    }
                                    $staleDevice->delete();
                                }
                            } catch (\Throwable $staleTokenError) {
                                // best effort: never fail the sign-in over cleanup
                            }
                        }
                        try {
                            $this->redis->del("deviceSignedOut:" . $qDevice->id);
                        } catch (\Throwable $signedOutClearError) {
                        }
                        $client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
                            "persistent" => false,
                        ]));
                        $client->initialize();
                        $client->emit("logoutStatus", ["subdomain" => $session["subdomain"], "extension" => $session["extension"], "status" => 1]);
                        $response = json_encode(
                            [
                                "result" => "success",
                                "content" => $qDevice->id,
                                "enabled" => $qDevice->enabled,
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    } else {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "An error has occurred. (Code AI1006)",
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                }
            }
        } else {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Unathorized. (Code AI1004)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
    }

    public function agentactivityAction($page = 1)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
            // ACTIVITY // AGENT, DATE
            if ($this->request->isGet()) {
                $offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                $vUserLog = VUserLogs::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [ Column::BIND_PARAM_STR],
                        "limit" => 20,
                        "offset"=> $offset,
                        'order' => 'insert_date DESC'
                    ]
                );
                $count = VUserLogs::count(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [ Column::BIND_PARAM_STR],
                    ]
                );
                $response = json_encode(
                    [
                        "result" => "success",
                        "content" => $vUserLog,
                        "count" => $count,
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            } else if ($this->request->isPost()) {
                $parameters = array();
                $parameters["page"] = intval($this->request->getPost("page", "int"));
                $parameters["type"] = intval($this->request->getPost("type", "int"));
                if (empty($parameters["page"])) {
                    $contents = file_get_contents("php://input");
                    $parameters = json_decode($contents, true);
                }
                $offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                $vUserLogs = VUserLogs::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [ Column::BIND_PARAM_STR],
                        "limit" => 20,
                        "offset"=> $offset,
                        'order' => 'insert_date DESC'
                    ]
                );
                $count = VUserLogs::count(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [ Column::BIND_PARAM_STR],
                    ]
                );
                $index = 0;
                $content = array();
                foreach ($vUserLogs as $vUserLog) {
                    $content[$index]["date"] = $vUserLog->timestamp;
                    $content[$index]["username"] = $vUserLog->username;
                    $content[$index]["type"] = $vUserLog->type;
                    $content[$index]["result"] = $vUserLog->result;
                    $content[$index]["remote_address"] = $vUserLog->remote_address;
                    $content[$index]["user_agent"] = $vUserLog->user_agent;
                    $index++;
                }
                $security = new \Phalcon\Security\Random();
                $filename = $security->uuid();
                $fp = fopen('/var/www/ringq/cache/'. $filename .'.csv', 'w');
                $header = ["Date", "Username", "Type", "IP address", "User Agent"];
                fputcsv($fp, $header, ",");
                foreach ($content as $fields) { 
                    fputcsv($fp, $fields, ","); 
                }
                header('Content-Type: text/csv');
                header('Content-Disposition: attachment; filename="output.csv";');
                fclose($fp);
                if ($parameters["type"] == 1) {
                    $this->response->setFileToSend("/var/www/ringq/cache/". $filename .".csv", $filename .".csv")->send();
                    if (file_exists("/var/www/ringq/cache/". $filename .".csv")) {
                        unlink("/var/www/ringq/cache/". $filename .".csv");
                    }
                } 
                if ($parameters["type"] == 2) {
                    $this->redis->lpush("report", json_encode(["email" => $session["email"], "file" => $filename .".csv", "domain_uuid" => $session["domain_uuid"]]));
                    $response = json_encode(
                        [
                            "result" => "success",
                            "message" => "Generating reports.",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            }
        }
    }

    public function auxcodesAction($page = 1, $searchTerm = "")
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
            if ($this->request->isGet()) {
                $offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                $qAuxcodes = QAuxcodes::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [ Column::BIND_PARAM_STR],
                        "limit" => 20,
                        "offset"=> $offset,
                        'order' => 'id ASC'
                    ]
                );
                $count = QAuxcodes::count(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [ Column::BIND_PARAM_STR],
                    ]
                );
                $index = 0;
                $content = [];
                foreach ($qAuxcodes as $qAuxcode) {
                    $content[$index]["auxcode_uuid"] = $qAuxcode->auxcode_uuid;
                    $content[$index]["auxcode_status"] = ucfirst($qAuxcode->auxcode_status);
                    $content[$index]["username"] = $qAuxcode->username;
                    $index++;
                }
                $response = json_encode(
                    [
                        "result" => "success",
                        "content" => $content,
                        "count" => $count,
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            } else if ($this->request->isPost()) {
                $this->redis->del('vCallCenterAgents5-' . $session["subdomain"]);
                $parameters = array();
                $parameters["auxcode_type"] = intval($this->request->getPost("auxcode_type", "int"));
                $parameters["auxcode_uuid"] = $this->request->getPost("auxcode_uuid", "string");
                $parameters["auxcode_status"] = $this->request->getPost("auxcode_status", "string");
                $parameters["extension"] = intval($this->request->getPost("extension", "int"));
                $parameters["queue_extension"] = intval($this->request->getPost("queue_extension", "int"));
                if (empty($parameters["auxcode_type"])) {
                    $contents = file_get_contents("php://input");
                    $parameters = json_decode($contents, true);
                }
                if ($parameters["auxcode_type"] == 6) {
                    $qAuxcodes = QAuxcodes::find([
                        "conditions" => "domain_uuid = :domain_uuid:",
