    public function auxcodes2Action($page = 0, $type = 0)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
            // AUXCODES // AGENT, AUXCODE, QUEUE, DATE
            if ($this->request->isGet()) {
                $offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                $qAuxcodesLists = QAuxcodesList::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                        "limit" => 20,
                        "offset"=> $offset,
                        'order' => 'insert_date DESC'
                    ]
                );
                $count = QAuxcodesList::count(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                $index = 0;
                $content = array();
                foreach ($qAuxcodesLists as $qAuxcodesList) {
                    $content[$index]["username"] = $qAuxcodesList->username;
                    $content[$index]["extension"] = $qAuxcodesList->extension;
                    $content[$index]["queue"] = $qAuxcodesList->extension;
                    $content[$index]["insert_date"] = $qAuxcodesList->insert_date;
                    $content[$index]["auxcode_status"] = ucfirst($qAuxcodesList->auxcode_status);
                    $index++;
                }
                $response = json_encode(
                    [
                        "result" => "success",
                        "content" => $content,
                        "count" => $count,
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            } else if ($this->request->isPost()) {
                $parameters = array();
                $parameters["page"] = intval($this->request->getPost("page", "int"));
                $parameters["type"] = intval($this->request->getPost("type", "int"));
                if (empty($parameters["page"])) {
                    $contents = file_get_contents("php://input");
                    $parameters = json_decode($contents, true);
                }
                $offset = $page > 1 ? intval($parameters["page"]) * 20 - 20 : 0;
                $qAuxcodesLists = QAuxcodesList::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                        "limit" => 20,
                        "offset"=> $offset,
                        'order' => 'insert_date DESC'
                    ]
                );
                $count = QAuxcodesList::count(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                $index = 0;
                $content = array();
                foreach ($qAuxcodesLists as $qAuxcodesList) {
                    $content[$index]["username"] = $qAuxcodesList->username;
                    $content[$index]["extension"] = $qAuxcodesList->extension;
                    $content[$index]["insert_date"] = $qAuxcodesList->insert_date;
                    $content[$index]["auxcode_status"] = ucfirst($qAuxcodesList->auxcode_status);
                    $index++;
                }
                $security = new \Phalcon\Security\Random();
                $filename = $security->uuid();
                $fp = fopen('/var/www/ringq/cache/'. $filename .'.csv', 'w');
                $header = ["Username", "Extension", "Date", "Auxcode"];
                fputcsv($fp, $header, ",");
                foreach ($content as $fields) { 
                    fputcsv($fp, $fields, ","); 
                }
                header('Content-Type: text/csv');
                header('Content-Disposition: attachment; filename="output.csv";');
                fclose($fp);
                if ($parameters["type"] == 1) {
                    $this->response->setFileToSend("/var/www/ringq/cache/". $filename .".csv", $filename .".csv")->send();
                    if (file_exists("/var/www/ringq/cache/". $filename .".csv")) {
                        unlink("/var/www/ringq/cache/". $filename .".csv");
                    }
                } 
                if ($parameters["type"] == 2) {
                    $this->redis->lpush("report", json_encode(["email" => $session["email"], "file" => $filename .".csv", "domain_uuid" => $session["domain_uuid"]]));
                    $response = json_encode(
                        [
                            "result" => "success",
                            "message" => "Generating reports.",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            }
        }
    }

    public function callcenterAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        if ($this->request->isGet()) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AC1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AC1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $this->redis->del("allDialplans-" . $session["subdomain"]);
            $this->redis->del("vCallCenterQueues-" . $session["subdomain"]);
            $this->redis->del("vCallCenterAgents-" . $session["subdomain"]);
            $this->redis->del("vCallCenterAgents5-" . $session["subdomain"]);
            $this->redis->del("allVCallCenterTiers-" . $session["subdomain"]);
            $parameters = array();
            $parameters["type"] = $this->request->getPost("type", "string");
            $parameters["queue_name"] = $this->request->getPost("queue_name", "string");
            $parameters["queue_extension"] = intval($this->request->getPost("queue_extension", "int"));
            $parameters["queue_greeting"] = $this->request->getPost("queue_greeting", "string");
            $parameters["queue_strategy"] = $this->request->getPost("queue_strategy", "string");
            $parameters["queue_moh_sound"] = $this->request->getPost("queue_moh_sound", "string");
            $parameters["queue_messsage_on_hold"] = $this->request->getPost("queue_messsage_on_hold", "string");
            $parameters["queue_messsage_on_hold2"] = $this->request->getPost("queue_messsage_on_hold2", "string");
            $parameters["queue_messsage_on_hold3"] = $this->request->getPost("queue_messsage_on_hold3", "string");
            $parameters["queue_messsage_interval"] = intval($this->request->getPost("queue_messsage_interval", "int"));
            $parameters["queue_announce_position"] = intval($this->request->getPost("queue_announce_position", "int"));
            $parameters["queue_time_base_score"] = intval($this->request->getPost("queue_time_base_score", "int"));
            $parameters["queue_time_base_score_sec"] = intval($this->request->getPost("queue_time_base_score_sec", "int"));
            $parameters["agent_call_timeout"] = intval($this->request->getPost("agent_call_timeout", "int")) == 0 ? 0 : intval($this->request->getPost("agent_call_timeout", "int"));
            $parameters["queue_timeout_action"] = intval($this->request->getPost("queue_timeout_action", "int"));
            $parameters["queue_max_wait_time"] = intval($this->request->getPost("queue_max_wait_time", "int"));
            $parameters["queue_max_wait_time_with_no_agent"] = intval($this->request->getPost("queue_max_wait_time_with_no_agent", "int"));
            $parameters["queue_max_wait_time_with_no_agent_time_reached"] = intval($this->request->getPost("queue_max_wait_time_with_no_agent_time_reached", "int"));
            $parameters["queue_tier_rules_apply"] = $this->request->getPost("queue_tier_rules_apply", "string");
            $parameters["queue_wrapup"] = intval($this->request->getPost("queue_wrapup", "int"));
            $parameters["queue_show_contact"] = intval($this->request->getPost("queue_show_contact", "int"));
            $parameters["queue_show_scripts"] = intval($this->request->getPost("queue_show_scripts", "int"));
            $parameters["queue_skill"] = intval($this->request->getPost("queue_skill", "int"));
            $parameters["queue_callback"] = intval($this->request->getPost("queue_callback", "int"));
            $parameters["queue_callback_custom"] = intval($this->request->getPost("queue_callback_custom", "int"));
            // Queue call recording: "0" = use each extension's own setting, "1" = always record,
            // "2" = never record. Null when the client does not send it (older clients, create).
            $parameters["queue_record"] = $this->request->getPost("queue_record", "string");
            $parameters["destination_number"] = $this->request->getPost("destination_number", "string");
            $parameters["queue_sla"] = intval($this->request->getPost("queue_sla", "int"));
            $parameters["agent_wrap_up_time"] = intval($this->request->getPost("agent_wrap_up_time", "int"));
            $parameters["global"] = intval($this->request->getPost("global", "int"));
            $parameters["global2"] = intval($this->request->getPost("global2", "int"));
            $parameters["work_default"] = $this->request->getPost("work_default", "string");
            $parameters["break_default"] = $this->request->getPost("break_default", "string");
            $parameters["work_schedules"] = $this->request->getPost("work_schedules", "string");
            $parameters["break_schedules"] = $this->request->getPost("break_schedules", "string");
            $parameters["content"] = $this->request->getPost("content", "string");
            $parameters["queue_max_callers"] = intval($this->request->getPost("queue_max_callers", "int"));
            $parameters["queue_auto_answer"] = intval($this->request->getPost("queue_auto_answer", "int"));
            $parameters["queue_sla_notify"] = intval($this->request->getPost("queue_sla_notify", "int"));
            $parameters["queue_callback_success"] = intval($this->request->getPost("queue_callback_success", "int"));
            $parameters["queue_callback_fail"] = intval($this->request->getPost("queue_callback_fail", "int"));
            $parameters["queue_call_lost"] = intval($this->request->getPost("queue_call_lost", "int"));
            $parameters["queue_call_landing"] = $this->request->getPost("queue_call_landing", "string");
            $parameters["queue_call_landing2"] = $this->request->getPost("queue_call_landing2", "string");
            $parameters["queue_call_landing_url"] = $this->request->getPost("queue_call_landing_url", "string");
            $parameters["click2talk_mode"] = intval($this->request->getPost("click2talk_mode", "string"));
            $parameters["facebook_chat"] = $this->request->getPost("facebook_chat", "string");
            $parameters["whatsapp_chat"] = $this->request->getPost("whatsapp_chat", "string");
            $parameters["webchat_chat"] = $this->request->getPost("webchat_chat", "string");
            $parameters["line_chat"] = $this->request->getPost("line_chat", "string");
            $parameters["telegram_chat"] = $this->request->getPost("telegram_chat", "string");
            $parameters["telnyx_chat"] = $this->request->getPost("telnyx_chat", "string");
            $parameters["twilio_chat"] = $this->request->getPost("twilio_chat", "string");
            if (empty($parameters["queue_extension"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            $queueNameKept = ($parameters["type"] ?? null) == 2
                && ($storedQueueName = QueueName::storedName($this->db, $session["domain_uuid"], $parameters["queue_extension"] ?? null)) !== null
                && trim($storedQueueName) === trim((string)($parameters["queue_name"] ?? ""));
            if (($parameters["type"] ?? null) != 3 && !$queueNameKept) {
                $queueNameError = QueueName::formatError($parameters["queue_name"] ?? "");
                if ($queueNameError === null && QueueName::isTaken($this->db, $session["domain_uuid"], $parameters["queue_name"], $parameters["type"] == 1 ? null : ($parameters["queue_extension"] ?? null))) {
                    $queueNameError = "A queue with this name already exists.";
                }
                if ($queueNameError !== null) {
                    $this->response->setContent(json_encode([
                        "result" => "error",
                        "message" => $queueNameError . " (Code AQ1002)",
                        "content" => [],
                    ]));
                    return $this->response;
                }
                $parameters["queue_name"] = trim((string)$parameters["queue_name"]);
            }
            $callcenterForm = new CallcenterForm();
            $callcenterDeleteForm = new CallcenterDeleteForm();
            if ($parameters["type"] != 3) {
                // The name was checked above (QueueName, 2-15 characters); CallcenterForm (encoded)
                // still asks for 4-100, so it gets a stand-in name and checks the other fields.
                $callcenterFormParameters = $parameters;
                $callcenterFormParameters["queue_name"] = "Queue";
                if (!$callcenterForm->isValid($callcenterFormParameters)) {
                    $messages = $callcenterForm->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AQ1002)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            } else {
                if (!$callcenterDeleteForm->isValid($parameters)) {
                    $messages = $callcenterDeleteForm->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AQ1002)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $scriptsForm = new ScriptsForm();
                if (!$scriptsForm->isValid($parameters)) {
                    $messages = $scriptsForm->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AQ1002)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            }
            if (!isset($parameters["click2talk_mode"])) {
                $parameters["click2talk_mode"] = 1;
            }
            $vExtensions = VExtensions::find(
                [
                    "conditions" => "domain_uuid = :domain_uuid:",
                    "bind" =>
                        [
                            "domain_uuid" => $session["domain_uuid"],
                        ],
                    "bindTypes" => [Column::BIND_PARAM_STR],
                ]
            );
            $this->redis->del("queueAgents@". $session["subdomain"]);
            foreach($vExtensions as $vExtension) {
                $this->redis->lpush("queueAgents@". $session["subdomain"], $vExtension->extension);
            }
            if ($parameters["type"] == 1) {
                $this->db->begin();
                $nextExtension = VCallCenterQueues::maximum(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "column" => "queue_extension",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                if ($nextExtension) {
                    $queue_extension = $nextExtension + 1;
                } else {
                    $queue_extension = 9000;
                }
                if ($parameters["queue_extension"] != 0) {
                    $queue_extension = $parameters["queue_extension"];
                }
                $vCallCenterQueue = VCallCenterQueues::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND queue_extension = :queue_extension:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "queue_extension" => $queue_extension
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                    ]
                );
                if ($vCallCenterQueue) {
                    $this->db->rollback();
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Sorry, queue extension already existing. (Code AQ1005)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $application_data = "";
                $queue_timeout_action = "";
                $queue_timeout_action_xml = "";
                if (!empty($parameters["queue_type"])) {
                    if ($parameters["queue_type"] == 1) {
                        $application_data = "transfer";
                        $queue_timeout_action_xml = $parameters["queue_timeout_action"] ." XML ". $session["subdomain"];
                        $queue_timeout_action = $application_data . ":". $parameters["queue_timeout_action"] ." XML ". $session["subdomain"];
                    } else if ($parameters["queue_type"] == 2) {
                        $application_data = "transfer";
                        $queue_timeout_action_xml = "*99". $parameters["queue_timeout_action"] ." XML ". $session["subdomain"];
                        $queue_timeout_action = $application_data . ":*99". $parameters["queue_timeout_action"] ." XML ". $session["subdomain"];
                    } else if ($parameters["queue_type"] == 3) {
                        $application_data = "hangup";
                        $queue_timeout_action = "hangup:";
                    }
                }
                $parameters["queue_extension"] = $queue_extension;
                $vCallCenterQueue = new VCallCenterQueues();
                $security = new \Phalcon\Security\Random();
                $dialplan_uuid = $security->uuid();
                $call_center_queue_uuid = $security->uuid();
                $vCallCenterQueue->call_center_queue_uuid = $call_center_queue_uuid;
                $vCallCenterQueue->domain_uuid = $session["domain_uuid"];
                $vCallCenterQueue->dialplan_uuid = $dialplan_uuid;
                $vCallCenterQueue->queue_name = $parameters["queue_name"];
                $vCallCenterQueue->queue_extension = strval($parameters["queue_extension"]);
                if (!empty($parameters["queue_greeting"])) {
                    $vCallCenterQueue->queue_greeting = "/var/www/ringq/public/audio/". $parameters["queue_greeting"];
                }
                $vCallCenterQueue->queue_moh_sound = "local_stream://default";
                if (!empty($parameters["queue_moh_sound"])) {
                    $vCallCenterQueue->queue_moh_sound = "/var/www/ringq/public/audio/". $parameters["queue_moh_sound"];
                }
                $queue_messsage_on_hold = "";
                $queue_messsage_on_hold2 = "";
                $queue_messsage_on_hold3 = "";
                $vCallCenterQueue->queue_messsage_on_hold = null;
                if (!empty($parameters["queue_messsage_on_hold"])) {
                    $queue_messsage_on_hold = $parameters["queue_messsage_on_hold"];
                    $vCallCenterQueue->queue_messsage_on_hold = "/var/www/ringq/public/audio/". $parameters["queue_messsage_on_hold"];
                }
                $vCallCenterQueue->queue_messsage_on_hold2 = null;
                if (!empty($parameters["queue_messsage_on_hold2"])) {
                    $queue_messsage_on_hold2 = $parameters["queue_messsage_on_hold2"];
                    $vCallCenterQueue->queue_messsage_on_hold2 = "/var/www/ringq/public/audio/". $parameters["queue_messsage_on_hold2"];
                }
                $vCallCenterQueue->queue_messsage_on_hold3 = null;
                if (!empty($parameters["queue_messsage_on_hold3"])) {
                    $queue_messsage_on_hold3 = $parameters["queue_messsage_on_hold3"];
                    $vCallCenterQueue->queue_messsage_on_hold3 = "/var/www/ringq/public/audio/". $parameters["queue_messsage_on_hold3"];
                }
                if (!empty($parameters["queue_messsage_interval"])) {
                    $vCallCenterQueue->queue_messsage_interval = intval($parameters["queue_messsage_interval"]) == 0 ? null : intval($parameters["queue_messsage_interval"]);
                }
                $vCallCenterQueue->queue_announce_frequency = isset($parameters["queue_announce_frequency"]) ? intval($parameters["queue_announce_frequency"]) : null;
                $description = [0, 0, 60, 0, 0, 0];
                if (intval($parameters["agent_wrap_up_time"]) > 0) {
                  $description[0] = $parameters["agent_wrap_up_time"];
                } else {
                  $description[0] = "0";
                }
                if (intval($parameters["queue_sla"]) > 0) {
                  $description[1] = $parameters["queue_sla"];
                } else {
                  $description[1] = "0";
                }
                if (isset($parameters["agent_call_timeout"])) {
                  $description[2] = $parameters["agent_call_timeout"];
                } else {
                  $description[2] = "0";
                }
                if (intval($parameters["queue_wrapup"]) > 0) {
                  $description[3] = $parameters["queue_wrapup"];
                  $this->redis->hset("queueSettings". $parameters["queue_extension"] ."@". $session["subdomain"], "wrap_up", $parameters["queue_wrapup"]);
                } else {
                  $this->redis->hset("queueSettings". $parameters["queue_extension"] ."@". $session["subdomain"], "wrap_up", 0);
                }
                if (intval($parameters["queue_show_contact"]) > 0) {
                  $description[4] = $parameters["queue_show_contact"];
                  $this->redis->hset("queueSettings". $parameters["queue_extension"] ."@". $session["subdomain"], "queue_show_contact", $parameters["queue_show_contact"]);
                } else {
                    $this->redis->hset("queueSettings". $parameters["queue_extension"] ."@". $session["subdomain"], "queue_show_contact", 0);
                }
                if (intval($parameters["queue_show_scripts"] ) > 0) {
                  $description[5] = $parameters["queue_show_scripts"];
                  $this->redis->hset("queueSettings". $parameters["queue_extension"] ."@". $session["subdomain"], "queue_script", 1);
                } else {
                  $this->redis->hset("queueSettings". $parameters["queue_extension"] ."@". $session["subdomain"], "queue_script", 0);
                }
                if (!empty($parameters["queue_callback"])) {
                    if (intval($parameters["queue_callback"]) == 2) {
                        $this->redis->set($parameters["queue_extension"] ."@". $session["subdomain"] ."-callBack", "1");
                    } else {
                        $this->redis->del($parameters["queue_extension"] ."@". $session["subdomain"] ."-callBack");
                    }
                }
                if (!empty($parameters["queue_callback_custom"])) {
                    if (intval($parameters["queue_callback_custom"]) == 2) {
                        $this->redis->set($parameters["queue_extension"] ."@". $session["subdomain"] ."-callBackCustom", "1");
                    } else {
                        $this->redis->del($parameters["queue_extension"] ."@". $session["subdomain"] ."-callBackCustom");
                    }
                }
                if (!empty($parameters["queue_call_landing"])) {
                    $this->redis->set($parameters["queue_extension"] ."@". $session["subdomain"] ."-queue_call_landing", $parameters["queue_call_landing"]);
                }   else {
                    $this->redis->set($parameters["queue_extension"] ."@". $session["subdomain"] ."-queue_call_landing", "Do Nothing");
                }
                if (!empty($parameters["queue_call_landing2"])) {
                    $this->redis->set($parameters["queue_extension"] ."@". $session["subdomain"] ."-queue_call_landing2", $parameters["queue_call_landing2"]);
                }   else {
                    $this->redis->set($parameters["queue_extension"] ."@". $session["subdomain"] ."-queue_call_landing2", "Do Nothing");
                }
                if (!empty($parameters["queue_call_landing_url"])) {
                    $this->redis->set($parameters["queue_extension"] ."@". $session["subdomain"] ."-queue_call_landing_url", $parameters["queue_call_landing_url"]);
                }   else {
                    $this->redis->set($parameters["queue_extension"] ."@". $session["subdomain"] ."-queue_call_landing_url", "");
                }
                $vCallCenterQueue->queue_description = implode("-", $description);
                $vCallCenterQueue->queue_strategy = strtolower(str_replace(" ", "-", $parameters["queue_strategy"]));
                $vCallCenterQueue->queue_record_template = '/var/lib/freeswitch/recordings/'. $session["subdomain"] .'/archive/${strftime(%Y)}/${strftime(%b)}/${strftime(%d)}/${uuid}.${record_ext}';
                $vCallCenterQueue->queue_time_base_score = "system";
                $vCallCenterQueue->queue_time_base_score_sec = intval($parameters["queue_time_base_score_sec"]);
                $vCallCenterQueue->queue_max_wait_time = intval($parameters["queue_max_wait_time"]);
                $vCallCenterQueue->queue_announce_position = intval($parameters["queue_announce_position"]);
                $vCallCenterQueue->queue_max_wait_time_with_no_agent = intval($parameters["queue_max_wait_time"]);
                $vCallCenterQueue->queue_max_wait_time_with_no_agent_time_reached = intval($parameters["queue_max_wait_time"]);
                $vCallCenterQueue->queue_timeout_action = $queue_timeout_action;
                $vCallCenterQueue->queue_discard_abandoned_after = 900;
                $vCallCenterQueue->queue_tier_rules_apply = isset($parameters["queue_skill"]) && intval($parameters["queue_skill"]) == 1 ? "true" : "false";
                $vCallCenterQueue->queue_tier_rule_wait_second = 15;
                $vCallCenterQueue->queue_tier_rule_wait_multiply_level = "true";
                $vCallCenterQueue->queue_tier_rule_no_agent_no_wait = "true";
                $vCallCenterQueue->queue_abandoned_resume_allowed = "false";
                $vCallCenterQueue->queue_cid_prefix = null;
                $vCallCenterQueue->queue_cc_exit_keys = null;
                $vCallCenterQueue->insert_user = $session["user_uuid"];
                $vCallCenterQueue->insert_date = date("Y-m-d H:i:s");
                if (!$vCallCenterQueue->create()) {
                    $this->db->rollback();
                    $messages = $vCallCenterQueue->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AQ1003)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                } else {
                    $vDialplan = new VDialplans();
                    $vDialplan->domain_uuid = $session["domain_uuid"];
                    $vDialplan->dialplan_uuid = $dialplan_uuid;
                    $vDialplan->dialplan_name = $parameters["queue_name"];
                    $vDialplan->dialplan_number = $parameters["queue_extension"];
                    $vDialplan->dialplan_context = $session["subdomain"];
                    $vDialplan->dialplan_continue = "false";
                    $timeBasedScore = $vCallCenterQueue->queue_time_base_score_sec != 0 ? '<action application="set" data="cc_base_score='. $vCallCenterQueue->queue_time_base_score_sec .'"/>' : "";
                    $queue_greeting = "";
                    if (!empty($parameters["queue_greeting"])) {
                        $queue_greeting = '<action application="playback" data="'. "/var/www/ringq/public/audio/". $parameters["queue_greeting"] .'"/>';
                    }
                    $queue_announce_position = "";
                    if (intval($parameters["queue_announce_position"]) != 0) {
                       $queue_announce_position = '<action application="set" data="result=${luarun(callcenter-announce-position.lua ${uuid} '. $parameters["queue_extension"] .'@'. $session["subdomain"] .' '. (intval($parameters["queue_announce_position"]) - 1) * 1000 .')}"/>';
