                    $client->emit("reloadqueue", ["extension" => $parameters["queue_extension"], "subdomain" => $session["subdomain"], "queue_reload" => $queueRecordReload ? 1 : 0]);
                    $client->emit("broadcast4", ["extension" => $parameters["queue_extension"], "subdomain" => $session["subdomain"], "wrap_up" => intval($parameters["queue_wrapup"]), "queue_script" => intval($parameters["queue_show_scripts"])]);
                    $response = json_encode(
                        [
                            "result" => "success",
                            "message" => "Successfully, updated queue.",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            }
            if ($parameters["type"] == 3) {
                $this->db->begin();
                if (array_key_exists("destination_number",$parameters) && !empty($parameters["destination_number"])) {
                    $destinationForm = new DestinationForm();
                    if (!$destinationForm->isValid($parameters)) {
                        $messages = $destinationForm->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AQ1005)",
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    } else {
                        $vDestination = VDestinations::findFirst(
                            [
                                "conditions" => "domain_uuid = :domain_uuid: AND destination_number = :destination_number:",
                                "bind" =>
                                    [
                                        "domain_uuid" => $session["domain_uuid"],
                                        "destination_number" => $parameters["destination_number"]
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                            ]
                        );
                        if ($vDestination) {
                            if (!$vDestination->delete()) {
                                $this->db->rollback();
                                $messages = $vDestination->getMessages();
                                $message = "";
                                foreach ($messages as $error) {
                                    $message .= $error . " ";
                                }
                                $response = json_encode(
                                    [
                                        "result" => "error",
                                        "message" => trim($message) . " (Code AQ1006)",
                                        "content" => [],
                                    ]
                                );
                                $this->response->setContent($response);
                                return $this->response;
                            }
                            $vDialplan = VDialplans::findFirst(
                                [
                                    "conditions" => "domain_uuid = :domain_uuid: AND dialplan_uuid = :dialplan_uuid:",
                                    "bind" =>
                                        [
                                            "domain_uuid" => $session["domain_uuid"],
                                            "dialplan_uuid" => $vDestination->dialplan_uuid
                                        ],
                                    "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                                ]
                            );
                            if (!$vDialplan) {
                                $this->db->rollback();
                                $response = json_encode(
                                    [
                                        "result" => "error",
                                        "message" => "Sorry, Callcenter dialplan non-existing or already been deleted. (Code AQ1007)",
                                        "content" => [],
                                    ]
                                );
                                $this->response->setContent($response);
                                return $this->response;
                            }
                        }
                    }
                }
                $vCallCenterQueue = VCallCenterQueues::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND queue_extension = :queue_extension:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "queue_extension" => $parameters["queue_extension"]
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                    ]
                );
                if (!$vCallCenterQueue) {
                    $this->db->rollback();
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Queue non-existing (Code AQ1007)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                if (!$vCallCenterQueue->delete()) {
                    $this->db->rollback();
                    $messages = $vCallCenterQueue->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AQ1008)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $vCallCenterTiers = VCallCenterTiers::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND call_center_queue_uuid = :call_center_queue_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "call_center_queue_uuid" => $vCallCenterQueue->call_center_queue_uuid
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                    ]
                );
                $client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
                    "persistent" => false,
                ]));
                $client->initialize();
                foreach ($vCallCenterTiers as $vCallCenterTier) {
                    if (!$vCallCenterTier->delete()) {
                        $this->db->rollback();
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Sorry, Queue entries cannot be deleted. (Code AQ1009)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $client->emit("deletetier", ["extension" => $parameters["queue_extension"], "subdomain" => $session["subdomain"], "agent" => $vCallCenterTier->call_center_agent_uuid]);
                }
                $vDialplans = VDialplans::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND dialplan_number = :dialplan_number:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "dialplan_number" => $parameters["queue_extension"]
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                    ]
                );
                if (!$vDialplans) {
                    $this->db->rollback();
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Queue non-existing (Code AQ1010)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                foreach($vDialplans as $vDialplan) {
                    if (!$vDialplan->delete()) {
                        $this->db->rollback();
                        $messages = $vDialplan->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AQ1011)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $vDialplanDetails = VDialplanDetails::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND dialplan_uuid = :dialplan_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "dialplan_uuid" => $vDialplan->dialplan_uuid
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    foreach ($vDialplanDetails as $vDialplanDetail) {
                        if (!$vDialplanDetail->delete()) {
                            $this->db->rollback();
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => "Sorry, Queue entries cannot be deleted. (Code AQ1012)",
                                    "content" => [],
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                    }
                }
                $qTimeSchedule = QTimeSchedules::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                if ($qTimeSchedule) {
                    $workExtensions = array();
                    $breakExtensions = array();
                    $work2Extensions = array();
                    $break2Extensions = array();
                    if ($qTimeSchedule->work_extensions) {
                        $workExtensions = explode(",", $qTimeSchedule->work_extensions);
                        $workExtensions2 = array_diff($workExtensions, array($parameters["queue_extension"]));
                        $qTimeSchedule->work_extensions = !empty($workExtensions2) ? implode(",", $workExtensions2) : "";
                    }
                    if ($qTimeSchedule->break_extensions) {
                        $breakExtensions = explode(",", $qTimeSchedule->break_extensions);
                        $breakExtensions2 = array_diff($breakExtensions, array($parameters["queue_extension"]));
                        $qTimeSchedule->break_extensions = !empty($breakExtensions2) ? implode(",", $breakExtensions2) : "";
                    }
                    if (!empty($workExtensions) || !empty($breakExtensions)) {
                        if (!$qTimeSchedule->update()) {
                            $this->db->rollback();
                            $messages = $qTimeSchedule->getMessages();
                            $message = "";
                            foreach ($messages as $error) {
                                $message .= $error . " ";
                            }
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => trim($message) . " (Code AS1001)",
                                    "content" => [],
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                    }
                }
                $qScript = QScripts::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension: ",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "extension" => $parameters["queue_extension"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                    ]
                );
                if ($qScript) {
                    if (!$qScript->delete()) {
                        $this->db->rollback();
                        $messages = $qScript->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AS1002)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                }
                $qQueueNotification = QQueueNotifications::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND queue_extension =:queue_extension:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "queue_extension" => intval($parameters["queue_extension"])
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                    ]
                );
                if ($qQueueNotification) {
                    if (!$qQueueNotification->delete()) {
                        $this->db->rollback();
                        $messages = $qQueueNotification->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AS1003)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                }
                $qCallQueue = QCallQueues::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND queue_uuid = :queue_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "queue_uuid" => $vCallCenterQueue->call_center_queue_uuid,
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if ($qCallQueue) {
                    if (!$qCallQueue->delete()) {
                        $this->db->rollback();
                        $messages = $qCallQueue->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AS1003)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                }
                if (file_exists("/var/cache/fusionpbx/dialplan.". $session["subdomain"])) {
                    unlink("/var/cache/fusionpbx/dialplan.". $session["subdomain"]);
                }
                if (file_exists("/var/cache/fusionpbx/configuration.callcenter.conf.". gethostname())) {
                    unlink("/var/cache/fusionpbx/configuration.callcenter.conf.". gethostname());
                }
                if (file_exists("/var/cache/ringq/dialplan.". $session["subdomain"])) {
                    unlink("/var/cache/ringq/dialplan.". $session["subdomain"]);
                }
                if (file_exists("/var/cache/ringq/configuration.callcenter.conf.". gethostname())) {
                    unlink("/var/cache/ringq/configuration.callcenter.conf.". gethostname());
                }
                $this->redis->set("callboardReset-". $session["subdomain"], 1);
                $this->redis->del($parameters["queue_extension"] ."@". $session["subdomain"] ."-facebook-chat");
                $this->db->commit();
                $client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
                    "persistent" => false,
                ]));
                $client->emit("reloadqueue", ["extension" => $parameters["queue_extension"], "subdomain" => $session["subdomain"]]);
                $nextExtension = 9000;
                $maximumExtension = VCallCenterQueues::maximum(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "column" => "queue_extension",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                if ($maximumExtension) {
                    $nextExtension = $maximumExtension + 1;
                } else {
                    $nextExtension = 9000;
                }
                $response = json_encode(
                    [
                        "result" => "success",
                        "message" => "Successfully, deleted queue.",
                        "content" => strval($nextExtension),
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
        }
    }

    public function callcostAction($type = 1, $page = 1)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
            if ($this->request->isGet()) {
                $offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                $vCallCenterAgent = VCallCenterAgents::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "user_uuid" => $session["user_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                $timestamp = $this->redis->get($session["extension"] ."@". $session["subdomain"] ."-deletion");
                if (!isset($timestamp)) {
                    $timestamp = 0;
                }
                if ($type == 1) {
                    $vXmlCdr = QRingqCdr::find(
                        [
                            "conditions" => "(caller_id_number = :extension: OR caller_destination = :extension: OR cc_agent = :cc_agent: OR source_number = :extension:) AND caller_id_number != caller_destination AND source_number is not NULL AND (caller_id_number != :extension: OR caller_destination != :extension: OR cc_agent != :cc_agent:  OR source_number = :extension:) AND domain_uuid = :domain_uuid: AND start_epoch > :start_epoch: AND direction = :direction: AND duration is not NULL",
                            "columns" => "direction, start_stamp, answer_stamp, start_epoch, answer_epoch, end_stamp, end_epoch, caller_id_name, caller_id_number, caller_destination, destination_number, duration, voicemail_message, missed_call, waitsec, hangup_cause, source_number, record_name",
                            "bind" =>
                                [
                                    "extension" => $session["extension"],
                                    "domain_uuid" => $session["domain_uuid"],
                                    "cc_agent" => $vCallCenterAgent->call_center_agent_uuid,
                                    "start_epoch" => $timestamp,
                                    "direction" => "outbound",
                                ],
                            "bindTypes" => [Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT, Column::BIND_PARAM_STR],
                            "limit" => 20,
                            "offset"=> $offset,
                            'order' => 'insert_date DESC'
                        ]
                    );
                    $count = QRingqCdr::count(
                        [
                            "conditions" => "(caller_id_number = :extension: OR caller_destination = :extension: OR cc_agent = :cc_agent: OR source_number = :extension:) AND caller_id_number != caller_destination AND source_number is not NULL AND domain_uuid = :domain_uuid: AND start_epoch > :start_epoch: AND direction = :direction: AND duration is not NULL",
                            "bind" =>
                                [
                                    "extension" => $session["extension"],
                                    "domain_uuid" => $session["domain_uuid"],
                                    "cc_agent" => $vCallCenterAgent->call_center_agent_uuid,
                                    "start_epoch" => $timestamp,
                                    "direction" => "outbound",
                                ],
                            "bindTypes" => [Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT, Column::BIND_PARAM_STR],
                        ]
                    );
                }
                if ($type == 2) {
                    $vXmlCdr = QRingqCdr::find(
                        [
                            "conditions" => "(caller_destination = :extension: OR cc_agent = :cc_agent: OR source_number = :extension:) AND caller_id_number != caller_destination AND source_number is not NULL AND domain_uuid = :domain_uuid: AND missed_call = true AND start_epoch > :start_epoch: AND direction = :direction: AND duration is not NULL",
                            "columns" => "direction, start_stamp, answer_stamp, start_epoch, answer_epoch, end_stamp, end_epoch, caller_id_name, caller_id_number, caller_destination, destination_number, duration, voicemail_message, missed_call, waitsec, hangup_cause, source_number, record_name",
                            "bind" =>
                                [
                                    "extension" => $session["extension"],
                                    "domain_uuid" => $session["domain_uuid"],
                                    "cc_agent" => $vCallCenterAgent->call_center_agent_uuid,
                                    "start_epoch" => $timestamp,
                                    "direction" => "outbound",
                                ],
                            "bindTypes" => [Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT, Column::BIND_PARAM_STR],
                            "limit" => 20,
                            "offset"=> $offset,
                            'order' => 'insert_date DESC'
                        ]
                    );
                    $count = QRingqCdr::count(
                        [
                            "conditions" => "(caller_destination = :extension: OR cc_agent = :cc_agent: OR source_number = :extension:) AND caller_id_number != caller_destination AND source_number is not NULL AND domain_uuid = :domain_uuid: AND missed_call = true AND start_epoch > :start_epoch: AND direction = :direction: AND duration is not NULL",
                            "bind" =>
                                [
                                    "extension" => $session["extension"],
                                    "domain_uuid" => $session["domain_uuid"],
                                    "cc_agent" => $vCallCenterAgent->call_center_agent_uuid,
                                    "start_epoch" => $timestamp,
                                    "direction" => "outbound",
                                ],
                            "bindTypes" => [Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT, Column::BIND_PARAM_STR],
                        ]
                    );
                }
                if ($type == 3) {
                    $vXmlCdr = QRingqCdr::find(
                        [
                            "conditions" => "source_number is not NULL AND domain_uuid = :domain_uuid: AND direction = :direction: AND duration is not NULL",
                            "columns" => "direction, start_stamp, answer_stamp, start_epoch, answer_epoch, end_stamp, end_epoch, caller_id_name, caller_id_number, caller_destination, destination_number, duration, voicemail_message, missed_call, waitsec, hangup_cause, source_number, record_name",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "direction" => "outbound",
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                            "limit" => 20,
                            "offset"=> $offset,
                            'order' => 'insert_date DESC'
                        ]
                    );
                    $count = QRingqCdr::count(
                        [
                            "conditions" => "source_number is not NULL AND domain_uuid = :domain_uuid: AND direction = :direction: AND duration is not NULL",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "direction" => "outbound",
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    $response = json_encode(
                        [
                            "result" => "success",
                            "content" => $vXmlCdr,
                            "count" => $count,
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                // CALL COST // AGENT, DATE
                if ($type == 4) {
                    $vXmlCdr = QCallCost::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                            "limit" => 20,
                            "offset"=> $offset,
                            'order' => 'callStart DESC'
                        ]
                    );
                    $count = QCallCost::count(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                        ]
                    );
                    $response = json_encode(
                        [
                            "result" => "success",
                            "content" => $vXmlCdr,
                            "count" => $count,
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }

                $content = [
                    "callLogs" => $vXmlCdr,
                    "count" => $count
                ];
                $response = json_encode(
                    [
                        "result" => "success",
                        "content" => $content,
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            } else if ($this->request->isPost()) {
                if ($type == 1 || $type == 2) {
                    $parameters["page"] = intval($this->request->getPost("page", "int"));
                    if (empty($parameters["page"])) {
                        $contents = file_get_contents("php://input");
                        $parameters = json_decode($contents, true);
                    }
                    $offset = $page > 1 ? intval($parameters["page"]) * 20 - 20 : 0;
                    $vXmlCdrs = QRingqCdr::find(
                        [
                            "conditions" => "source_number is not NULL AND domain_uuid = :domain_uuid:",
                            "columns" => "direction, start_stamp, answer_stamp, start_epoch, answer_epoch, end_stamp, end_epoch, caller_id_name, caller_id_number, caller_destination, destination_number, duration, voicemail_message, missed_call, waitsec, hangup_cause, source_number",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                            "limit" => 20,
                            "offset"=> $offset,
                            'order' => 'insert_date DESC'
                        ]
                    );
                    $count = QRingqCdr::count(
                        [
                            "conditions" => "source_number is not NULL AND domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                        ]
                    );
                    $index = 0;
                    $content = array();
                    foreach ($vXmlCdrs as $vXmlCdr) {
                        $content[$index]["date"] = $vXmlCdr->start_stamp;
                        $content[$index]["time"] = $vXmlCdr->start_stamp;
                        $content[$index]["caller"] = $vXmlCdr->caller_id_number;
                        $content[$index]["caller_name"] = $vXmlCdr->caller_id_name;
                        $content[$index]["caller"] = $vXmlCdr->insert_date;
                        $content[$index]["customer"] = $vXmlCdr->customer;
                        $content[$index]["destination"] = $vXmlCdr->caller_destination;
                        $content[$index]["duration"] = $vXmlCdr->duration;
                        $index++;
                    }
                    $security = new \Phalcon\Security\Random();
                    $filename = $security->uuid();
                    $fp = fopen('/var/www/ringq/cache/'. $filename .'.csv', 'w');
                    $header = ["Date", "Time", "Extension", "Caller Name", "Caller Number", "Caller", "Customer", "Destination", "Duration"];
                    fputcsv($fp, $header, ",");
                    foreach ($content as $fields) { 
                        fputcsv($fp, $fields, ","); 
                    }
                    header('Content-Type: text/csv');
                    header('Content-Disposition: attachment; filename="output.csv";');
                    fclose($fp);
                    if ($parameters["type"] == 1) {
                        $this->response->setFileToSend("/var/www/ringq/cache/". $filename .".csv", $filename .".csv")->send();
                        if (file_exists("/var/www/ringq/cache/". $filename .".csv")) {
                            unlink("/var/www/ringq/cache/". $filename .".csv");
                        }
                    } 
                    if ($parameters["type"] == 2) {
