            if (!$vCallCenterQueue) {
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => "Queue non-existing (Code ACA1002)",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            $this->db->begin();
            if ($parameters["extensions"]) {
                $security = new \Phalcon\Security\Random();
                $extensions = explode(",", $parameters["extensions"]);
                $extensions2 = [];
                $positions = explode(",", $parameters["tier_position"]);
                $tiers = explode(",", $parameters["tier_level"]);
