    public function debugAction($type = 2)
    {
        error_log("Debug action called with type: " . $type);
        // 1 start
        // 2 stop

        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        if ($this->request->isPost()) {
            $session = $this->session->get("auth");
            if ($session != null) {
                if ($this->redis->exists('sip-pcap.service') == false) {
                    $this->redis->set('sip-pcap.service', $type);
                }

                if ($type == '1') {
                    exec('sudo /usr/bin/systemctl start sip-pcap.service 2>&1', $output);
                } else {
                    exec('sudo /usr/bin/systemctl stop sip-pcap.service 2>&1', $output);
                }

                $this->redis->set('sip-pcap.service', $type);

                $response = [
                    "result" => "success",
                    "message" => $type == '1' ? "Callflow debug has started" : "Callflow debug has ended",
                    "content" => [],
                ];

                $this->response->setContent(json_encode($response));
                return $this->response;
            }
        }
    }

