    public function chatsAction($type = 1, $page = 1, $username = "", $count = 40)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
    
        $session  = $this->session->get("auth");
        $username = $this->filter->sanitize($username, "string");
        // $count = 40;
        if ($session && $this->request->isGet()) {
            $elementsPerMessage = 5;
            $limit  = intval($count) * $elementsPerMessage; // total Redis elements per page
            $offset = ($page - 1) * $limit;                // starting index
            $end    = $offset + $limit - 1;                // ending index
         
            $pageCounter = $page;
            // pick correct key based on type
            switch ($type) {
                case 1: $key = $session["subdomain"] . "-external-" . $username; break;
                case 2: $key = "whatsapp:919894340047:" . $username; break;
                case 3: $key = "facebook:919894340047:" . $username; break;
                default: $key = null;
            }
    
            if ($key) {
                $totalItems = $this->redis->llen($key);
                if ($totalItems) {
                    $totalPages = ceil($totalItems / $limit);
                    $content    = $this->redis->lrange($key, $offset, $end);
    
                    $hasMore = $offset <= $totalItems;
                    $next    = $hasMore ? true : false;
                    if($next === true){
                        $page + 1;
                    }
                    $data = [
                        "result"  => "success",
                        "content" => $content,
                        "next"    => $next,
                        "hasMore" => $hasMore,
                        "key"     => $key,
                        "count"   => count($content),
                        "page"    => $page,
                        "total"   => $totalItems,
                        "offset"  => $offset,
                        "end"     => $end,
                        "pageCounter"   => $pageCounter,
                        "throw" => $count,
                    ];
                    $this->response->setContent(json_encode($data));
                    return $this->response;
                }
            }
    
            // fallback
            $this->response->setContent(json_encode([
                "result"  => "success",
                "content" => [],
                "next"    => false,
                "hasMore" => false,
                "count"   => 0,
                "page"    => $page,
                "total"   => 0,
                "key"     => $key ?? null,
                "offset"  => $offset,
                "end"     => $end,
                "throw" => $count,
            ]));
            return $this->response;
        }
    }

