    // The mobile app's update popup: which store build is current and which is
    // the oldest still allowed. Shipped with the central update
    // (app/config/app-version.php; the sandbox deploy ships PHP under app/ but
    // no .json), so sandbox servers announce a new app before production does.
    // Open to signed-in and signed-out callers: nothing private in it.
    public function appversionAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-cache");
        $file = APP_PATH . "/config/app-version.php";
        $data = is_readable($file) ? include $file : null;
        if (!is_array($data)) {
            $data = [];
        }
        $out = ["result" => "success", "note" => (string) ($data["note"] ?? "")];
        foreach (["ios", "android"] as $os) {
            $p = is_array($data[$os] ?? null) ? $data[$os] : [];
            $out[$os] = [
                "latest" => (int) ($p["latest"] ?? 0),
                "minimum" => (int) ($p["minimum"] ?? 0),
                "version" => (string) ($p["version"] ?? ""),
                "url" => (string) ($p["url"] ?? ""),
            ];
        }
        $this->response->setContent(json_encode($out));
        return $this->response;
    }

    public function clearcacheAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AF1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }

        // clear local file caches
        $files = glob("/var/cache/fusionpbx/*");
        foreach ($files as $file) {
            if (is_file($file)) {
                @unlink($file);
            }
        }
        $files = glob("/var/cache/ringq/*");
        foreach ($files as $file) {
            if (is_file($file)) {
                @unlink($file);
            }
        }

        // clear Redis API caches created by this controller
        try {
            $keys = [
                'queueAssigmentsAgents-*',
                'vCallCenterQueues-*',
                'vIvrMenus-*',
                'vIvrMenuOptionsRaw-*',
                'allVRingGroups-*',
                'allDialplans-*',
                'allVusers-*',
                'allQUsers-*',
                'vExtensions-*',
                'vCallCenterAgents-*',
                'vCallCenterAgents5-*',
                'allVCallCenterTiers-*'
            ]; 

            foreach ($keys as $pattern) {
                $cacheKeys = $this->redis->keys($pattern);
                if (is_array($cacheKeys)) {
                    foreach ($cacheKeys as $key) {
                        $this->redis->del($key);
                    }
                }
            }

            $cacheKeys = $this->redis->keys("api_cache:*");
            if (is_array($cacheKeys)) {
                foreach ($cacheKeys as $key) {
                    $this->redis->del($key);
                }
            }
            // chat caches for external, whatsapp, facebook start here
            $whatsAppKeys = $this->redis->keys("whatsappconfig:cache:number:*");
            if (is_array($whatsAppKeys)) {
                foreach ($whatsAppKeys as $key) {
                    $this->redis->del($key);
                }
            }
            $facebookKeys = $this->redis->keys("facebookconfig:cache:recipient:*");
            if (is_array($facebookKeys)) {
                foreach ($facebookKeys as $key) {
                    $this->redis->del($key);
                }
            }
            $twilioKeys = $this->redis->keys("twilio:fqdn:cache:information:*");
            if (is_array($twilioKeys)) {
                foreach ($twilioKeys as $key) {
                    $this->redis->del($key);
                }
            }
            // chat cache end here
        } catch (\Throwable $e) {
            // log and continue without failing the request
            error_log(json_encode([
                "clearcache_error" => ControllerBase::safeErrorMessage($e),
            ]));
        }
        $client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
            "persistent" => false,
        ]));
        $client->initialize();
        $client->emit("gatewaystart", ["uuid" => "", "subdomain" => $session["subdomain"]]);
        $response = json_encode(
            [
                "result" => "success",
                "message" => "Successfully, cleared cached.",
            ]
        );
        $this->response->setContent($response);
        return $this->response;
    }

    public function conferenceAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        if ($this->request->isGet()) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AC1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AC1001)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "string"));
            $parameters["conference_center_name"] = $this->request->getPost("conference_center_name", "string");
            $parameters["conference_center_extension"] = intval($this->request->getPost("conference_center_extension", "int"));
            $parameters["moderator_pin"] = $this->request->getPost("moderator_pin", "string");
            $parameters["participant_pin"] = $this->request->getPost("participant_pin", "string");
            $parameters["destination_number"] = $this->request->getPost("destination_number", "string");
            if (empty($parameters["conference_center_extension"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            $conferenceForm = new ConferenceForm();
            if (!$conferenceForm->isValid($parameters)) {
                $messages = $conferenceForm->getMessages();
                $message = "";
                foreach ($messages as $error) {
                    $message .= $error . " ";
                }
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => trim($message) . " (Code AC1002)",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            if ($parameters["type"] == 1) {
                $this->db->begin();
                $conference_extension = 9501;
                $nextExtension = VConferenceCenters::maximum(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "column" => "conference_center_extension",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                if ($nextExtension) {
                    $conference_extension = $nextExtension + 1;
                }
                if ($parameters["conference_center_extension"] != 0) {
                    $conference_extension = $parameters["conference_center_extension"];
                }
                $vConferenceCenter = VConferenceCenters::findFirst(
