                                );
                                $this->response->setContent($response);
                                return $this->response;
                            }
                        }
                    }
                }
                $vConference = VConferenceCenters::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND conference_center_extension = :conference_center_extension:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "conference_center_extension" => $parameters["conference_center_extension"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                    ]
                );
                if (!$vConference) {
                    $this->db->rollback();
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Conference non-existing (Code AQ1007)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                if (!$vConference->delete()) {
                    $this->db->rollback();
                    $messages = $vConference->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AQ1008)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $vDialplans = VDialplans::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND dialplan_uuid = :dialplan_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "dialplan_uuid" => $vConference->dialplan_uuid
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if (!$vDialplans) {
                    $this->db->rollback();
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Queue non-existing (Code AQ1010)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                foreach($vDialplans as $vDialplan) {
                    if (!$vDialplan->delete()) {
                        $this->db->rollback();
                        $messages = $vDialplan->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AQ1011)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                }
                $vConferenceRoom = VConferenceRooms::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND conference_center_uuid = :conference_center_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "conference_center_uuid" => $vConference->conference_center_uuid,
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if (!$vConferenceRoom->delete()) {
                    $this->db->rollback();
                    $messages = $vConferenceRoom->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AQ1012)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $this->db->commit();
                $conference_extension = 4000;
                $nextExtension = VConferenceCenters::maximum(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "column" => "conference_center_extension",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                if ($nextExtension) {
                    $conference_extension = $nextExtension + 1;
                }
                $response = json_encode(
                    [
                        "result" => "success",
                        "message" => "Successfully, deleted conference.",
                        "content" => strval($conference_extension),
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
        }
    }

    public function contactAction()
    {
       $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
       $this->response->setHeader("Content-Type", "application/json");
        if ($this->request->isPost()) {
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "int"));
            $parameters["queue_extension"] = intval($this->request->getPost("queue_extension", "int"));
            $parameters["number_phone_number"] = $this->request->getPost("number_phone_number", "string");
            if (empty($parameters["type"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
           }
           if ($this->isInternalRequest()) {
                $session["subdomain"] = $parameters["subdomain"] ?? null;
                $vDomain = VDomains::findFirst([
                    "conditions" => "domain_name = :domain_name:",
                    "bind" => [
                        "domain_name" => $session["subdomain"],
                    ],
                    "bindTypes" => [Column::BIND_PARAM_STR],
                ]);
                if ($vDomain) {
                    $session["domain_uuid"] = $vDomain->domain_uuid;
                }
           } else {
               $session = $this->session->get("auth");
               if (!$session) {
                    $response = json_encode(
                       [
                             "result" => "error",
                             "message" => "Sorry, invalid request made.",
                             "content" => [],
                       ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
               }
