                $settings["callLandingOutbound"] = in_array($this->redis->get("landing:" . $session["subdomain"] . "-call-landing-outbound"), [null, false], true) ? "0" : $this->redis->get("landing:" . $session["subdomain"] . "-call-landing-outbound");
