                    $base64Credentials = base64_encode($apiKey . ":");
                    $baseUrl = "https://api.$lastPart.cliniko.com/v1";
                    $phoneNumber = $parameters["number_phone_number"];
                    $getPatient = $this->redis->get("cliniko-patient:$phoneNumber"); 
