                        $qContacts = new QContacts();
                        $qContacts->first_name = $patientData["first_name"];
                        $qContacts->last_name = $patientData["last_name"];
                        $qContacts->phone = $patientData["numbers"];
                        $qContacts->phone2 = "";
                        $qContacts->company_name = "";
                        $qContacts->email = "";
                        $qContacts->email2 = "";
                        $qContacts->address_1 = "";
                        $qContacts->address_2 = "";
                        $qContacts->office_phone = "";
                        $qContacts->whatsapp_phone = "";
                        $curl = curl_init();
                        $userAgent = "";
                        if (!is_null($appVendorName) && !is_null($appVendorEmail)) {
                            $userAgent = "User-Agent: $appVendorName ($appVendorEmail)";
                        }
                        curl_setopt($curl, CURLOPT_URL, "$baseUrl/patients/{$patientData['patient_id']}");
                        curl_setopt($curl, CURLOPT_RETURNTRANSFER, true);
                        curl_setopt($curl, CURLOPT_HTTPHEADER, [
                            "Accept: application/json",
                            $userAgent,
                            "Authorization: Basic $base64Credentials"
                        ]);
                        $patientResponse = curl_exec($curl);
                        $patientStatus = curl_getinfo($curl, CURLINFO_HTTP_CODE);
                        curl_close($curl);

                        if ($patientStatus >= 200 && $patientStatus < 300) {
                            $patientResponseData = json_decode($patientResponse, true);

                            $settings2["showQueueCallLandingUrl"] .= "/patients/" .  $patientResponseData['id'];

                            $this->redis->rpush('queues-cliniko', json_encode([
                                'subdomain' => $session["subdomain"],
                                'first_name' => $patientResponseData['first_name'],
                                'last_name' => $patientResponseData['last_name'],
                                'patient_id' => $patientResponseData['id'],
                                'contact_number' => $parameters["number_phone_number"],
                                'queue_extension' => $parameters["queue_extension"],
                                'queued_at' => time()
                            ]));
                        } else {
                            $this->redis->del("cliniko-patient:$phoneNumber");

                            $this->redis->rpush('cliniko:newuser', json_encode([
                                'subdomain' => $session["subdomain"],
                                'phone_number' => $parameters["number_phone_number"],
                                'queue_extension' => $parameters["queue_extension"]
                            ])); 

                            $maxRetries = 10;
                            $retryCount = 0;

                            while ($retryCount < $maxRetries) {
                                $createdPatient = $this->redis->get('cliniko-patient-created');

                                if ($createdPatient) {
                                    $settings2["showQueueCallLandingUrl"] .= "/patients/" .  $createdPatient;
                                    break;
                                }

                                $retryCount++;
                                sleep(1);
                            }
