                    }
                    curl_close($curl);
                }
                $settings2["queueScriptContent"] = "";
                $qScript = QScripts::findFirst(
                    [
                       "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
                       "bind" =>
                          [
                             "domain_uuid" => $session["domain_uuid"],
                                "extension" => strval($parameters["queue_extension"])
                          ],
                       "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if ($qScript) {
                    $settings2["queueScriptContent"] = $qScript->content;
                }
                $response = json_encode(
                    [
                        "result" => "success",
                        "content" => isset($qContacts) ? $qContacts : null,
                        "wrapupCodes" => isset($qWrapupnotes) ? $qWrapupnotes : null,
