                        "settings" => $settings,
                        "settings2" => $settings2
                    ]
                );
                error_log("000 This is called 000");
                error_log($response);
                $this->redis->set($session["subdomain"]. "-". $parameters["type"] . $parameters["queue_extension"] . $parameters["number_phone_number"], $response);
                $this->redis->expire($session["subdomain"]. "-". $parameters["type"] . $parameters["queue_extension"] . $parameters["number_phone_number"], 60);
                $this->response->setContent($response);
                return $this->response;
