                }
                if ($parameters["show_call_landing2"] == "Cliniko") {
                    $results = $this->redis->hgetall("integration:" . $session["subdomain"] . "-cliniko");
                    $parameters["show_external_url"] = $results["url"]; 
                }
                if ($parameters["show_call_landing2"] == "Autotask") {
                    $results = $this->redis->hgetall("integration:" . $session["subdomain"] . "-autotask");
                    $parameters["show_external_url"] = $results["url"];
                }
                if ($parameters["show_call_landing2"] == "SalesForce") {
                    $results = $this->redis->hgetall("integration:" . $session["subdomain"] . "-salesforce");
                    $parameters["show_external_url"] = $results["url"];
                }
                $this->redis->set("landing:" . $session["subdomain"] . "-show-contact-module", $parameters["show_contact_module"]);
                $this->redis->set("landing:" . $session["subdomain"] . "-hide-contact-number", $parameters["hide_contact_number"]);
                $this->redis->set("landing:" . $session["subdomain"] . "-show-contact-page", $parameters["show_contact_module"]);
                $this->redis->set("landing:" . $session["subdomain"] . "-show-call-landing", $parameters["show_call_landing"]);
                $this->redis->set("landing:" . $session["subdomain"] . "-show-call-landing2", $parameters["show_call_landing2"]);
                // $this->redis->set("landing:" . $session["subdomain"] . "-auto-logout-webapp", $parameters["auto_logout_webapp"]);
                // $this->redis->set("landing:" . $session["subdomain"] . "-custom-auto-logout-webapp", $parameters["custom_auto_logout_webapp"]);
                $this->redis->set("landing:" . $session["subdomain"] . "-show-contact-page-before", $parameters["show_contact_page_before"]);
                $this->redis->set("landing:" . $session["subdomain"] . "-show-external-url", $parameters["show_external_url"]);
                $this->redis->set("landing:" . $session["subdomain"] . "-contact-checker", $parameters["contact_checker"]);
                // Older clients (mobile, Flutter) don't send these; leave the stored values untouched then.
                if ($this->request->hasPost("call_landing_inbound")) {
                    $this->redis->set("landing:" . $session["subdomain"] . "-call-landing-inbound", intval($this->request->getPost("call_landing_inbound", "int")) == 1 ? "1" : "0");
                }
                if ($this->request->hasPost("call_landing_outbound")) {
                    $this->redis->set("landing:" . $session["subdomain"] . "-call-landing-outbound", intval($this->request->getPost("call_landing_outbound", "int")) == 1 ? "1" : "0");
                }
               
                $aiCacheKey = "api_cache:accounts:ai:" . $session["domain_uuid"] . ":" . $session["subdomain"];
                $this->redis->del($aiCacheKey);

                $response = json_encode(
                    [
                        "result" => "success",
                        "message" => "Successfully, updated call landing.",
                        "content" => "",
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
        }

    }

    public function contactsAction($page = 1)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
            if ($this->request->isGet()) {
                $offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                $qContacts = QContacts::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_INT],
                        "limit" => 20,
                        "order" => "id ASC"
                    ]
                );
                $count = QContacts::count(
                    [
                        "conditions" => "domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_INT],
                    ]
                );
                $index = 0;
                $content = array();
                foreach ($qContacts as $qContact) {
                    $content[$index]["id"] = $qContact->id;
                    $content[$index]["companyname"] = isset($qContact->company_name) ? ucfirst($qContact->company_name) : null;
                    $content[$index]["firstname"] =  ucfirst($qContact->first_name);
                    $content[$index]["lastname"] = ucfirst($qContact->last_name);
                    $content[$index]["address_1"] = isset($qContact->address_1) ? $qContact->address_1 : null;
                    $content[$index]["address_2"] = isset($qContact->address_2) ? $qContact->address_2 : null;
                    $content[$index]["email"] = isset($qContact->email) ? $qContact->email : null;
                    $content[$index]["email2"] = isset($qContact->email2) ? $qContact->email2 : null;
                    $content[$index]["phone"] = $qContact->phone;
                    $content[$index]["phone2"] = isset($qContact->phone2) ? $qContact->phone2 : null;
                    $content[$index]["office_phone"] = isset($qContact->office_phone) ? $qContact->office_phone : null;
                    $content[$index]["whatsapp_phone"] = isset($qContact->whatsapp_phone) ? $qContact->whatsapp_phone : null;
                    $qWrapupnotesLists = QWrapupnotesList::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND contact_id = :contact_id:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "contact_id" => $qContact->id,
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                            "limit" => 20,
                            'order' => 'insert_date DESC'
                        ]
                    );
                    $content[$index]["wrapup_notes"] = isset($qWrapupnotesLists) ? $qWrapupnotesLists : null;
                    $index++;
                }
                $response = json_encode(
                    [
                        "result" => "success",
                        "content" => $content,
                        "count" => $count,
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
