                $parameters["contact_type"] = intval($this->request->getPost("contact_type", "int"));
                $parameters["company_name"] = $this->request->getPost("company_name", "string");
                $parameters["first_name"] = $this->request->getPost("first_name", "string");
                $parameters["last_name"] = $this->request->getPost("last_name", "string");
                $parameters["email"] = $this->request->getPost("email", "string");
