    public function destinationsAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        if ($this->request->isGet()) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AD1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AD1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "int"));
            $parameters["type2"] = intval($this->request->getPost("type2", "int"));
            $parameters["extension"] = intval($this->request->getPost("extension", "int"));
            $parameters["destination_name"] = $this->request->getPost("destination_name", "string");
            $parameters["destination_number"] = $this->request->getPost("destination_number", "string");
            $parameters["destination_record"] = $this->request->getPost("destination_record", "string");
            $parameters["destination_enabled"] = $this->request->getPost("destination_enabled", "string");
            if (empty($parameters["extension"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            $inboundForm = new InboundForm();
            if (!$inboundForm->isValid($parameters)) {
                $messages = $inboundForm->getMessages();
                $message = "";
                foreach ($messages as $error) {
                    $message .= $error . " ";
                }
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => trim($message) . " (Code AD1000)",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            // ADD INBOUND
            if ($parameters["type"] == 1) {
                $this->db->begin();
                $qDid = QDids::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND did_number = :did_number: OR did_number = :did_number2:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "did_number" => $parameters["destination_number"],
                                "did_number2" => "+" . $parameters["destination_number"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if (!$qDid) {
                    $this->db->rollback();
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Sorry, DID does not exists. (Code AD1000)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $previousExtension = $qDid->extension;
                $qDidChecker = QDids::findFirst(
                    [
                        "conditions" => "domain_uuid != :domain_uuid: AND did_number = :did_number: ",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "did_number" => $parameters["destination_number"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if ($qDidChecker) {
                    $this->db->rollback();
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Sorry, DID already assigned in another instance. (Code AD1000)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                if ($parameters["type2"] == 1) {
                    $didType = "1";
                    if (intval($parameters["extension"]) != 3000 && intval($parameters["extension"]) != 5555  && intval($parameters["extension"]) != 7777) {
                        $checkIvr = VIvrMenus::findFirst(
                            [
                                "conditions" => "domain_uuid = :domain_uuid: AND ivr_menu_extension = :ivr_menu_extension:",
                                "bind" =>
                                    [
                                        "domain_uuid" => $session["domain_uuid"],
                                        "ivr_menu_extension" => $parameters["extension"],
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                            ]
                        );
                        if ($checkIvr) {
                            $parameters["extension"] = $checkIvr->ivr_menu_extension;
                        } else {
                            $nextExtension = VIvrMenus::maximum(
                                [
