            if ($parameters["type"] == 1) {
                $security = new \Phalcon\Security\Random();
                $did_uuid = $security->uuid();
                $checkDid = QDids::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND did_number = :did_number:",
                        "bind" => [
                            "domain_uuid" => $session["domain_uuid"],
                            "did_number" => $parameters["did_number"],

                        ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                    ]
                );
                if ($checkDid) {
                    $message = "Sorry, DID already exists.";
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AD1011)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $qDid = new QDids();
                $qDid->did_uuid = $did_uuid;
                $qDid->domain_uuid = $session["domain_uuid"];
                $qDid->did_number = $parameters["did_number"];
                $qDid->sip_trunk_name = $parameters["sip_trunk_name"];
                $qDid->country = $parameters["country"];
                $qDid->insert_user = $session["user_uuid"];
                $qDid->insert_date = date("Y-m-d H:i:s");
                if (!$qDid->create()) {
                    $messages = $qDid->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AD1011)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $response = json_encode(
                    [
                        "result" => "success",
                        "message" => "Successfully, added new DID.",
                        "content" => [
                            "did" => $parameters["did_number"]
                        ],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            if ($parameters["type"] == 2) {
                $qDid = QDids::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND did_number = :did_number: ",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "did_number" => $parameters["did_number"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if (!$qDid) {
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Sorry, DID does not exists. (Code AD1012)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $this->db->begin();
                if (!$qDid->delete()) {
                    $this->db->rollback();
                    $messages = $qDid->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AD1013)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $vDestination = VDestinations::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND destination_number = :destination_number: ",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "destination_number" => $qDid->did_number,
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if ($vDestination) {
                    if (!$vDestination->delete()) {
                        $this->db->rollback();
                        $messages = $vDestination->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AD1013)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $vDialplans = VDialplans::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND dialplan_uuid = :dialplan_uuid: ",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "dialplan_uuid" => $vDestination->dialplan_uuid,
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    foreach($vDialplans as $vDialplan) {
                        if (!$vDialplans->delete()) {
                            $this->db->rollback();
                            $messages = $vDialplans->getMessages();
                            $message = "";
                            foreach ($messages as $error) {
                                $message .= $error . " ";
                            }
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => trim($message) . " (Code AD1013)",
                                    "content" => [],
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                        $vDialplanDetails = VDialplanDetails::find(
                            [
                                "conditions" => "domain_uuid = :domain_uuid: AND dialplan_uuid = :dialplan_uuid: ",
                                "bind" =>
                                    [
                                        "domain_uuid" => $session["domain_uuid"],
                                        "dialplan_uuid" => $vDialplan->dialplan_uuid,
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                            ]
                        );
                        foreach($vDialplanDetails as $vDialplanDetail) {
                            if (!$vDialplanDetail->delete()) {
                                $this->db->rollback();
                                $messages = $vDialplanDetail->getMessages();
                                $message = "";
                                foreach ($messages as $error) {
                                    $message .= $error . " ";
                                }
                                $response = json_encode(
                                    [
                                        "result" => "error",
                                        "message" => trim($message) . " (Code AD1013)",
                                        "content" => [],
                                    ]
                                );
                                $this->response->setContent($response);
                                return $this->response;
                            }
                        }
                    }
                }
                $this->db->commit();
                $response = json_encode(
                    [
                        "result" => "success",
                        "message" => "Successfully deleted DID.",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
        }
    }

    public function faxAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        if ($this->request->isGet()) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AF1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AF1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "int"));
            $parameters["fax_extension"] = intval($this->request->getPost("fax_extension", "int"));
            $parameters["fax_name"] = $this->request->getPost("fax_name", "string");
            $parameters["fax_email_connection_host"] = $this->request->getPost("fax_email_connection_host", "string");
            $parameters["fax_email_connection_type"] = $this->request->getPost("fax_email_connection_type", "string"); // pop3, IMAP
            $parameters["fax_email_connection_security"] = $this->request->getPost("fax_email_connection_security", "string"); // ssl, tls
            $parameters["fax_email_connection_username"] = $this->request->getPost("fax_email_connection_username", "string");
            $parameters["fax_email_connection_password"] = $this->request->getPost("fax_email_connection_password", "string");
            $parameters["fax_email_outbound_authorized_senders"] = $this->request->getPost("fax_email_outbound_authorized_senders", "string");
            $parameters["fax_extension"] = intval($this->request->getPost("fax_extension", "int"));
            $parameters["fax_email_connection_port"] = intval($this->request->getPost("fax_email_connection_port", "int"));
            if (empty($parameters["fax_extension"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            $faxForm = new FaxForm();
            if (!$faxForm->isValid($parameters)) {
                $messages = $faxForm->getMessages();
                $message = "";
                foreach ($messages as $error) {
                    $message .= $error . " ";
                }
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => trim($message) . " (Code AF1002)",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            if ($parameters["type"] == 1) {
                $this->db->begin();
                $fax_extension = $parameters["fax_extension"];
                $security = new \Phalcon\Security\Random();
                $fax_uuid = $security->uuid();
                $dialplan_uuid = $security->uuid();
                $vFax = new VFax();
                $vFax->fax_uuid = $fax_uuid;
                $vFax->dialplan_uuid = $dialplan_uuid;
                $vFax->domain_uuid = $session["domain_uuid"];
                $vFax->accountcode = $session["subdomain"];
                $checkFax = VFax::findFirst(
                    [
