                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $vFax->fax_prefix = "";
                $vFax->fax_email = "";
                $vFax->fax_extension = strval($fax_extension);
                $vFax->fax_destination_number = strval($fax_extension);
