                $vFax->fax_email_connection_type = $parameters["fax_email_connection_type"];
                $vFax->fax_email_connection_host = $parameters["fax_email_connection_host"];
                $vFax->fax_email_connection_port = strval($parameters["fax_email_connection_port"]);
                $vFax->fax_email_connection_security = $parameters["fax_email_connection_security"];
                $vFax->fax_email_connection_username = $parameters["fax_email_connection_username"];
                $vFax->fax_email_connection_password = $parameters["fax_email_connection_password"];
                $vFax->fax_email_outbound_authorized_senders = $parameters["fax_email_outbound_authorized_senders"];
                $vFax->fax_email_connection_validate = "true";
