                    // $client2 = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
                    //     "persistent" => false,
                    // ]));
                    // $client2->initialize();
                    // $client2->emit("reloadqueue", []);
                    // Twilio
                    $redisKey = "twilioconfig:sms:config:". $vGateway->gateway_uuid .":". $session["subdomain"];
                    $payload = [
                        'id' => $vGateway->gateway_uuid,
                        'fqdn' => $session["subdomain"],
                        'name' => $parameters["twilio_name"],
                        'phoneNumber' => $parameters["twilio_phone_number"],
