                    $this->redis->set($redisKey, json_encode($payload));
                    // Telnyx
                    $redisKey2 = "telnyx:sms:config:". $vGateway->gateway_uuid .":". $session["subdomain"];
                    $payload2 = [
                        'id' => $vGateway->gateway_uuid,
