    public function historyAction($type = 1, $page = 1, $extension = 0, $callNature = 0, $callType = 0, $startStamp = 0, $endStamp = 0)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
            if ($type == 3 && $this->isPlainUser($session)) {
                $type = 1;
            }
            if ($this->request->isGet()) {
                $offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                $vCallCenterAgents = VCallCenterAgents::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND user_uuid = :user_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "user_uuid" => $session["user_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                $vCallCenterAgentArray = [];
                foreach ($vCallCenterAgents as $vCallCenterAgent) {
                    array_push($vCallCenterAgentArray, $vCallCenterAgent->call_center_agent_uuid);
                }
                $vCallCenterAgentArray = implode(",", $vCallCenterAgentArray);
                $vCallCenterAgentArray = is_array($vCallCenterAgentArray) ? $vCallCenterAgentArray : (strpos((string) $vCallCenterAgentArray, ',') !== false ? explode(",", (string) $vCallCenterAgentArray) : [(string) $vCallCenterAgentArray]);
                $timestamp = $this->redis->get($session["extension"] ."@". $session["subdomain"] ."-deletion");
                if (!isset($timestamp)) {
                    $timestamp = 0;
                }
                // CALL LOGS // AGENT, CALL TYPE (MISSED/ANSWERED), CALL NATURE (INBOUND/OUTBOUND), DATE
                if ($type == 1) {
                    $vXmlCdrs = QRingqCdr::find(
                        [
                            // "conditions" => "(caller_id_number = :extension: OR caller_destination = :extension: OR cc_agent IN (:cc_agent:) OR source_number = :extension:) AND caller_id_number != caller_destination AND source_number is not NULL AND (caller_id_number != :extension: OR caller_destination != :extension: OR source_number = :extension:) AND domain_uuid = :domain_uuid: AND start_epoch > :start_epoch:",
                            "conditions" => "(caller_id_number = :extension: OR caller_destination = :extension: OR cc_agent IN ({cc_agent:array}) OR source_number = :extension:) AND caller_id_number != caller_destination AND (caller_id_number != :extension: OR caller_destination != :extension: OR source_number = :extension:) AND domain_uuid = :domain_uuid: AND start_epoch > :start_epoch:",
                            "columns" => "direction, call_center_queue_uuid, last_arg, start_stamp, answer_stamp, start_epoch, answer_epoch, end_stamp, end_epoch, caller_id_name, caller_id_number, caller_destination, destination_number, duration, voicemail_message, missed_call, waitsec, hangup_cause, source_number, record_name",
                            "bind" =>
                                [
                                    "extension" => $session["extension"],
                                    "domain_uuid" => $session["domain_uuid"],
                                    "cc_agent" => $vCallCenterAgentArray,
                                    "start_epoch" => $timestamp
                                ],
                            "bindTypes" => [Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                            "limit" => 20,
                            "offset"=> $offset,
                            'order' => 'insert_date DESC'
                        ]
                    );
                    $count = QRingqCdr::count(
                        [
                            "conditions" => "(caller_id_number = :extension: OR caller_destination = :extension: OR cc_agent IN ({cc_agent:array}) OR source_number = :extension:) AND caller_id_number != caller_destination AND source_number is not NULL AND (caller_id_number != :extension: OR caller_destination != :extension: OR source_number = :extension:) AND domain_uuid = :domain_uuid: AND start_epoch > :start_epoch:",
                            "bind" =>
                                [
                                    "extension" => $session["extension"],
                                    "domain_uuid" => $session["domain_uuid"],
                                    "cc_agent" => $vCallCenterAgentArray,
                                    "start_epoch" => $timestamp
                                ],
                            "bindTypes" => [Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                        ]
                    );
                    $count2 = QRingqCdr::count(
                        [
                            "conditions" => "caller_destination = :extension: AND caller_id_number != caller_destination AND source_number is not NULL AND domain_uuid = :domain_uuid: AND missed_call = true AND start_epoch > :start_epoch:",
                            "bind" =>
                                [
                                    "extension" => $session["extension"],
                                    "domain_uuid" => $session["domain_uuid"],
                                    "start_epoch" => $timestamp
                                ],
                            "bindTypes" => [Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                        ]
                    );
                    $missed = $this->redis->get($session["extension"] ."@". $session["subdomain"] ."-missed");
                    $this->redis->set($session["extension"] ."@". $session["subdomain"] ."-missed", $count2);
                    $vXmlCdrsArray = $vXmlCdrs->toArray();
                    $finalCdrs = [];
                    foreach ($vXmlCdrsArray as $key => $vXmlCdr) {
                        $uniqueKey = $vXmlCdr['call_center_queue_uuid'] . '-' . $vXmlCdr['start_stamp'];
                        if (!isset($uniqueCdrs[$uniqueKey])) {
                            $uniqueCdrs[$uniqueKey] = true;
                            if (isset($vXmlCdr['call_center_queue_uuid']) && $vXmlCdr['call_center_queue_uuid']) {
                                $vXmlCdr['is_queue'] = 'true';
                            } else {
                                $vXmlCdr['is_queue'] = 'false';
                            }
                            $finalCdrs[] = $vXmlCdr;
                        }
                    }
                    $content = [
                        "callLogs" => $finalCdrs,
                        "count" => $count,
                        "count2" => isset($missed) ? $missed : $count2,
                        "message" => $vCallCenterAgentArray
                    ];
                    $response = json_encode(
                        [
                            "result" => "success",
                            "content" => $content,
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                if ($type == 2) {
                    $vXmlCdr = QRingqCdr::find(
                        [
                            "conditions" => "(caller_destination = :extension: OR cc_agent = :cc_agent: OR source_number = :extension:) AND caller_id_number != caller_destination AND source_number is not NULL AND domain_uuid = :domain_uuid: AND missed_call = true AND start_epoch > :start_epoch:",
                            "columns" => "direction, start_stamp, answer_stamp, last_arg, start_epoch, answer_epoch, end_stamp, end_epoch, caller_id_name, caller_id_number, caller_destination, destination_number, duration, voicemail_message, missed_call, waitsec, hangup_cause, source_number, record_name",
                            "bind" =>
                                [
                                    "extension" => $session["extension"],
                                    "domain_uuid" => $session["domain_uuid"],
                                    "cc_agent" => $vCallCenterAgent->call_center_agent_uuid,
                                    "start_epoch" => $timestamp
                                ],
                            "bindTypes" => [Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                            "limit" => 20,
                            "offset"=> $offset,
                            'order' => 'insert_date DESC'
                        ]
                    );
                    $count = QRingqCdr::count(
                        [
                            "conditions" => "(caller_destination = :extension: OR cc_agent = :cc_agent: OR source_number = :extension:) AND caller_id_number != caller_destination AND source_number is not NULL AND domain_uuid = :domain_uuid: AND missed_call = true AND start_epoch > :start_epoch:",
                            "bind" =>
                                [
                                    "extension" => $session["extension"],
                                    "domain_uuid" => $session["domain_uuid"],
                                    "cc_agent" => $vCallCenterAgent->call_center_agent_uuid,
                                    "start_epoch" => $timestamp
                                ],
                            "bindTypes" => [Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                        ]
                    );
                }
                // CALL LOGS // AGENT, CALL TYPE (MISSED/ANSWERED), CALL NATURE (INBOUND/OUTBOUND), DATE
                if ($type == 3) {
                    $conditions = "source_number is not NULL AND domain_uuid = :domain_uuid:";
                    $bind = [
                        "domain_uuid" => $session["domain_uuid"],
                    ];
                    $bindTypes = [
                        Column::BIND_PARAM_STR
                    ];
                    // $extension = 0, $callType = 1, $callNature = 1, $startStamp = 0, $endStamp = 0
                    if ($extension != 0) {
                        $extension = intval($extension);
                        $vCallCenterAgent = VCallCenterAgents::findFirst(
                            [
                                "conditions" => "domain_uuid = :domain_uuid: AND agent_id = :agent_id:",
                                "bind" =>
                                    [
                                        "domain_uuid" => $session["domain_uuid"],
                                        "agent_id" => $extension,
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT],
                            ]
                        );
                        if (!$vCallCenterAgent) {
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "content" => [],
                                    "message" => "Sorry, extension is either non-existing or already deleted.",
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                        $conditions = "domain_uuid = :domain_uuid: AND (caller_id_number = :extension: OR caller_destination = :extension: OR cc_agent = :cc_agent: OR source_number = :extension:) AND caller_id_number != caller_destination AND source_number is not NULL AND (caller_id_number != :extension: OR caller_destination != :extension: OR cc_agent != :cc_agent: OR source_number = :extension:) AND start_epoch > :start_epoch:";
                        $bind = [
                            "domain_uuid" => $session["domain_uuid"],
                            "extension" => $extension,
                            "cc_agent" => $vCallCenterAgent->call_center_agent_uuid,
                            "start_epoch" => $timestamp
                        ];
                        $bindTypes = [
                            Column::BIND_PARAM_STR, Column::BIND_PARAM_INT, Column::BIND_PARAM_STR, Column::BIND_PARAM_INT
                        ];
                    }
                    if ($callType != 0) {
                        // Missed call
                        if ($callType == 1) {
                            $conditions .= " AND answer_epoch is NULL";
                        }
                        // Answered call
                        if ($callType == 2) {
                            $conditions .= " AND answer_epoch is NOT NULL";
                        }
                    }
                    if ($callNature != 0) {
                        // Incoming 
                        if ($callNature == 1) {
                            $conditions .= " AND (direction = 'inbound' OR direction = 'local')";
                        }
                        // Outgoing
                        if ($callNature == 2) {
                            $conditions .= " AND direction = 'outbound'";
                        }
                    }
                    if ($startStamp != 0) {
                        $conditions .= " AND start_epoch > :start_epoch:";
                        $bind["start_epoch"] = $startStamp;

                    }
                    if ($endStamp != 0) {
                        $conditions = str_replace(" AND start_epoch > :start_epoch:","", $conditions);
                        $conditions .= " AND start_epoch BETWEEN :start_epoch: AND :start_epoch2:";
                        $bind2 = array_merge($bind, ["start_epoch2" => $endStamp]);
                        $bind = $bind2;
                        array_push($bindTypes, Column::BIND_PARAM_INT);
                    }
                    $vXmlCdr = QRingqCdr::find(
                        [
                            "conditions" => $conditions,
                            "columns" => "direction, start_stamp, last_arg, answer_stamp, start_epoch, answer_epoch, end_stamp, end_epoch, caller_id_name, caller_id_number, caller_destination, destination_number, duration, voicemail_message, missed_call, waitsec, hangup_cause, source_number, record_name",
                            "bind" => $bind,
                            "bindTypes" => $bindTypes,
                            "limit" => 20,
                            "offset"=> $offset,
                            'order' => 'insert_date DESC'
                        ]
                    );
                    $count = QRingqCdr::count(
                        [
                            "conditions" => $conditions,
                            "bind" => $bind,
                            "bindTypes" => $bindTypes,
                        ]
                    );
                    $response = json_encode(
                        [
                            "result" => "success",
                            "content" => $vXmlCdr,
                            "count" => $count,
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $content = [
                    "callLogs" => $vXmlCdr,
                    "count" => $count
                ];
                $response = json_encode(
                    [
                        "result" => "success",
                        "content" => $content,
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            } else if ($this->request->isPost()) {
                $parameters["page"] = intval($this->request->getPost("page", "int"));
                $parameters["type"] = intval($this->request->getPost("type", "int"));
                if (empty($parameters["page"])) {
                    $contents = file_get_contents("php://input");
                    $parameters = json_decode($contents, true);
                }
                if ($parameters["type"] == 0) {
                    $this->redis->set($session["extension"] ."@". $session["subdomain"] ."-deletion", time());
                    $response = json_encode(
                        [
                            "result" => "success",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $offset = $page > 1 ? intval($parameters["page"]) * 20 - 20 : 0;
                $vXmlCdrs = QRingqCdr::find(
                    [
                        "conditions" => "source_number is not NULL AND domain_uuid = :domain_uuid:",
                        "columns" => "direction, start_stamp, last_arg, answer_stamp, start_epoch, answer_epoch, end_stamp, end_epoch, caller_id_name, caller_id_number, caller_destination, destination_number, duration, voicemail_message, missed_call, waitsec, hangup_cause, source_number",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                        "limit" => 20,
                        "offset"=> $offset,
                        'order' => 'insert_date DESC'
                    ]
                );
                $count = QRingqCdr::count(
                    [
                        "conditions" => "source_number is not NULL AND domain_uuid = :domain_uuid:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                $index = 0;
                $content = array();
                foreach ($vXmlCdrs as $vXmlCdr) {
                    $content[$index]["date"] = $vXmlCdr->start_stamp;
                    $content[$index]["time"] = $vXmlCdr->start_stamp;
                    $content[$index]["caller"] = $vXmlCdr->caller_id_number;
                    $content[$index]["caller_name"] = $vXmlCdr->caller_id_name;
                    $content[$index]["caller"] = $vXmlCdr->caller_id_number;
                    $content[$index]["destination"] = $vXmlCdr->caller_destination;
                    $content[$index]["duration"] = $vXmlCdr->duration;
                    $index++;
                }
                $security = new \Phalcon\Security\Random();
                $filename = $security->uuid();
                $fp = fopen('/var/www/ringq/cache/'. $filename .'.csv', 'w');
                $header = ["Date", "Time", "Extension", "Caller Name", "Caller Number", "Caller", "Customer", "Destination", "Duration"];
                fputcsv($fp, $header, ",");
                foreach ($content as $fields) { 
                    fputcsv($fp, $fields, ","); 
                }
                header('Content-Type: text/csv');
                header('Content-Disposition: attachment; filename="output.csv";');
                fclose($fp);
                if ($parameters["type"] == 1) {
                    $this->response->setFileToSend("/var/www/ringq/cache/". $filename .".csv", $filename .".csv")->send();
                    if (file_exists("/var/www/ringq/cache/". $filename .".csv")) {
                        unlink("/var/www/ringq/cache/". $filename .".csv");
                    }
                } 
                if ($parameters["type"] == 2) {
                    $this->redis->lpush("report", json_encode(["email" => $session["email"], "file" => $filename .".csv", "domain_uuid" => $session["domain_uuid"]]));
                    $response = json_encode(
                        [
                            "result" => "success",
                            "message" => "Generating reports.",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            }
        }
    }

    public function holidayexemptAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AT21000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "int"));
            $parameters["extension"] = intval($this->request->getPost("extension", "int"));
            if (empty($parameters["type"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            if ($parameters["type"] == 1) {
                $checker = QHolidayExemptions::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "extension" => strval(intval($parameters["extension"]))
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if ($checker) {
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Sorry, extension is already exempted (Code AT21000)",
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $this->db->begin();
                $security = new \Phalcon\Security\Random();
                $exempt_uuid = $security->uuid();
                $qHolidayExemption = new QHolidayExemptions();
                $qHolidayExemption->exempt_uuid = $exempt_uuid;
                $qHolidayExemption->domain_uuid = $session["domain_uuid"];
                $qHolidayExemption->extension = strval(intval($parameters["extension"]));
                $qHolidayExemption->insert_user = $session["user_uuid"];
                $qHolidayExemption->insert_date = date("Y-m-d H:i:s");
                if (!$qHolidayExemption->create()) {
                    $this->db->rollback();
                    $messages = $qHolidayExemption->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AT2002)",
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                $qHolidays = QHolidays::find(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND extensions is NULL",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],

                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR],
                    ]
                );
                foreach($qHolidays as $qHoliday) {
                    $qHoliday->update_user = $session["user_uuid"];
                    $qHoliday->update_date = date("Y-m-d H:i:s");
                    if (!$qHoliday->update()) {
                        $this->db->rollback();
                        $messages = $qHoliday->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AT2003)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $qHolidayExemptions = QHolidayExemptions::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "columns" => "extension",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR] ,
                        ]
                    );
                    $exemptions = array(strval(intval($parameters["extension"])));
                    foreach ($qHolidayExemptions as $qHolidayExemption) {
                        array_push($exemptions, $qHolidayExemption->extension);
                    }
                    $included = array();
                    $vIvrMenus = VIvrMenus::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "columns" => "ivr_menu_extension",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                        ]
                    );
                    foreach($vIvrMenus as $vIvrMenu) {
                        if ($vIvrMenu->ivr_menu_extension > 5999 && !in_array($vIvrMenu->ivr_menu_extension, $exemptions)) {
                            array_push($included, $vIvrMenu->ivr_menu_extension);
                        }
                    }
                    $vCallCenterQueues = VCallCenterQueues::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "columns" => "queue_extension",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                        ]
                    );
                    foreach($vCallCenterQueues as $vCallCenterQueue) {
                        if (!in_array($vCallCenterQueue->queue_extension, $exemptions)) {
                            array_push($included, $vCallCenterQueue->queue_extension);
                        }
                    }
                    $vExtensions = VExtensions::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "columns" => "extension",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                        ]
                    );
                    foreach($vExtensions as $vExtension) {
                        if (!in_array($vExtension->extension, $exemptions)) {
                            array_push($included, $vExtension->extension);
                        }
                    }
                    $extension = implode("|", $included);
                    $parameters["day"] = $qHoliday->day;
                    $parameters["month"] = $qHoliday->month;
                    $parameters["year"] = $qHoliday->year;
                    $parameters["recurring"] = $qHoliday->recurring;
                    $parameters["holiday_name"] = $qHoliday->holiday_name;
                    $parameters["holiday_greeting"] = $qHoliday->holiday_greeting;
                    $day2 = $qHoliday->day2 != "0" ? "-" . $qHoliday->day2 : "-" .  $qHoliday->day;
                    $month2 = $qHoliday->month2 != "0" ? "-". $qHoliday->month2 : "-" . $qHoliday->month;
                    $year2 = $qHoliday->year2 != "0" ? "-" . $qHoliday->year2 : "-" . $qHoliday->year;
                    $dialplan_name = $qHoliday->holiday_uuid;
                    $vDialplan = VDialplans::findFirst(
