                    $day2 = $qHoliday->day2 != "0" ? "-" . $qHoliday->day2 : "-" .  $qHoliday->day;
                    $month2 = $qHoliday->month2 != "0" ? "-". $qHoliday->month2 : "-" . $qHoliday->month;
                    $year2 = $qHoliday->year2 != "0" ? "-" . $qHoliday->year2 : "-" . $qHoliday->year;
                    $dialplan_name = $qHoliday->holiday_uuid;
                    $vDialplan = VDialplans::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND dialplan_name = :dialplan_name:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "dialplan_name" => $dialplan_name,
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    if ($vDialplan) {
                        $vDialplan->dialplan_name = $dialplan_name;
                        if ($parameters["recurring"] != "0") {
                            $vDialplan->dialplan_xml = '<extension name="'. $dialplan_name .'" continue="false" uuid="'. $vDialplan->dialplan_uuid .'">
                                <condition field="destination_number" expression="^'. $extension .'$"/>
                                <condition year="'.$parameters["year"] . $year2 .'" mday="'. $parameters["day"] . $day2 .'" mon="'. $parameters["month"] . $month2 .'" break="never">
                                    <action application="set" data="'. $parameters["holiday_name"] .'" inline="true"/>
                                    <action application="lua" data="streamfile.lua /var/www/ringq/public/audio/'. $parameters["holiday_greeting"] .'"/>
                                </condition>
                            </extension>';
                        } else {
                            $vDialplan->dialplan_xml = '<extension name="'. $dialplan_name .'" continue="false" uuid="'. $vDialplan->dialplan_uuid .'">
                                <condition field="destination_number" expression="^'. $extension .'$"/>
                                <condition mday="'. $parameters["day"] . $day2 .'" mon="'. $parameters["month"] . $month2 .'" break="never">
                                    <action application="set" data="'. $parameters["holiday_name"] .'" inline="true"/>
                                    <action application="lua" data="streamfile.lua /var/www/ringq/public/audio/'. $parameters["holiday_greeting"] .'"/>
                                </condition>
                            </extension>';
                        }
                        $vDialplan->update_user = $session["user_uuid"];
                        $vDialplan->update_date = date("Y-m-d H:i:s");
                        if (!$vDialplan->update()) {
                            $this->db->rollback();
                            $messages = $vDialplan->getMessages();
                            $message = "";
                            foreach ($messages as $error) {
                                $message .= $error . " ";
                            }
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => trim($message) . " (Code AT2003)",
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                        $vDialplanDetail = VDialplanDetails::findFirst(
                            [
                                "conditions" => "domain_uuid = :domain_uuid: AND dialplan_uuid = :dialplan_uuid: AND dialplan_detail_type = :dialplan_detail_type:",
                                "bind" =>
                                    [
                                        "domain_uuid" => $session["domain_uuid"],
                                        "dialplan_uuid" => $vDialplan->dialplan_uuid,
                                        "dialplan_detail_type" => "destination_number"
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                            ]
                        );
                        if ($vDialplanDetail) {
                            $vDialplanDetail->dialplan_detail_data = $extension;
                            $vDialplanDetail->update_user = $session["user_uuid"];
                            $vDialplanDetail->update_date = date("Y-m-d H:i:s");
                            if (!$vDialplanDetail->update()) {
                                $this->db->rollback();
                                $messages = $vDialplanDetail->getMessages();
                                $message = "";
                                foreach ($messages as $error) {
                                    $message .= $error . " ";
                                }
                                $response = json_encode(
                                    [
                                        "result" => "error",
                                        "message" => trim($message) . " (Code AT2004)",
                                        "content" => [],
                                    ]
                                );
                                $this->response->setContent($response);
                                return $this->response;
                            }
                        }
                    }
                }
                if (file_exists("/var/cache/fusionpbx/dialplan.". $session["subdomain"])) {
                    unlink("/var/cache/fusionpbx/dialplan.". $session["subdomain"]);
                }
                if (file_exists("/var/cache/fusionpbx/dialplan.public")) {
                    unlink("/var/cache/fusionpbx/dialplan.public");
                }
                if (file_exists("/var/cache/ringq/dialplan.". $session["subdomain"])) {
                    unlink("/var/cache/ringq/dialplan.". $session["subdomain"]);
                }
                if (file_exists("/var/cache/ringq/dialplan.public")) {
                    unlink("/var/cache/ringq/dialplan.public");
                }
                $this->db->commit();
                $response = json_encode(
                    [
                        "result" => "success",
                        "message" => "Successfully deleted holiday schedule.",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
        }
    }

    public function ivrAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        if ($this->request->isGet()) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code IV1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code IV1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $this->redis->del("vIvrMenus-" . $session["subdomain"]);
            $this->redis->del("vIvrMenuOptionsRaw-" . $session["subdomain"]);
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "int"));
