    public function messagesAction($type = 1, $param = "", $page = 1)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($this->request->isGet()) {
            if ($type == 1) {
                $extensions = array($session["extension"], $param);
                sort($extensions);
                $offset = $page * 30;
                $count = $this->redis->llen($session["subdomain"] ."-internal-". $extensions[0] ."-". $extensions[1]);
                if ($count) {
                    $view = false;
                    if ($count > 31) {
                        $pages = ceil($count / 30) - intval($page);
                        $view = $pages <= 1 ? false : true;
                        $logs = [];
                        if (ceil($count / 30) > intval($page) - 1) {
                            $offstop = intval($page) > 1 ? $pages * 30 + 29 : -1;
                            $logs = $this->redis->lrange($session["subdomain"]."-internal-". $extensions[0] ."-". $extensions[1], $offset, $offset + 29);
                        }
                        $data = json_encode(
                            [
                                "result" => "success",
                                "content" => $logs,
                                "bool" => $view
                            ]
                        );
                        $this->response->setContent($data);
                        return $this->response;
                    } else {
                        $logs = $this->redis->lrange($session["subdomain"]."-internal-". $extensions[0] ."-". $extensions[1], $offset, -1);
                        $data = json_encode(
                            [
                                "result" => "success",
                                "content" => $logs,
                                "bool" => $view
                            ]
                        );
                        $this->response->setContent($data);
                        return $this->response;
                    }
                }
            }
        }
    }

