    public function scheduling2Action()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        if ($this->request->isGet()) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AS21000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AS21001)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $this->redis->del("allDialplans-" . $session["subdomain"]);
            $this->db->begin();
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "int"));
            $parameters["type2"] = intval($this->request->getPost("type2", "int"));
            $parameters["voicemail"] = intval($this->request->getPost("voicemail", "int"));
            $parameters["extension"] = intval($this->request->getPost("extension", "int"));
            $parameters["destination_action"] = intval($this->request->getPost("destination_action", "int"));
            if (empty($parameters["extension"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            $dialplan_name = "nonwork-";
            $dial_playback = '<action application="lua" data="streamfile.lua misc/sorry_non-office_hour.wav"/>';
            if ($parameters["type"] == 2 || $parameters["type"] == 4 || $parameters["type"] == 6) {
                $dialplan_name = "break-";
                $dial_playback = '<action application="lua" data="streamfile.lua misc/sorry_break-time.wav"/>';
            }
