                                        "domain_uuid" => $session["domain_uuid"],
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR],
                            ]
                        );
                        foreach($vIvrMenus as $vIvrMenu) {
                            if ($vIvrMenu->ivr_menu_extension > 5999) {
                                array_push($included, $vIvrMenu->ivr_menu_extension);
                            }
                        }
                    }
                    if ($parameters["type2"] == 2) {
                        $vCallCenterQueues = VCallCenterQueues::find(
                            [
                                "conditions" => "domain_uuid = :domain_uuid:",
                                "columns" => "queue_extension",
                                "bind" =>
                                    [
                                        "domain_uuid" => $session["domain_uuid"],
                                    ],
                                "bindTypes" => [Column::BIND_PARAM_STR],
                            ]
                        );
                        foreach($vCallCenterQueues as $vCallCenterQueue) {
                            array_push($included, $vCallCenterQueue->queue_extension);
                        }
                    }
                    if ($parameters["type"] == 9) {
                        $extensions = explode(",", $qTimeSchedule->work_extensions);
                        $extensions = array_diff($extensions, $included);
                        $qTimeSchedule->work_extensions = implode(",", $extensions);
                    } else {
                        $extensions = explode(",", $qTimeSchedule->break_extensions);
                        $extensions = array_diff($extensions, $included);
                        $qTimeSchedule->break_extensions = implode(",", $extensions);
                    }
                    if (!$qTimeSchedule->update()) {
                        $this->db->rollback();
                        $messages = $qTimeSchedule->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AS1001)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                }
                foreach ($included as $extension) {
                    $vDialplans = VDialplans::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND dialplan_number = :dialplan_number: AND dialplan_order = :dialplan_order: AND dialplan_description != ''",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "dialplan_number" => strval($extension),
                                    "dialplan_order" => $parameters["type"] == 10 ? 5 : 10
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    if ($vDialplans) {
                        foreach ($vDialplans as $vDialplan) {
                            $vDialplanDetails = VDialplanDetails::find(
                                [
                                    "conditions" => "domain_uuid = :domain_uuid: AND dialplan_uuid = :dialplan_uuid:",
                                    "bind" =>
                                        [
                                            "domain_uuid" => $session["domain_uuid"],
                                            "dialplan_uuid" => $vDialplan->dialplan_uuid,
                                        ],
                                    "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                                ]
                            );
                            foreach ($vDialplanDetails as $vDialplanDetail) {
                                if (!$vDialplanDetail->delete()) {
                                    $this->db->rollback();
                                    $messages = $vDialplanDetail->getMessages();
                                    $message = "";
                                    foreach ($messages as $error) {
                                        $message .= $error . " ";
                                    }
                                    $response = json_encode(
                                        [
                                            "result" => "error",
                                            "message" => trim($message) . " (Code AS21007)",
                                            "content" => [],
                                        ]
                                    );
                                    $this->response->setContent($response);
                                    return $this->response;
                                }
                            }
                            if (!$vDialplan->delete()) {
                                $this->db->rollback();
                                $messages = $vDialplan->getMessages();
                                $message = "";
                                foreach ($messages as $error) {
                                    $message .= $error . " ";
                                }
                                $response = json_encode(
                                    [
                                        "result" => "error",
                                        "message" => trim($message) . " (Code AS21007)",
                                        "content" => [],
                                    ]
                                );
                                $this->response->setContent($response);
                                return $this->response;
                            }
                        }
                    }
                }
                if (file_exists("/var/cache/fusionpbx/dialplan.". $session["subdomain"])) {
                    unlink("/var/cache/fusionpbx/dialplan.". $session["subdomain"]);
                }
                if (file_exists("/var/cache/fusionpbx/dialplan.public")) {
                    unlink("/var/cache/fusionpbx/dialplan.public");
                }
                if (file_exists("/var/cache/ringq/dialplan.". $session["subdomain"])) {
                    unlink("/var/cache/ringq/dialplan.". $session["subdomain"]);
                }
                if (file_exists("/var/cache/ringq/dialplan.public")) {
                    unlink("/var/cache/ringq/dialplan.public");
                }
                $this->db->commit();
                $response = json_encode(
                    [
                        "result" => "success",
                        "message" => "Success, successfully removed all default schedules.",
                        "content" => [
                            "work_extensions" => $qTimeSchedule->work_extensions,
                            "break_extensions" => $qTimeSchedule->break_extensions,
                        ],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;


            }
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, invalid request made.",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
    }

    public function timeschedulingAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AT1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $this->redis->del("allDialplans-" . $session["subdomain"]);
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "int"));
            $parameters["voicemail"] = intval($this->request->getPost("voicemail", "int"));
            $parameters["destination_action"] = intval($this->request->getPost("destination_action", "int"));
            $parameters["day_week"] = intval($this->request->getPost("day_week", "int"));
            $parameters["start_time"] = intval($this->request->getPost("start_time", "int"));
            $parameters["end_time"] = intval($this->request->getPost("end_time", "int"));
            $parameters["extra_ranges"] = strval($this->request->getPost("extra_ranges", "string"));
            if (empty($parameters["type"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            $qTimeSchedule = QTimeSchedules::findFirst(
                [
                    "conditions" => "domain_uuid = :domain_uuid:",
                    "bind" =>
                        [
                            "domain_uuid" => $session["domain_uuid"],
                        ],
                    "bindTypes" => [Column::BIND_PARAM_STR],
                ]
            );
            if ($qTimeSchedule) {
                if ($parameters["type"] == 3 || $parameters["type"] == 4) {
                    $this->db->begin();
                    if ($parameters["voicemail"] == 1) {
                        $parameters["destination_action"] = "*99". $parameters["destination_action"];
                    }
                    $dialplan_name = $parameters["type"] == 3 ? "nonwork-" : "break-";
                    $dial_playback = $parameters["type"] == 3 ? '<action application="lua" data="streamfile.lua misc/sorry_non-office_hour.wav"/>' : '<action application="lua" data="streamfile.lua misc/sorry_break-time.wav"/>';
                    if ($parameters["type"] == 3) {
                        $qTimeSchedule->work_default = $parameters["destination_action"];
                    }
                    if ($parameters["type"] == 4) {
                        $qTimeSchedule->break_default = $parameters["destination_action"];
                    }
                    $qTimeSchedule->update_user = $session["user_uuid"];
                    $qTimeSchedule->update_date = date("Y-m-d H:i:s");
                    if (!$qTimeSchedule->update()) {
                        $this->db->rollback();
                        $messages = $qTimeSchedule->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
