    public function timescheduling2Action()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AT21000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $parameters = array();
            $parameters["id"] = intval($this->request->getPost("id", "int"));
            $parameters["type"] = intval($this->request->getPost("type", "int"));
            $parameters["day"] = intval($this->request->getPost("day", "int"));
            $parameters["month"] = intval($this->request->getPost("month", "int"));
            $parameters["year"] = intval($this->request->getPost("year", "int"));
            $parameters["day2"] = intval($this->request->getPost("day2", "int"));
            $parameters["month2"] = intval($this->request->getPost("month2", "int"));
            $parameters["year2"] = intval($this->request->getPost("year2", "int"));
            $parameters["start_time"] = intval($this->request->getPost("start_time", "int"));
            $parameters["end_time"] = intval($this->request->getPost("end_time", "int"));
            $parameters["recurring"] = intval($this->request->getPost("recurring", "int"));
            $parameters["extension"] = intval($this->request->getPost("extension", "int"));
            $parameters["exemptions"] = $this->request->getPost("exemptions", "string");
            $parameters["timezone"] = $this->request->getPost("timezone", "string");
            $parameters["holiday_name"] = $this->request->getPost("holiday_name", "string");
            $parameters["holiday_greeting"] = $this->request->getPost("holiday_greeting", "string");
            if (empty($parameters["type"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            // Holiday audio is played from public/audio/<recording_filename>. Apps send the recording's
            // display name (or the full path the global default stores), so resolve it here.
            if (in_array(intval($parameters["type"]), [1, 2, 4, 5]) && !empty($parameters["holiday_greeting"])) {
                $parameters["holiday_greeting"] = $this->holidayGreetingFile($session["domain_uuid"], $parameters["holiday_greeting"]);
            }
            $holidayForm = new HolidayForm();
            if (!$holidayForm->isValid($parameters)) {
                $messages = $holidayForm->getMessages();
                $message = "";
                foreach ($messages as $error) {
                    $message .= $error . " ";
                }
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => trim($message) . " (Code AT2001)",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            $security = new \Phalcon\Security\Random();
            if ($parameters["type"] == 1) {
                $this->db->begin();
                $exemptions = array();
                if (!empty($this->request->getPost("exemptions", "string"))) {
                    $exemptions = explode(",", $this->request->getPost("exemptions", "string"));
                }
                $holiday_uuid = $security->uuid();
                $qHoliday = new QHolidays();
                $qHoliday->domain_uuid = $session["domain_uuid"];
                $qHoliday->holiday_uuid = $holiday_uuid;
                $qHoliday->holiday_name = $parameters["holiday_name"];
                $qHoliday->holiday_greeting = $parameters["holiday_greeting"];
                $qHoliday->day = $parameters["day"];
                $qHoliday->month = $parameters["month"];
                $qHoliday->year = $parameters["year"];
                $qHoliday->day2 = $parameters["day2"];
                $qHoliday->month2 = $parameters["month2"];
                $qHoliday->year2 = $parameters["year2"];
                $qHoliday->recurring = $parameters["recurring"] != "0" ? 1 : 0;
                if ($parameters["start_time"] == "0" && $parameters["end_time"] == "1440") {
                    $qHoliday->time = null;
                } else {
                    $qHoliday->time = $parameters["start_time"] . "-" . $parameters["end_time"];
                }
                $qHoliday->insert_user = $session["user_uuid"];
                $qHoliday->insert_date = date("Y-m-d H:i:s");
