                    $vDialplan->dialplan_xml = $xml;
                    $vDialplan->dialplan_name = "global-timezone";
                    $vDialplan->dialplan_order = 0;
                    $vDialplan->dialplan_context = $session["subdomain"];
                    $vDialplan->dialplan_continue = "true";
                    $vDialplan->dialplan_enabled = "true";
                    $vDialplan->insert_user = $session["user_uuid"];
                    $vDialplan->insert_date = date("Y-m-d H:i:s");
                    if (!$vDialplan->create()) {
                        $this->db->rollback();
                        $messages = $vDialplan->getMessages();
                        $message = "";
                        foreach ($messages as $error) {
                            $message .= $error . " ";
                        }
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => trim($message) . " (Code AS1002)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                }
                if (file_exists("/var/cache/fusionpbx/dialplan." . $session["subdomain"])) {
                    unlink("/var/cache/fusionpbx/dialplan." . $session["subdomain"]);
                }
                if (file_exists("/var/cache/ringq/dialplan." . $session["subdomain"])) {
                    unlink("/var/cache/ringq/dialplan." . $session["subdomain"]);
                }
 
                $setTimezone = new Process(['sudo', 'timedatectl', 'set-timezone', $parameters["timezone"]]);
                $setTimezone->setTimeout(600);
                $setTimezone->run();

                if (!$setTimezone->isSuccessful()) {
                    $response = json_encode([
                        "result" => "error",
                        "message" => $setTimezone->getErrorOutput(),
                        "content" => [],
                    ]);

                } else {
                    $response = json_encode([
                        "result" => "success",
                        "message" => "Successfully selected default timezone.",
                        "content" => [],
                    ]);

                    echo $response;

                    fastcgi_finish_request();

                    $phpReload = new Process(['sudo', 'service', 'php7.4-fpm', 'reload']);
                    $phpReload->setTimeout(600);
                    $phpReload->run();
                }
                $this->response->setContent($response);
                return $this->response;
            }
        }
    }

    public function searchAction($type = 1, $search = "", $page = 1, $startStamp = 0, $endStamp = 0)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
            $type = intval($type);
            if ($this->request->isGet()) {
                $offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                $keyword = strtolower($this->filter->sanitize($search, "string"));
                $timezone = date_default_timezone_get();
                $vUserSettings = VUserSettings::findFirst(
                    [
                        "conditions" => "domain_uuid = :domain_uuid: AND user_setting_subcategory = :user_setting_subcategory:",
                        "bind" =>
                            [
                                "domain_uuid" => $session["domain_uuid"],
                                "user_setting_subcategory" => "time_zone"
                            ],
                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                    ]
                );
                if ($vUserSettings) {
                    $timezone = $vUserSettings->user_setting_value;
                }
                if ($type == 1) {
                    $vExtensions = VExtensions::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND extension != :extension: AND extension LIKE :keyword:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "extension" => $session["extension"],
                                    "keyword" => "%". $keyword ."%"
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT, Column::BIND_PARAM_STR],
                            "limit" => 20,
                            "offset" => $offset
                        ]
                    );
                    $count = VExtensions::count(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND extension != :extension: AND extension LIKE :keyword:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "extension" => $session["extension"],
                                    "keyword" => "%". $keyword ."%"
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_INT, Column::BIND_PARAM_STR],
                        ]
                    );
                    $index = 0;
                    $content = [];
                    foreach ($vExtensions as $vExtension) {
                        $content[$index]["extension"] = $vExtension->extension;
                        $content[$index]["extension2"] = $vExtension->number_alias;
                        $content[$index]["username"] = $vExtension->vExtensionUsers->vUsers->username;
                        $content[$index]["firstname"] = $vExtension->vExtensionUsers->qUsers->first_name;
                        $content[$index]["lastname"] = $vExtension->vExtensionUsers->qUsers->last_name;
                        $content[$index]["image"] = $vExtension->vExtensionUsers->qUsers->image;
                        $content[$index]["group"] = $vExtension->vExtensionUsers->vUsers->vUserGroups->group_name;
                        $content[$index]["user_status"] = $vExtension->vExtensionUsers->vUsers->user_status;
                        $content[$index]["status"] = $this->redis->get("wallstatus:" . $session["subdomain"] . ":". $vExtension->extension);
                        $index++;
                    }
                    $response = json_encode(
                        [
                            "result" => "success",
                            "content" => $content,
                            "count" => $count,
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
                if ($type == 2) {  
                    // MR cHANGES LIKE to ILIKE for case insensitive search
                    $qContacts = QContacts::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND (company_name ILIKE :keyword: OR email ILIKE :keyword: OR phone ILIKE :keyword: OR first_name ILIKE :keyword: OR last_name ILIKE :keyword:)",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "keyword" => "%". $keyword ."%"
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                            "limit" => 20,
                            "offset" => $offset
                        ]
                    );
                    $count = QContacts::count(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND (company_name ILIKE :keyword: OR email ILIKE :keyword: OR phone ILIKE :keyword: OR first_name ILIKE :keyword: OR last_name ILIKE :keyword:)",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "keyword" => "%". $keyword ."%"
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    $index = 0;
                    $content = [];
                    foreach ($qContacts as $qContact) {
                        $content[$index]["id"] = $qContact->id;
                        $content[$index]["companyname"] = isset($qContact->company_name) ? ucfirst($qContact->company_name) : null;
                        $content[$index]["firstname"] = ucfirst($qContact->first_name);
                        $content[$index]["lastname"] = ucfirst($qContact->last_name);
                        $content[$index]["address_1"] = isset($qContact->address_1) ? $qContact->address_1 : null;
                        $content[$index]["address_2"] = isset($qContact->address_2) ? $qContact->address_2 : null;
                        $content[$index]["email"] = isset($qContact->email) ? $qContact->email : null;
                        $content[$index]["email2"] = isset($qContact->email2) ? $qContact->email2 : null;
                        $content[$index]["phone"] = $qContact->phone;
                        $content[$index]["phone2"] = isset($qContact->phone2) ? $qContact->phone2 : null;
                        $content[$index]["office_phone"] = isset($qContact->office_phone) ? $qContact->office_phone : null;
                        $content[$index]["whatsapp_phone"] = isset($qContact->whatsapp_phone) ? $qContact->whatsapp_phone : null;
                        $index++;
                    }
                    $response = json_encode(
