                if ($type == 4) {
                    // Aux codes report search: status, agent extension or name, newest first, within the chosen dates.
                    $conditions = "domain_uuid = :domain_uuid: AND (auxcode_status ILIKE :keyword: OR extension ILIKE :keyword: OR username ILIKE :keyword:)";
                    $bind = ["domain_uuid" => $session["domain_uuid"], "keyword" => "%" . $keyword . "%"];
                    if (intval($startStamp) > 0) {
                        $conditions .= " AND insert_date >= :startStamp:";
                        $bind["startStamp"] = $this->formatTimezoneUnix("Y-m-d H:i:sP", intval($startStamp), $timezone);
                    }
                    if (intval($endStamp) > 0) {
                        $conditions .= " AND insert_date <= :endStamp:";
