                    $content[$index]["call_answered_time"] = $qCallQueue->call_answered_time;
                    $content[$index]["call_waiting_time"] = $qCallQueue->call_waiting_time;
                    $content[$index]["call_end_time"] = $qCallQueue->call_end_time;
                    $content[$index]["call_time_to_answer"] = $qCallQueue->call_time_to_answer;
                    $content[$index]["insert_date"] = $qCallQueue->insert_date;
                    $index++;
                }
                $security = new \Phalcon\Security\Random();
                $filename = $security->uuid();
                $fp = fopen('/var/www/ringq/cache/'. $filename .'.csv', 'w');
                $header = ["Username", "Extension", "Date", "Auxcode"];
                fputcsv($fp, $header, ",");
                foreach ($content as $fields) { 
                    fputcsv($fp, $fields, ","); 
                }
                header('Content-Type: text/csv');
