                                    $uuid = $vDialplan->dialplan_uuid;
                                    if (!isset($alreadyAddedList[$uuid])) {
                                        $alreadyAddedList[$uuid] = true; 
                                        $xml .= "\n" . $vDialplan->dialplan_xml;
                                    }
                                }
                                $vDialplan2 = VDialplans::findFirst(
                                    [
                                        "conditions" => "domain_uuid = :domain_uuid: AND dialplan_name = :dialplan_name:",
                                        "bind" =>
                                            [
                                                "domain_uuid" => $session["domain_uuid"],
                                                "dialplan_name" => "outbound-rules"
                                            ],
                                        "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                                    ]
                                );
                                if ($vDialplan2) {
                                    if (empty($xml)) {
                                        if (!$vDialplan2->delete()) {
                                            $this->db->rollback();
                                            $messages = $vDialplan2->getMessages();
                                            $message = "";
                                            foreach ($messages as $error) {
                                                $message .= $error . " ";
                                            }
                                            $response = json_encode(
                                                [
                                                    "result" => "error",
                                                    "message" => trim($message) . " (Code AS1005)",
                                                    "content" => [],
                                                ]
                                            );
                                            $this->response->setContent($response);
                                            return $this->response;
                                        }
                                    } else {
                                        $vDialplan2->dialplan_enabled = "true";
                                        $vDialplan2->dialplan_xml = $xml;
                                        if (!$vDialplan2->update()) {
                                            $this->db->rollback();
                                            $messages = $vDialplan2->getMessages();
                                            $message = "";
                                            foreach ($messages as $error) {
                                                $message .= $error . " ";
                                            }
                                            $response = json_encode(
                                                [
                                                    "result" => "error",
                                                    "message" => trim($message) . " (Code AS1005)",
                                                    "content" => [],
                                                ]
                                            );
                                            $this->response->setContent($response);
                                            return $this->response;
                                        }
                                    }
                                } else {
                                    $outbound_uuid2 = $security->uuid();
                                    $vDialplan0 = new VDialplans();
                                    $vDialplan0->domain_uuid = $session["domain_uuid"];
                                    $vDialplan0->dialplan_uuid = $outbound_uuid2;
                                    $vDialplan0->app_uuid = $security->uuid();
                                    $vDialplan0->hostname = null;
                                    $vDialplan0->dialplan_xml = $xml;
                                    $vDialplan0->dialplan_name = "outbound-rules";
                                    $vDialplan0->dialplan_order = intval($parameters["emergency"]) == 1 ? 0 : 85;
                                    $vDialplan0->dialplan_context = $session["subdomain"];
                                    $vDialplan0->dialplan_continue = "false";
                                    $vDialplan0->dialplan_enabled = "true";
                                    $vDialplan0->insert_user = $session["user_uuid"];
                                    $vDialplan0->insert_date = date("Y-m-d H:i:s");
                                    if (!$vDialplan0->create()) {
                                        $this->db->rollback();
                                        $messages = $vDialplan0->getMessages();
                                        $message = "";
                                        foreach ($messages as $error) {
                                            $message .= $error . " ";
                                        }
                                        $response = json_encode(
                                            [
                                                "result" => "error",
                                                "message" => trim($message) . " (Code AS1002)",
                                                "content" => [],
                                            ]
                                        );
                                        $this->response->setContent($response);
                                        return $this->response;
                                    }
                                }
                              $this->db->commit();
                              if (file_exists("/var/cache/fusionpbx/dialplan.". $session["subdomain"])) {
                                  unlink("/var/cache/fusionpbx/dialplan.". $session["subdomain"]);
                              }
                              if (file_exists("/var/cache/ringq/dialplan.". $session["subdomain"])) {
                                  unlink("/var/cache/ringq/dialplan.". $session["subdomain"]);
                              }
                              $response = json_encode(
                                  [
                                      "result" => "success",
                                      "message" => "Successfully deleted outbound rule.",
                                  ]
                              );
                              $this->response->setContent($response);
                              return $this->response;
                            }
                        } else {
                            $this->db->rollback();
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => "Sorry, please check outbound rule entry.",
                                    "content" => [],
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                    } else {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Sorry, please check outbound rule entry.",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                }
            }
        }
    }

    public function uploadAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        if ($this->request->isGet()) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AU1000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AU1001)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if (!$this->request->hasFiles()) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, invalid request. No image attached.  (Code AU1002)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        $qUser = QUsers::findFirst(
            [
                "conditions" => "user_uuid = :user_uuid:",
                "bind" =>
                    [
                        "user_uuid" => $session["user_uuid"],
                    ],
                "bindTypes" => [Column::BIND_PARAM_STR],
            ]
        );
        if (!$qUser) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made. (Code AU1003)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        } else {
            $parameters = array();
            $imageForm = new ImageForm();
            if (!$imageForm->isValid(array_merge($parameters, $_FILES))) {
                $messages = $imageForm->getMessages();
                $message = "";
                foreach ($messages as $error) {
                    $message .= $error . " ";
                }
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => trim($message) . " (Code AU1004)",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            if (isset($this->request->getUploadedFiles()[0])) {
                $image = $this->request->getUploadedFiles()[0];
                if ($image->getSize() != NULL) {
                    $getType = $image->getRealType();
                    $allowType = ["image/gif", "image/jpg", "image/jpeg", "image/png", "image/webp"];
                    if (in_array($getType, $allowType)) {
                        $imageFile = new \Phalcon\Image\Adapter\Gd($image->getTempName());
                        if (!empty($qUser->image)) {
                            if (file_exists("/var/www/ringq/public/avr/".$qUser->image)) {
                                unlink("/var/www/ringq/public/avr/".$qUser->image);
                            }
                        }
                        $imageName = time() . (time() - 123456789) . "0.png";
                        $qUser->image = $imageName;
                        if (!$qUser->update()) {
                            $messages = $qUser->getMessages();
                            $message = "";
                            foreach ($messages as $error) {
                                $message .= $error . " ";
                            }
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => trim($message) . " (Code AU1004)",
                                    "content" => [],
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                        $imageFile->resize(300, null, Enum::WIDTH);
                        $imageFile->save("avr/" . $imageName, 95);
                        $this->redis->set($session["extension"] . ":" . $session["subdomain"], $imageName);
                        $response = json_encode(
                            [
                                "result" => "success",
                                "content" => $imageName,
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    } else {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Sorry, invalid image type. (Code AU1005)",
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                } else {
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => "Sorry, invalid request. No image attached. (Code AU1006)",
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            } else {
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => "Sorry, invalid request. No image attached. (Code AU1007)",
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
        }
    }

    public function upload2Action()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if (!$session) {
            $response = json_encode(
                [
                    "result" => "error",
                    "message" => "Sorry, unathorized request made (Code AU21000)",
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
        if ($this->request->isPost()) {
            $parameters = array();
            $parameters["type"] = intval($this->request->getPost("type", "string"));
            $parameters["extension"] = intval($this->request->getPost("extension", "int"));
            $parameters["greeting_name"] = $this->request->getPost("greeting_name", "string");
            $parameters["recording_filename"] = $this->request->getPost("recording_filename", "string");
            if (empty($parameters["recording_filename"])) {
                $contents = file_get_contents("php://input");
                $parameters = json_decode($contents, true);
            }
            $audioForm = new AudioForm();
            if (!$audioForm->isValid($parameters)) {
                $messages = $audioForm->getMessages();
                $message = "";
                foreach ($messages as $error) {
                    $message .= $error . " ";
                }
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => trim($message) . " (Code AU21001)",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            if (intval($parameters["type"]) == 6) {
                $vVoicemail = VVoicemails::findFirst([
                    "conditions" => "domain_uuid = :domain_uuid: AND voicemail_id = :voicemail_id:",
                    "bind" => [
                       "domain_uuid" => $session["domain_uuid"],
                       "voicemail_id" => strval(intval($parameters["extension"])),
                    ],
                    "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                 ]);
                    if (!$vVoicemail) {
                    $response = json_encode(
                     [
                           "result" => "error",
                           "message" => "Sorry, voicemail does not exists.",
                           "content" => [],
                     ]
                  );
                  $this->response->setContent($response);
                  return $this->response;
                    }
                    $vVoicemail->greeting_id = null;
                    if (!$vVoicemail->update()) {
                     $messages = $vVoicemail->getMessages();
                     $message = "";
                     foreach ($messages as $error) {
                        $message .= $error . " ";
                     }
                     $response = json_encode([
                        "result" => "error",
                        "message" => trim($message) . " (Code AC1002)",
                        "content" => [],
                     ]);
                     $this->response->setContent($response);
                     return $this->response;
                    }
                $response = json_encode(
                    [
                        "result" => "success",
                        "message" => "Successfully set to default.",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            if (!file_exists("/var/www/ringq/public/voice/". $parameters["recording_filename"])) {
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => "Sorry, sound file does not exists (Code AU21002)",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            $max = VVoicemailGreetings::maximum(
                [
                    "conditions" => "domain_uuid = :domain_uuid:",
                    "column" => "greeting_id",
                    "bind" =>
                        [
                            "domain_uuid" => $session["domain_uuid"]
                        ],
                ]
            );
            $greeting_name = "";
            if (intval($parameters["type"]) == 1) {
                $greeting_name = "available";
            }
            if (intval($parameters["type"]) == 2) {
                $greeting_name = "away";
            }
            if (intval($parameters["type"]) == 3) {
                $greeting_name = "busy";
            }
            if (intval($parameters["type"]) == 4) {
                $greeting_name = "custom1";
            }
            if (intval($parameters["type"]) == 5) {
                $greeting_name = "custom2";
            }
            $previous_greeting_name = "";
            $greeting_description = explode(".", $parameters["greeting_name"]);
            $security = new \Phalcon\Security\Random();
            $vVoicemailGreeting = VVoicemailGreetings::findFirst(
                [
                    "conditions" => "domain_uuid = :domain_uuid: AND voicemail_id = :voicemail_id: AND greeting_name = :greeting_name:",
                    "bind" =>
                        [
                            "domain_uuid" => $session["domain_uuid"],
                            "voicemail_id" => strval(intval($parameters["extension"])),
                            "greeting_name" => $greeting_name,
                        ],
                    "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                ]
            );
            if ($vVoicemailGreeting) {
                $previous_greeting_name = $vVoicemailGreeting->greeting_description;
                $vVoicemailGreeting->greeting_name = $greeting_name;
                $vVoicemailGreeting->greeting_filename = "greeting_". $vVoicemailGreeting->greeting_id .".wav";
                $vVoicemailGreeting->greeting_description = $greeting_description[0];
                $vVoicemailGreeting->update_user = $session["user_uuid"];
                $vVoicemailGreeting->update_date = date("Y-m-d H:i:s");
                if (!$vVoicemailGreeting->update()) {
                    $messages = $vVoicemailGreeting->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AU21003)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            } else {
                $vVoicemailGreeting = new VVoicemailGreetings();
                $vVoicemailGreeting->voicemail_greeting_uuid = $security->uuid();
                $vVoicemailGreeting->domain_uuid = $session["domain_uuid"];
                $vVoicemailGreeting->voicemail_id = strval( intval($parameters["extension"]));
                $vVoicemailGreeting->greeting_id = $max += 1;
                $vVoicemailGreeting->greeting_name = $greeting_name;
                $vVoicemailGreeting->greeting_filename = "greeting_". $vVoicemailGreeting->greeting_id .".wav";
                $vVoicemailGreeting->greeting_description = $greeting_description[0];
                $vVoicemailGreeting->insert_user = $session["user_uuid"];
                $vVoicemailGreeting->insert_date = date("Y-m-d H:i:s");
                if (!$vVoicemailGreeting->create()) {
                    $messages = $vVoicemailGreeting->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AU21003)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                }
            }
            if (!file_exists("/var/www/ringq/public/voice/". $parameters["recording_filename"])) {
                $response = json_encode(
                    [
                        "result" => "error",
                        "message" => "Sorry, sound file does not exists (Code AU21002)",
                        "content" => [],
                    ]
                );
                $this->response->setContent($response);
                return $this->response;
            }
            rename("/var/www/ringq/public/voice/". $parameters["recording_filename"], "/var/lib/freeswitch/storage/voicemail/default/". $session["subdomain"] ."/". $parameters["extension"] ."/greeting_". $vVoicemailGreeting->greeting_id .".wav");
            $response = json_encode(
                [
                    "result" => "success",
                    "message" => "Successfully added new audio file.",
                    "content" => [
                        "greeting" => $vVoicemailGreeting,
                        "previous" => $previous_greeting_name
                    ],
                ]
            );
            $this->response->setContent($response);
            return $this->response;
        }
    }

