    public function recordingsAction($type = 0, $record_uuid = "")
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
            if ($this->isPlainUser($session)) {
                return $this->forbiddenForUser();
            }
            if ($this->request->isGet()) {
                if ($type == 1 && !empty($record_uuid)) {
                    $parameters = array();
                    $parameters["record_uuid"] = $this->filter->sanitize($record_uuid, "string");
                    if (empty($parameters["record_uuid"])) {
                        $recordingForm = new RecordingForm();
                        if (!$recordingForm->isValid($parameters)) {
                            $messages = $recordingForm->getMessages();
                            $message = "";
                            foreach ($messages as $error) {
                                $message .= $error . " ";
                            }
                            $response = json_encode(
                                [
                                    "result" => "error",
                                    "message" => trim($message) . " (Code AA1000)",
                                    "content" => [],
                                ]
                            );
                            $this->response->setContent($response);
                            return $this->response;
                        }
                    }
                    $vXmlCdr = QRingqCdr::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND xml_cdr_uuid = :xml_cdr_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "xml_cdr_uuid" => $parameters["record_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    if (!$vXmlCdr) {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Recording does not exists anymore. (Code AA1000)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $path = $vXmlCdr->record_path . "/" . $vXmlCdr->record_name;
                    $this->response->setFileToSend($path, "voicemail.wav")->send();
                }
            }
            if ($this->request->isPost()) {
                $parameters = array();
                $parameters["record_uuid"] = $this->request->getPost("record_uuid", "string");
                if (empty($parameters["record_uuid"])) {
                    $contents = file_get_contents("php://input");
                    $parameters = json_decode($contents, true);
                }
                $recordingForm = new RecordingForm();
                if (!$recordingForm->isValid($parameters)) {
                    $messages = $recordingForm->getMessages();
                    $message = "";
                    foreach ($messages as $error) {
                        $message .= $error . " ";
                    }
                    $response = json_encode(
                        [
                            "result" => "error",
                            "message" => trim($message) . " (Code AA1000)",
                            "content" => [],
                        ]
                    );
                    $this->response->setContent($response);
                    return $this->response;
                } else {
                    $vXmlCdr = QRingqCdr::findFirst(
                        [
                            "conditions" => "domain_uuid = :domain_uuid: AND record_name = :record_name:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                    "record_name" => $parameters["record_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                        ]
                    );
                    if (!$vXmlCdr) {
                        $response = json_encode(
                            [
                                "result" => "error",
                                "message" => "Recording does not exists anymore. (Code AA1000)",
                                "content" => [],
                            ]
                        );
                        $this->response->setContent($response);
                        return $this->response;
                    }
                    $path = $vXmlCdr->record_path . "/" . $vXmlCdr->record_name;
                    $this->response->setFileToSend($path, "voicemail.wav")->send();
                }
            }
        } else {
            $this->response->redirect("https://" . $this->request->getHttpHost() . "/403forbidden.html");
        }
    }

    public function voicemailsAction($page = 1, $type = 1)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $session = $this->session->get("auth");
        if ($session) {
            if ($this->request->isGet()) {
                $offset = $page > 1 ? intval($page) * 20 - 20 : 0;
                if ($type == 1 && $this->isPlainUser($session)) {
                    $type = 2;
                }
                if ($type == 1) {
                    $vVoicemailMessages = VVoicemailMessages::find(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                            "limit" => 20,
                            "offset"=> $offset,
                            'order' => 'created_epoch DESC'
                        ]
                    );
                    $count = VVoicemailMessages::count(
                        [
                            "conditions" => "domain_uuid = :domain_uuid:",
                            "bind" =>
                                [
                                    "domain_uuid" => $session["domain_uuid"],
                                ],
                            "bindTypes" => [Column::BIND_PARAM_STR],
                        ]
                    );
                    $index = 0;
                    $content = array();
                    foreach ($vVoicemailMessages as $vVoicemailMessage) {
