    /** Recording display name, stored file name or full audio path -> file name under public/audio. */
    private function holidayGreetingFile($domainUuid, $greeting)
    {
        $greeting = trim(strval($greeting));
        $prefix = "/var/www/ringq/public/audio/";
        while (strpos($greeting, $prefix) === 0) {
            $greeting = substr($greeting, strlen($prefix));
        }
        $qRecording = QRecordings::findFirst(
            [
                "conditions" => "domain_uuid = :domain_uuid: AND recording_name = :recording_name:",
                "bind" => ["domain_uuid" => $domainUuid, "recording_name" => $greeting],
                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
                "order" => "insert_date DESC",
            ]
        );
        if ($qRecording && !empty($qRecording->recording_filename)) {
            return basename($qRecording->recording_filename);
        }
        return basename($greeting);
    }

    /**
     * Extra time windows for one day of office or break hours, sent as
     * "start_end.start_end" (minutes, same end convention as the main pair).
     */
    private function scheduleExtraRanges($value)
    {
        $value = is_scalar($value) ? trim(strval($value)) : "";
        if ($value === "" || !preg_match('/^\d{1,4}_\d{1,4}(\.\d{1,4}_\d{1,4}){0,11}$/', $value)) {
            return [];
        }
        $ranges = [];
        foreach (explode(".", $value) as $pair) {
            list($start, $end) = array_map("intval", explode("_", $pair));
            if ($start >= $end || $end > 1440) {
                return [];
            }
            $ranges[] = [$start, $end];
        }
        return $ranges;
    }

    private function scheduleExtraSuffix($value)
    {
        $ranges = $this->scheduleExtraRanges($value);
        if (empty($ranges)) {
            return "";
        }
        return "-". implode(".", array_map(function ($range) { return $range[0] ."_". $range[1]; }, $ranges));
    }

    /**
     * minute-of-day for a nonwork/break rule. Office rules arrive swapped
     * ($a = office end, $b = office start) so the reversed range matches
     * outside office hours; break rules are a plain $a-$b range. Extra
     * windows turn this into a comma list.
     */
    private function scheduleMinuteOfDay($a, $b, $extra = "")
    {
        $a = intval($a);
        $b = intval($b);
        $ranges = $this->scheduleExtraRanges($extra);
        if (empty($ranges) || $a == $b) {
            return $a ."-". $b;
        }
        $office = $a > $b;
        $ranges[] = $office ? [$b, $a] : [$a, $b];
        usort($ranges, function ($x, $y) { return $x[0] - $y[0]; });
        $merged = [];
        foreach ($ranges as $range) {
            $last = count($merged) - 1;
            if ($last >= 0 && $range[0] <= $merged[$last][1]) {
                $merged[$last][1] = max($merged[$last][1], $range[1]);
            } else {
                $merged[] = $range;
            }
        }
        $parts = [];
        if ($office) {
            $parts[] = $merged[count($merged) - 1][1] ."-". $merged[0][0];
            for ($i = 0; $i < count($merged) - 1; $i++) {
                $parts[] = $merged[$i][1] ."-". $merged[$i + 1][0];
            }
        } else {
            foreach ($merged as $range) {
                $parts[] = $range[0] ."-". $range[1];
            }
        }
        return implode(",", $parts);
    }

    private function regexRangeExpression($from, $to)
    {
        if($from < 0 || $to < 0) {
            throw new Exception("Negative values not supported");
        }

        if($from > $to) {
            throw new Exception("Invalid range $from..$to, from > to");
        }

        $ranges = array($from);
        $increment = 1;
        $next = $from;
        $higher = true;

        while(true) {
            $next += $increment;
            if($next + $increment > $to) {
                if($next <= $to) {
                    $ranges[] = $next;
                }
                $increment /= 10;
                $higher = false;
            }
            else if($next % ($increment*10) === 0) {
                $ranges[] = $next;
                $increment = $higher ? $increment*10 : $increment/10;
            }
            
            if(!$higher && $increment < 1) { // Changed < 10 to < 1 for precision
                break;
            }
        }

        $ranges[] = $to + 1;
        $ranges = array_unique($ranges);
        sort($ranges);

        $parts = []; // Use an array for parts to handle the OR pipe better

        for($i = 0; $i < count($ranges) - 1; $i++) {
            $str_from = (string)($ranges[$i]);
            $str_to = (string)($ranges[$i + 1] - 1);
            
            $part = "";
            for($j = 0; $j < strlen($str_from); $j++) {
                if($str_from[$j] == $str_to[$j]) {
                    $part .= $str_from[$j];
                } else {
                    $part .= "[" . $str_from[$j] . "-" . $str_to[$j] . "]";
                }
            }
            $parts[] = $part;
        }

        // Wrap in start/end anchors and join with |
        return "^(" . implode('|', $parts) . ")$";
    }

    // Emergency rules may only name exact emergency numbers (911, 112, 999 ...),
    // comma separated. An empty or wildcard prefix would match ordinary calls.
    private function validEmergencyNumbers($prefixPattern) {
        $numbers = explode(",", str_replace(" ", "", (string) $prefixPattern));
        foreach ($numbers as $number) {
            if (!preg_match('/^[0-9]{2,6}$/', $number)) {
                return false;
            }
        }
        return true;
    }

    private function emergencyIdChecker($domainUuid, $extensionId) {
        $groupChecker = VRingGroups::findFirst(
            [
                "conditions" => "domain_uuid = :domain_uuid: AND ring_group_extension = :ring_group_extension:",
                "bind" =>
                    [
                        "domain_uuid" => $domainUuid,
                        "ring_group_extension" => $extensionId,
                    ],
                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
            ]
        );
        if ($groupChecker) {
            return false;
        }
        $extensionChecker = VExtensions::findFirst(
            [
                "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
                "bind" =>
                    [
                        "domain_uuid" => $domainUuid,
                        "extension" => $extensionId,
                    ],
                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
            ]
        );
        if ($extensionChecker) {
            return false;
        }
        $sipIpChecker = QCallBehaviors::findFirst(
            [
                "conditions" => "domain_uuid = :domain_uuid: AND force_ping = :force_ping:",
                "bind" =>
                    [
                        "domain_uuid" => $domainUuid,
                        "force_ping" => $extensionId,
                    ],
                "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
            ]
        );
        if ($sipIpChecker) {
            return false;
        }
        return true;
    }

    protected function formatTimezoneString($dateString, $format, $targetTimezone) {
        $date = new DateTime($dateString);
        $date->setTimezone(new DateTimeZone($targetTimezone));
        return $date->format($format);
    }

    protected function formatTimezoneUnix($format, $unixTime = 0, $timezone) {
        $result = "";
        if ($unixTime != 0) {
            $timestamp = $unixTime;
            $timezone = new DateTimeZone($timezone);
            $date = new DateTime("@$timestamp"); 
            $date->setTimezone($timezone);
            $result = $date->format($format);
        }
        return $result;
    }

    protected function pruneMusicOnHoldOrphans($domainUuid, $subdomain)
    {
        $keep = array();
        $qRecordings = QRecordings::find(
            [
                "conditions" => "domain_uuid = :domain_uuid: AND type = 5",
                "bind" =>
                    [
                        "domain_uuid" => $domainUuid,
                    ],
                "bindTypes" => [Column::BIND_PARAM_STR],
            ]
        );
        foreach ($qRecordings as $qRecording) {
            $base = explode("_", $qRecording->recording_filename);
            $base = basename(current($base));
            if ($base !== "") {
                $keep[$base] = true;
            }
        }
        foreach (["8000", "16000", "32000", "48000"] as $rate) {
            $dir = "/usr/share/freeswitch/sounds/music/". $subdomain ."/". $rate;
            if (!is_dir($dir)) {
                continue;
            }
            $files = glob($dir . "/*.wav");
            if ($files === false) {
                continue;
            }
            foreach ($files as $file) {
                if (!isset($keep[basename($file, ".wav")])) {
                    unlink($file);
                }
            }
        }
    }

    protected function reloadMusicOnHold($subdomain)
    {
        try {
            foreach (
                [
                    "/var/cache/ringq/configuration.local_stream.conf",
                    "/var/cache/ringq/configuration.local_stream.conf." . gethostname(),
                    "/var/cache/ringq/dialplan." . $subdomain,
                ] as $cached
            ) {
                if (file_exists($cached)) {
                    unlink($cached);
                }
            }
            $client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:3000", [
                "persistent" => false,
            ]));
            $client->initialize();
            $client->emit("localstreamreload", ["subdomain" => $subdomain]);
        } catch (\Throwable $e) {
            error_log("music on hold reload failed: " . $e->getMessage());
        }
    }
    protected function isFolderEmpty($folder) {
        // Check if directory exists and is readable
        if (!is_dir($folder) || !is_readable($folder)) {
            return false;
        }

        // Scan the directory
        $files = scandir($folder);

        // Remove . and .. from result
        return count(array_diff($files, ['.', '..'])) === 0;
    }

    protected function isUuid(string $value): bool {
        return preg_match(
            '/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i',
            $value
        ) === 1;
    }

    private function activeSipProfileSetting($name)
    {
        try {
            $row = $this->db->fetchOne(
                "SELECT s.sip_profile_setting_value FROM v_sip_profile_settings s
                   JOIN v_sip_profiles p ON p.sip_profile_uuid = s.sip_profile_uuid
                  WHERE s.sip_profile_setting_name = :name AND COALESCE(s.sip_profile_setting_value, '') <> ''
                  ORDER BY CASE WHEN p.sip_profile_enabled::text = 'true' AND s.sip_profile_setting_enabled::text = 'true' THEN 0 ELSE 1 END,
                           CASE p.sip_profile_name WHEN 'internal' THEN 0 WHEN 'external' THEN 1 ELSE 2 END
                  LIMIT 1",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["name" => $name]
            );
        } catch (\Throwable $e) {
            error_log("activeSipProfileSetting: " . $e->getMessage());
            return "";
        }
        return $row ? (string) $row["sip_profile_setting_value"] : "";
    }

    public function getExternalInterfaces() {
        $output = shell_exec("ip -4 -brief addr");
        
        if (is_null($output)) {
            return ["error" => "Command failed."];
        }

        $lines = explode("\n", trim($output));
        $result = [];

        foreach ($lines as $line) {
            $parts = preg_split('/\s+/', $line);

            if (count($parts) >= 2) {
                $name = $parts[0];
                
                // 1. Skip if the interface is 'lo' (localhost)
                if ($name === 'lo') {
                    continue;
                }

                $status = $parts[1];
                $ipRaw  = isset($parts[2]) ? $parts[2] : 'N/A';

                // 2. Remove the CIDR suffix (e.g., /24) to get just the IP
                $cleanIp = explode('/', $ipRaw)[0];

                $result[] = [
                    'interface' => $name,
                    'status'    => $status,
                    'ip'        => $cleanIp
                ];
            }
        }

        return $result;
    }

    public function isInternalRequest() {
        $remote = $_SERVER['REMOTE_ADDR'] ?? '';
        $server = $_SERVER['SERVER_ADDR'] ?? '';

        // Check for standard match or loopback addresses
        return ($remote === $server) || ($remote === '127.0.0.1') || ($remote === '::1');
    }

    function getServerPublicIP() {
        // List of reliable APIs to check (fallbacks in case one is down)
        $services = [
            'https://api.ipify.org',
            'https://icanhazip.com',
            'https://ifconfig.me/ip'
        ];

        foreach ($services as $url) {
            // Method 1: Try using cURL if available
            if (function_exists('curl_init')) {
                $ch = curl_init();
                curl_setopt($ch, CURLOPT_URL, $url);
                curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
                curl_setopt($ch, CURLOPT_TIMEOUT, 3); // 3-second timeout
                $ip = curl_exec($ch);
                curl_close($ch);

                if ($ip !== false && filter_var(trim($ip), FILTER_VALIDATE_IP)) {
                    return trim($ip);
                }
            }

            // Method 2: Fallback to file_get_contents if allow_url_fopen is enabled
            if (ini_get('allow_url_fopen')) {
                $context = stream_context_create(['http' => ['timeout' => 3]]);
                $ip = @file_get_contents($url, false, $context);
                
                if ($ip !== false && filter_var(trim($ip), FILTER_VALIDATE_IP)) {
                    return trim($ip);
                }
            }
        }

        return false;
    }
    // Outbound lookup for api/index with a short redis cache and bounded
    // timeouts, so an owner login never waits on (or dies with) a slow or
    // unreachable license server. Returns the response body or false.
    private function cachedLoginLookup($cacheKey, $ttl, $url, $jsonBody)
    {
        $cached = $this->redis->get($cacheKey);
        if ($cached) {
            return (string) $cached;
        }
        $options = [
            CURLOPT_URL => $url,
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_ENCODING => "",
            CURLOPT_MAXREDIRS => 10,
            CURLOPT_CONNECTTIMEOUT => 5,
            CURLOPT_TIMEOUT => 15,
            CURLOPT_FOLLOWLOCATION => true,
            CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
        ];
        if ($jsonBody !== null) {
            $options[CURLOPT_CUSTOMREQUEST] = "POST";
            $options[CURLOPT_HTTPHEADER] = ["Accept: application/json", "Content-Type: application/json"];
            $options[CURLOPT_POSTFIELDS] = $jsonBody;
        }
        $curl = curl_init();
        curl_setopt_array($curl, $options);
        $response = curl_exec($curl);
        $httpCode = (int) curl_getinfo($curl, CURLINFO_HTTP_CODE);
        if ($response === false) {
            error_log("api/index lookup {$url}: " . curl_error($curl));
        }
        curl_close($curl);
        if ($response === false || $httpCode < 200 || $httpCode >= 300 || json_decode((string) $response, true) === null) {
            return false;
        }
        $this->redis->setex($cacheKey, (int) $ttl, (string) $response);
        return (string) $response;
    }

    // ───────────────────────────────────────────────────────────────
    // User preferences: one JSON document per user within the tenant
    // (q_user_preferences), for settings the web client used to keep only
    // in the browser (dialer size, wallboard and Call Flow layouts, ...).
    //
    //   GET  /api/user/preferences  -> {"result":"success","content":{...}}
    //   PUT  /api/user/preferences  body: only the changed keys
    //   POST /api/user/preferences  same as PUT
    //
    // Keys are merged into the stored document, never replacing it, and a
    // key sent as null is deleted. The merge is one SQL statement, so two
    // tabs saving different keys at the same time cannot wipe each other.
    // POST is accepted because the :8443 vhost does not list PUT in
    // Access-Control-Allow-Methods, so browsers refuse a cross-origin PUT.
    // A form-encoded body carries the JSON as a "preferences" field.
    // ───────────────────────────────────────────────────────────────

    private const USER_PREFERENCES_MAX_BYTES = 262144;
    private const USER_PREFERENCES_MAX_KEY_LENGTH = 128;

    public function sipcredentialsAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["domain_uuid"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isGet()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "GET required."]));
            return $this->response;
        }
        $vExtension = VExtensions::findFirst([
            "conditions" => "domain_uuid = :domain_uuid: AND extension = :extension:",
            "bind" => [
                "domain_uuid" => (string) $session["domain_uuid"],
                "extension" => (string) $session["extension"],
            ],
            "bindTypes" => [Column::BIND_PARAM_STR, Column::BIND_PARAM_STR],
        ]);
        if (!$vExtension) {
            $this->response->setStatusCode(404, "Not Found");
            $this->response->setContent(json_encode(["result" => "error", "message" => "No extension assigned to this user."]));
            return $this->response;
        }
        $this->response->setContent(json_encode([
            "result" => "success",
            "content" => [
                "extension" => (string) $vExtension->extension,
                "sip_username" => (string) ($vExtension->number_alias ?: $vExtension->extension),
                "sip_password" => (string) $vExtension->password,
                "domain" => (string) ($session["subdomain"] ?? $vExtension->accountcode),
            ],
        ]));
        return $this->response;
    }

    public function listsAction($resource = "", $id = "")
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["domain_uuid"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isGet()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "GET required."]));
            return $this->response;
        }
        $resource = strtolower((string) $resource);
        $adminLists = ["queues", "ivrs", "dids", "holidays", "officehours", "trunks", "queue", "ivr", "calls", "numbers", "recordings", "deskphones", "roles", "chats", "chat", "sipprofiles", "dbowners", "queueagents", "push", "cdrpipeline", "mail", "updatehealth", "outboundrule", "aiagent", "permissions"];
        if (!in_array($resource, array_merge($adminLists, ["devices", "extension"]), true)) {
            $this->response->setStatusCode(404, "Not Found");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unknown list."]));
            return $this->response;
        }
        if (in_array($resource, $adminLists, true) && $this->isPlainUser($session)) {
            $this->response->setStatusCode(403, "Forbidden");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Sorry, you can only access your own records. (Code AC4031)"]));
            return $this->response;
        }
        $domain = (string) $session["domain_uuid"];
        $assoc = \Phalcon\Db\Enum::FETCH_ASSOC;
        $content = [];
        $routedDids = function (string $type) use ($domain, $assoc): array {
            $out = [];
            foreach ($this->db->fetchAll(
                "SELECT did_number, extension FROM q_dids WHERE domain_uuid = CAST(:domain AS uuid) AND type::text = :type ORDER BY did_number",
                $assoc,
                ["domain" => $domain, "type" => $type]
            ) as $row) {
                $out[(string) $row["extension"]][] = (string) $row["did_number"];
            }
            return $out;
        };
        if ($resource === "recordings") {
            $uses = ["1" => "ivr", "2" => "queue", "5" => "music_on_hold"];
            foreach ($this->db->fetchAll(
                "SELECT recording_name, recording_filename, type FROM q_recordings WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY type, recording_name",
                $assoc,
                ["domain" => $domain]
            ) as $row) {
                $type = (string) $row["type"];
                $content[] = [
                    "name" => (string) $row["recording_name"],
                    "file" => (string) $row["recording_filename"],
                    "use" => $uses[$type] ?? "other",
                ];
            }
        } elseif ($resource === "numbers") {
            $sources = [
                "extension" => "SELECT extension AS n FROM v_extensions WHERE domain_uuid = CAST(:domain AS uuid)",
                "queue" => "SELECT queue_extension AS n FROM v_call_center_queues WHERE domain_uuid = CAST(:domain AS uuid)",
                "ivr" => "SELECT ivr_menu_extension AS n FROM v_ivr_menus WHERE domain_uuid = CAST(:domain AS uuid)",
                "conference" => "SELECT conference_center_extension AS n FROM v_conference_centers WHERE domain_uuid = CAST(:domain AS uuid)",
                "group" => "SELECT ring_group_extension AS n FROM v_ring_groups WHERE domain_uuid = CAST(:domain AS uuid)",
                "fax" => "SELECT fax_extension AS n FROM v_fax WHERE domain_uuid = CAST(:domain AS uuid)",
            ];
            foreach ($sources as $kind => $sql) {
                foreach ($this->db->fetchAll($sql, $assoc, ["domain" => $domain]) as $row) {
                    $number = trim((string) $row["n"]);
                    if ($number !== "") {
                        $content[] = ["number" => $number, "kind" => $kind];
                    }
                }
            }
        } elseif ($resource === "queues") {
            $queues = $this->db->fetchAll(
                "SELECT call_center_queue_uuid::text AS uuid, queue_name, queue_extension, queue_strategy, queue_timeout_action, queue_max_wait_time, queue_max_callers, queue_description
                   FROM v_call_center_queues WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY queue_extension",
                $assoc,
                ["domain" => $domain]
            );
            $tiers = $this->db->fetchAll(
                "SELECT t.call_center_queue_uuid::text AS queue, a.agent_name, e.extension, t.tier_level, t.tier_position
                   FROM v_call_center_tiers t
                   JOIN v_call_center_agents a ON a.call_center_agent_uuid = t.call_center_agent_uuid
                   LEFT JOIN v_extensions e ON e.domain_uuid = a.domain_uuid AND e.number_alias = a.agent_id
                  WHERE t.domain_uuid = CAST(:domain AS uuid)
                  ORDER BY t.tier_level, t.tier_position, a.agent_name",
                $assoc,
                ["domain" => $domain]
            );
            $dids = $routedDids("2");
            $agents = [];
            foreach ($tiers as $tier) {
                $agents[(string) $tier["queue"]][] = [
                    "name" => (string) $tier["agent_name"],
                    "extension" => (string) ($tier["extension"] ?? ""),
                    "level" => (int) $tier["tier_level"] + 1,
                    "position" => (int) $tier["tier_position"] + 1,
                ];
            }
            foreach ($queues as $queue) {
                $content[] = [
                    "extension" => (string) $queue["queue_extension"],
                    "name" => (string) $queue["queue_name"],
                    "strategy" => (string) $queue["queue_strategy"],
                    "timeoutAction" => (string) $queue["queue_timeout_action"],
                    "maxWaitSeconds" => (int) $queue["queue_max_wait_time"],
                    "maxCallers" => (int) $queue["queue_max_callers"],
                    "description" => (string) $queue["queue_description"],
                    "agents" => $agents[(string) $queue["uuid"]] ?? [],
                    "dids" => $dids[(string) $queue["queue_extension"]] ?? [],
                ];
            }
        } elseif ($resource === "ivrs") {
            $menus = $this->db->fetchAll(
                "SELECT ivr_menu_uuid::text AS uuid, ivr_menu_name, ivr_menu_extension, ivr_menu_timeout, ivr_menu_exit_app, ivr_menu_exit_data, ivr_menu_direct_dial, ivr_menu_enabled, ivr_menu_description
                   FROM v_ivr_menus WHERE domain_uuid = CAST(:domain AS uuid) AND ivr_menu_extension > '5000' ORDER BY ivr_menu_extension",
                $assoc,
                ["domain" => $domain]
            );
            $rows = $this->db->fetchAll(
                "SELECT ivr_menu_uuid::text AS uuid, ivr_menu_option_digits, ivr_menu_option_action, ivr_menu_option_param
                   FROM v_ivr_menu_options WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY ivr_menu_option_digits",
                $assoc,
                ["domain" => $domain]
            );
            $dids = $routedDids("1");
            $options = [];
            foreach ($rows as $row) {
                $param = trim((string) $row["ivr_menu_option_param"]);
                $parts = preg_split('/\s+/', $param);
                $options[(string) $row["uuid"]][] = [
                    "digits" => (string) $row["ivr_menu_option_digits"],
                    "action" => (string) ($parts[0] ?? ""),
                    "destination" => (string) ($parts[1] ?? ""),
                ];
            }
            foreach ($menus as $menu) {
                $content[] = [
                    "extension" => (string) $menu["ivr_menu_extension"],
                    "name" => (string) $menu["ivr_menu_name"],
                    "enabled" => (string) $menu["ivr_menu_enabled"] !== "false",
                    "timeoutSeconds" => (int) round(((int) $menu["ivr_menu_timeout"]) / 1000),
                    "timeoutAction" => trim((string) $menu["ivr_menu_exit_app"] . " " . (string) $menu["ivr_menu_exit_data"]),
                    "directDial" => (string) $menu["ivr_menu_direct_dial"] === "true",
                    "description" => (string) $menu["ivr_menu_description"],
                    "options" => $options[(string) $menu["uuid"]] ?? [],
                    "dids" => $dids[(string) $menu["ivr_menu_extension"]] ?? [],
                ];
            }
        } elseif ($resource === "dids") {
            $kinds = ["1" => "ivr", "2" => "queue", "3" => "extension", "4" => "conference", "6" => "efax", "7" => "group", "8" => "mailfax"];
            $rows = $this->db->fetchAll(
                "SELECT did_number, type, name, extension, outbound, sip_trunk_name, country
                   FROM q_dids WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY did_number",
                $assoc,
                ["domain" => $domain]
            );
            foreach ($rows as $row) {
                $type = (string) $row["type"];
                $content[] = [
                    "number" => (string) $row["did_number"],
                    "destinationType" => $kinds[$type] ?? ($type === "" ? "unassigned" : "other"),
                    "destination" => (string) $row["extension"],
                    "destinationName" => (string) $row["name"],
                    "outbound" => (int) $row["outbound"] === 1,
                    "trunk" => (string) $row["sip_trunk_name"],
                    "country" => (string) $row["country"],
                ];
            }
        } elseif ($resource === "calls") {
            foreach ($this->tenantChannels((string) $session["subdomain"]) as $row) {
                $presence = (string) ($row["presence_id"] ?? "");
                $created = (string) ($row["created_epoch"] ?? "");
                $content[] = [
                    "uuid" => (string) ($row["uuid"] ?? ""),
                    "direction" => (string) ($row["direction"] ?? ""),
                    "state" => (string) ($row["callstate"] ?? ($row["state"] ?? "")),
                    "from" => (string) ($row["cid_num"] ?? ""),
                    "to" => (string) ($row["dest"] ?? ""),
                    "extension" => $presence === "" ? "" : (string) strstr($presence, "@", true),
                    "secondsUp" => $created === "" ? null : max(0, time() - (int) $created),
                ];
            }
        } elseif ($resource === "devices") {
            $own = $this->isPlainUser($session);
            $rows = $this->db->fetchAll(
                "SELECT id, device_type, extension, device_name, device_version, version, enabled, enabled2, update_login
                   FROM q_devices WHERE domain_uuid = CAST(:domain AS uuid)" . ($own ? " AND user_uuid = CAST(:user AS uuid)" : "") . " ORDER BY extension, id",
                $assoc,
                $own ? ["domain" => $domain, "user" => (string) $session["user_uuid"]] : ["domain" => $domain]
            );
            $types = ["1" => "android", "2" => "ios", "3" => "web"];
            foreach ($rows as $row) {
                $content[] = [
                    "id" => (int) $row["id"],
                    "type" => $types[(string) $row["device_type"]] ?? "other",
                    "extension" => (string) $row["extension"],
                    "name" => (string) $row["device_name"],
                    "platform" => (string) $row["device_version"],
                    "appVersion" => (string) $row["version"],
                    "receivesCalls" => (int) $row["enabled"] === 1,
                    "lastLogin" => (string) $row["update_login"],
                ];
            }
        } elseif ($resource === "trunks") {
            $rows = $this->db->fetchAll(
                "SELECT gateway_uuid::text AS uuid, gateway, username, auth_username, proxy, register, register_transport, codec_prefs, channels, expire_seconds, retry_seconds, description, profile, enabled, custom_user, custom_display, custom_match
                   FROM v_gateways WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY gateway",
                $assoc,
                ["domain" => $domain]
            );
            $live = (string) $this->redis->get($session["subdomain"] . "-gateways");
            $up = $live === "" ? [] : explode(" ", trim($live));
            foreach ($rows as $row) {
                $uuid = (string) $row["uuid"];
                $proxy = (string) $row["proxy"];
                $colon = strrpos($proxy, ":");
                $host = $colon === false ? $proxy : substr($proxy, 0, $colon);
                $port = $colon === false ? "" : substr($proxy, $colon + 1);
                $state = "unknown";
                $status = json_decode((string) $this->redis->get("gatewayStatus-" . $uuid), true);
                if (is_array($status) && isset($status["state"])) {
                    $state = (string) $status["state"];
                }
                $sms = false;
                foreach (["twilioconfig:sms:config:", "telnyx:sms:config:"] as $prefix) {
                    $config = json_decode((string) $this->redis->get($prefix . $uuid . ":" . $session["subdomain"]), true);
                    if (is_array($config) && (string) ($config["accessToken"] ?? "") !== "") {
                        $sms = true;
                    }
                }
                $content[] = [
                    "uuid" => $uuid,
                    "name" => (string) $row["gateway"],
                    "host" => $host,
                    "port" => $port,
                    "transport" => strtolower((string) ($row["register_transport"] ?: "udp")),
                    "auth" => trim((string) $row["register"]) === "false" ? "ip" : "register",
                    "username" => (string) $row["username"],
                    "authUsername" => (string) $row["auth_username"],
                    "outboundCallerId" => (string) $row["description"],
                    "codecs" => (string) $row["codec_prefs"],
                    "maxCalls" => (string) $row["channels"],
                    "expireSeconds" => (string) $row["expire_seconds"],
                    "retrySeconds" => (string) $row["retry_seconds"],
                    "profile" => (string) $row["profile"],
                    "fromUser" => (string) $row["custom_user"],
                    "fromDisplay" => (string) $row["custom_display"],
                    "didMatch" => (string) $row["custom_match"],
                    "enabled" => (string) $row["enabled"] === "true",
                    "online" => in_array($uuid, $up, true),
                    "state" => $state,
                    "smsConfigured" => $sms,
                ];
            }
        } elseif ($resource === "queue") {
            $entity = (string) $id;
            if (!preg_match('/^[0-9]{2,10}$/', $entity)) {
                $this->response->setStatusCode(400, "Bad Request");
                $this->response->setContent(json_encode(["result" => "error", "message" => "Give the queue number."]));
                return $this->response;
            }
            $queue = $this->db->fetchOne(
                "SELECT queue_name, queue_extension, queue_strategy, queue_greeting, queue_moh_sound, queue_messsage_on_hold, queue_messsage_on_hold2, queue_messsage_on_hold3, queue_messsage_interval, queue_announce_position, queue_time_base_score_sec, queue_timeout_action, queue_max_wait_time, queue_description, queue_tier_rules_apply, queue_max_callers, queue_auto_answer
                   FROM v_call_center_queues WHERE domain_uuid = CAST(:domain AS uuid) AND queue_extension = :entity LIMIT 1",
                $assoc,
                ["domain" => $domain, "entity" => $entity]
            );
            if (!$queue) {
                $this->response->setStatusCode(404, "Not Found");
                $this->response->setContent(json_encode(["result" => "error", "message" => "No queue with that number."]));
                return $this->response;
            }
            $script = $this->db->fetchOne(
                "SELECT content FROM q_scripts WHERE domain_uuid = CAST(:domain AS uuid) AND extension = :entity LIMIT 1",
                $assoc,
                ["domain" => $domain, "entity" => $entity]
            );
            $notify = $this->db->fetchOne(
                "SELECT queue_sla_notify, queue_callback_success, queue_callback_fail, queue_call_lost FROM q_queue_notifications WHERE domain_uuid = CAST(:domain AS uuid) AND queue_extension = :entity LIMIT 1",
                $assoc,
                ["domain" => $domain, "entity" => $entity]
            );
            $audio = function ($value) {
                $value = (string) $value;
                $prefix = "/var/www/ringq/public/audio/";
                return strpos($value, $prefix) === 0 ? substr($value, strlen($prefix)) : ($value === "local_stream://default" ? "" : $value);
            };
            $notes = [];
            $timeout = (string) $queue["queue_timeout_action"];
            $queueType = "";
            $timeoutAction = "";
            if (preg_match('/^transfer:(\*99)?([0-9]+) XML /', $timeout, $m)) {
                $queueType = $m[1] === "" ? "1" : "2";
                $timeoutAction = $m[2];
            } elseif (strpos($timeout, "hangup") === 0) {
                $queueType = "3";
                $timeoutAction = "Hangup";
            } elseif ($timeout !== "") {
                $notes[] = "The timeout action is not one the web app can express, so an edit would clear it.";
            }
            $desc = explode("-", (string) $queue["queue_description"]);
            $part = function ($i) use ($desc) {
                return isset($desc[$i]) && ctype_digit((string) $desc[$i]) ? (string) $desc[$i] : "0";
            };
            $key = $entity . "@" . $session["subdomain"];
            $chat = function ($suffix) use ($key) {
                $list = (array) $this->redis->lrange($key . "-" . $suffix, 0, -1);
                return implode(",", array_reverse(array_map("strval", $list)));
            };
            $mode = (string) $this->redis->get($key . "-click2talk-mode");
            $content = [
                "extension" => $entity,
                "name" => (string) $queue["queue_name"],
                "editable" => $notes === [],
                "notes" => $notes,
                "edit" => [
                    "queue_extension" => $entity,
                    "queue_name" => (string) $queue["queue_name"],
                    "queue_strategy" => (string) $queue["queue_strategy"],
                    "queue_type" => $queueType,
                    "queue_timeout_action" => $timeoutAction,
                    "queue_max_wait_time" => (string) (int) $queue["queue_max_wait_time"],
                    "agent_wrap_up_time" => $part(0),
                    "queue_sla" => $part(1),
                    "agent_call_timeout" => $part(2),
                    "queue_wrapup" => $part(3),
                    "queue_show_contact" => $part(4),
                    "queue_show_scripts" => $part(5),
                    "queue_skill" => (string) $queue["queue_tier_rules_apply"] === "true" ? "1" : "0",
                    "queue_greeting" => $audio($queue["queue_greeting"]),
                    "queue_moh_sound" => $audio($queue["queue_moh_sound"]),
                    "queue_messsage_on_hold" => $audio($queue["queue_messsage_on_hold"]),
                    "queue_messsage_on_hold2" => $audio($queue["queue_messsage_on_hold2"]),
                    "queue_messsage_on_hold3" => $audio($queue["queue_messsage_on_hold3"]),
                    "queue_messsage_interval" => $queue["queue_messsage_interval"] === null ? "" : (string) (int) $queue["queue_messsage_interval"],
                    "queue_announce_position" => (string) (int) $queue["queue_announce_position"],
                    "queue_time_base_score_sec" => (string) (int) $queue["queue_time_base_score_sec"],
                    "queue_max_callers" => (string) (int) $queue["queue_max_callers"],
                    "queue_auto_answer" => (string) (int) $queue["queue_auto_answer"] === "1" ? "1" : "0",
                    "queue_callback" => $this->redis->exists($key . "-callBack") ? "2" : "1",
                    "queue_callback_custom" => $this->redis->exists($key . "-callBackCustom") ? "2" : "1",
                    "queue_call_landing" => (string) $this->redis->get($key . "-queue_call_landing"),
                    "queue_call_landing2" => (string) $this->redis->get($key . "-queue_call_landing2"),
                    "queue_call_landing_url" => (string) $this->redis->get($key . "-queue_call_landing_url"),
                    "queue_record" => (string) ($this->redis->get($key . "-queueRecord") ?: "0"),
                    "click2talk_mode" => ctype_digit($mode) ? $mode : "1",
                    "content" => $script ? (string) $script["content"] : "",
                    "queue_sla_notify" => $notify && (int) $notify["queue_sla_notify"] === 1 ? "1" : "0",
                    "queue_callback_success" => $notify && (int) $notify["queue_callback_success"] === 1 ? "1" : "0",
                    "queue_callback_fail" => $notify && (int) $notify["queue_callback_fail"] === 1 ? "1" : "0",
                    "queue_call_lost" => $notify && (int) $notify["queue_call_lost"] === 1 ? "1" : "0",
                    "facebook_chat" => $chat("facebook-chat"),
                    "whatsapp_chat" => $chat("whatsapp-chat"),
                    "webchat_chat" => $chat("webchat-chat"),
                    "line_chat" => $chat("line-chat"),
                    "telegram_chat" => $chat("telgram-chat"),
                    "telnyx_chat" => $chat("telnyx-chat"),
                    "twilio_chat" => $chat("twilio-chat"),
                ],
            ];
        } elseif ($resource === "ivr") {
            $entity = (string) $id;
            if (!preg_match('/^[0-9]{2,10}$/', $entity)) {
                $this->response->setStatusCode(400, "Bad Request");
                $this->response->setContent(json_encode(["result" => "error", "message" => "Give the IVR number."]));
                return $this->response;
            }
            $menu = $this->db->fetchOne(
                "SELECT ivr_menu_uuid::text AS uuid, ivr_menu_name, ivr_menu_extension, ivr_menu_greet_long, ivr_menu_timeout, ivr_menu_exit_app, ivr_menu_exit_data, ivr_menu_direct_dial
                   FROM v_ivr_menus WHERE domain_uuid = CAST(:domain AS uuid) AND ivr_menu_extension = :entity AND ivr_menu_extension > '5000' LIMIT 1",
                $assoc,
                ["domain" => $domain, "entity" => $entity]
            );
            if (!$menu) {
                $this->response->setStatusCode(404, "Not Found");
                $this->response->setContent(json_encode(["result" => "error", "message" => "No IVR with that number."]));
                return $this->response;
            }
            $rows = $this->db->fetchAll(
                "SELECT ivr_menu_option_digits, ivr_menu_option_action, ivr_menu_option_param
                   FROM v_ivr_menu_options WHERE domain_uuid = CAST(:domain AS uuid) AND ivr_menu_uuid = CAST(:menu AS uuid) ORDER BY ivr_menu_option_digits",
                $assoc,
                ["domain" => $domain, "menu" => (string) $menu["uuid"]]
            );
            $notes = [];
            $dest = function ($value) {
                $value = trim((string) $value);
                if (preg_match('/^(transfer )?(\*99)?([0-9]+) XML /', $value . " ", $m)) {
                    return ($m[2] === "" ? "" : "vm:") . $m[3];
                }
                return null;
            };
            $options = [];
            foreach ($rows as $row) {
                $digit = (string) $row["ivr_menu_option_digits"];
                $value = (string) $row["ivr_menu_option_action"] === "menu-exec-app" ? $dest($row["ivr_menu_option_param"]) : null;
                if ($value === null) {
                    $notes[] = "Key " . $digit . " does something the web app cannot express, so an edit would remove it.";
                    continue;
                }
                $options[$digit] = $value;
            }
            $exitApp = (string) $menu["ivr_menu_exit_app"];
            $timeoutAction = "hangup";
            if ($exitApp === "transfer") {
                $parsed = $dest($menu["ivr_menu_exit_data"]);
                if ($parsed === null) {
                    $notes[] = "The timeout action is not one the web app can express, so an edit would clear it.";
                } else {
                    $timeoutAction = $parsed;
                }
            } elseif ($exitApp !== "hangup" && $exitApp !== "") {
                $notes[] = "The timeout action is not one the web app can express, so an edit would clear it.";
            }
            $greeting = (string) $menu["ivr_menu_greet_long"];
            $prefix = "/var/www/ringq/public/audio/";
            $content = [
                "extension" => $entity,
                "name" => (string) $menu["ivr_menu_name"],
                "editable" => $notes === [],
                "notes" => $notes,
                "edit" => [
                    "extension" => $entity,
                    "name" => (string) $menu["ivr_menu_name"],
                    "greeting" => strpos($greeting, $prefix) === 0 ? substr($greeting, strlen($prefix)) : $greeting,
                    "timeoutSeconds" => (int) round(((int) $menu["ivr_menu_timeout"]) / 1000),
                    "timeoutAction" => $timeoutAction,
                    "directDial" => (string) $menu["ivr_menu_direct_dial"] === "true" ? "yes" : "no",
                    "options" => (object) $options,
                ],
            ];
        } elseif ($resource === "extension") {
            $entity = (string) $id;
            if (!preg_match('/^[0-9]{2,10}$/', $entity)) {
                $this->response->setStatusCode(400, "Bad Request");
                $this->response->setContent(json_encode(["result" => "error", "message" => "Give the extension number."]));
                return $this->response;
            }
            if ($this->isPlainUser($session) && $entity !== (string) $session["extension"]) {
                $this->response->setStatusCode(403, "Forbidden");
                $this->response->setContent(json_encode(["result" => "error", "message" => "Sorry, you can only access your own records. (Code AC4031)"]));
                return $this->response;
            }
            $row = $this->db->fetchOne(
                "SELECT e.extension, e.accountcode, e.outbound_caller_id_name, e.outbound_caller_id_number, u.first_name, u.last_name, vu.username, vu.user_email
                   FROM v_extensions e
                   LEFT JOIN v_extension_users eu ON eu.extension_uuid = e.extension_uuid
                   LEFT JOIN q_users u ON u.user_uuid = eu.user_uuid
                   LEFT JOIN v_users vu ON vu.user_uuid = eu.user_uuid
                  WHERE e.domain_uuid = CAST(:domain AS uuid) AND e.extension = :entity
                  LIMIT 1",
                $assoc,
                ["domain" => $domain, "entity" => $entity]
            );
            if (!$row) {
                $this->response->setStatusCode(404, "Not Found");
                $this->response->setContent(json_encode(["result" => "error", "message" => "No extension with that number."]));
                return $this->response;
            }
            $behavior = $this->db->fetchOne(
                "SELECT mobile_number, sso_qr, sso_number, call_profiles, forward_all_enabled, forward_all_enabled2, forward_all_destination, forward_all_destination2, forward_busy_enabled, forward_busy_enabled2, forward_busy_destination, forward_busy_destination2, forward_no_answer_enabled, forward_no_answer_enabled2, forward_no_answer_destination, forward_no_answer_destination2, forward_no_answer_timeout, forward_no_answer_timeout2, call_screening, call_screening2, simultaneous_destination_enabled, simultaneous_destination_enabled2 FROM q_call_behaviors WHERE domain_uuid = CAST(:domain AS uuid) AND extension = :entity LIMIT 1",
                $assoc,
                ["domain" => $domain, "entity" => $entity]
            );
            $voicemail = $this->db->fetchOne(
                "SELECT voicemail_enabled, voicemail_recording_instructions, voicemail_description FROM v_voicemails WHERE domain_uuid = CAST(:domain AS uuid) AND voicemail_id = :entity LIMIT 1",
                $assoc,
                ["domain" => $domain, "entity" => $entity]
            );
            $notify = is_array($voicemail) ? (int) ($voicemail["voicemail_description"] ?? 0) : 0;
            $card = $entity . "@" . (string) $row["accountcode"];
            $text = function ($key) {
                $value = $this->redis->get($key);
                return $value === null || $value === false ? "" : (string) $value;
            };
            $dids = array_map("strval", (array) $this->redis->lrange("dids-" . $entity . "@" . $session["subdomain"], 0, -1));
            $hasEmail = trim((string) ($row["user_email"] ?? "")) !== "";
            $content = [
                "extension" => $entity,
                "editable" => is_array($behavior) && $hasEmail,
                "notes" => !$hasEmail
                    ? ["This extension's user has no email address, which the RingQ app needs to save a profile. Add one in the RingQ app first."]
                    : (is_array($behavior)
                    ? ["Profile and voicemail on/off only (voicemail fields are empty when the extension has no voicemail box). Call forwarding is in forwarding and is changed with extensions.update_forwarding. Desk phones are read with desk_phones.list and changed with desk_phones.add, desk_phones.update, desk_phones.remove. Sign-in credentials, voicemail PIN and follow-me are changed in the RingQ app."]
                    : ["This extension has no call settings record yet, so its profile cannot be saved here. Open and save it once in the RingQ app first."]),
                "edit" => [
                    "extension" => $entity,
                    "username" => (string) ($row["username"] ?? ""),
                    "email" => (string) ($row["user_email"] ?? ""),
                    "firstname" => (string) ($row["first_name"] ?? ""),
                    "lastname" => (string) ($row["last_name"] ?? ""),
                    "outbound_caller_id_name" => (string) ($row["outbound_caller_id_name"] ?? ""),
                    "outbound_caller_id_number" => (string) ($row["outbound_caller_id_number"] ?? ""),
                    "outbound_dids" => implode(",", array_reverse($dids)),
                    "mobile_number" => (string) ($behavior["mobile_number"] ?? ""),
                    "sso_qr" => (string) (int) ($behavior["sso_qr"] ?? 0),
                    "sso_number" => (string) (int) ($behavior["sso_number"] ?? 0),
                    "website" => $text($card . "-website"),
                    "job_title" => $text($card . "-jobTitle"),
                    "company" => $text($card . "-company"),
                    "linkedin_profile_url" => $text($card . "-linkedInProfileURL"),
                    "voicemail_enabled" => is_array($voicemail) ? ((string) $voicemail["voicemail_enabled"] === "true" ? "2" : "1") : "",
                    "voicemail_recording_instructions" => is_array($voicemail) ? ((string) $voicemail["voicemail_recording_instructions"] === "true" ? "2" : "1") : "",
                    "voicemail_description" => is_array($voicemail) ? (string) ($notify >= 1 && $notify <= 3 ? $notify : 1) : "",
                ],
            ];
            require_once __DIR__ . "/../library/McpCatalog.php";
            $profileNames = explode(",", (string) ($behavior["call_profiles"] ?? ""));
            $statusNames = [];
            foreach (McpCatalog::FORWARDING_STATUSES as $i => $status) {
                $statusNames[$status] = trim((string) ($profileNames[$i] ?? "")) !== "" ? trim((string) $profileNames[$i]) : ["Available", "Away", "Busy", "Custom 1", "Custom 2"][$i];
            }
            $content["forwarding"] = [
                "extension" => $entity,
                "editable" => is_array($behavior),
                "mobileNumber" => (string) ($behavior["mobile_number"] ?? ""),
                "statusNames" => $statusNames,
            ] + McpCatalog::forwardingEdit(is_array($behavior) ? $behavior : [], $entity);
        } elseif ($resource === "deskphones") {
            $entity = (string) $id;
            if (!preg_match('/^[0-9]{2,10}$/D', $entity)) {
                $this->response->setStatusCode(400, "Bad Request");
                $this->response->setContent(json_encode(["result" => "error", "message" => "Give the extension number."]));
                return $this->response;
            }
            $row = $this->db->fetchOne(
                "SELECT e.extension, eu.user_uuid::text AS user_uuid FROM v_extensions e LEFT JOIN v_extension_users eu ON eu.extension_uuid = e.extension_uuid WHERE e.domain_uuid = CAST(:domain AS uuid) AND e.extension = :entity LIMIT 1",
                $assoc,
                ["domain" => $domain, "entity" => $entity]
            );
            if (!$row) {
                $this->response->setStatusCode(404, "Not Found");
                $this->response->setContent(json_encode(["result" => "error", "message" => "No extension with that number."]));
                return $this->response;
            }
            require_once __DIR__ . "/../library/McpCatalog.php";
            $hostUrls = [["value" => "", "label" => (string) $session["subdomain"] . " (default)"]];
            $brands = McpCatalog::deskPhoneChoices((string) $this->redis->get("api_cache:licensecheckuser:" . $domain));
            $content = [
                "extension" => $entity,
                "editable" => trim((string) ($row["user_uuid"] ?? "")) !== "" && $brands !== [],
                "notes" => $brands === []
                    ? ["The phone models are not loaded on this server yet. Open RingQ in the browser once, then read this again."]
                    : ["brand, model and timezone must come from brands. hostUrl empty means the server address; the LAN IP of this server or of one of the account's tunnels (Tunnels page) is also accepted. Phones with brand custom use a custom template and can only be changed in the RingQ app."],
                "phones" => McpCatalog::deskPhoneEntries((array) $this->redis->lrange($entity . "@" . $session["subdomain"] . "-macAddresses", 0, -1)),
                "brands" => $brands,
                "stunServers" => McpCatalog::DESK_PHONE_STUNS,
                "hostUrls" => $hostUrls,
            ];
        } elseif ($resource === "roles") {
            $names = ["7" => "owner", "8" => "manager", "9" => "custom", "10" => "user"];
            foreach ($this->db->fetchAll(
                "SELECT e.extension, coalesce(u.first_name, '') AS first_name, coalesce(u.last_name, '') AS last_name
                   FROM v_extensions e
                   LEFT JOIN v_extension_users eu ON eu.extension_uuid = e.extension_uuid
                   LEFT JOIN q_users u ON u.user_uuid = eu.user_uuid
                  WHERE e.domain_uuid = CAST(:domain AS uuid) AND e.extension ~ '^[0-9]+$'
                  ORDER BY length(e.extension), e.extension",
                $assoc,
                ["domain" => $domain]
            ) as $row) {
                $mode = (string) $this->permissionModeOf(["extension" => (string) $row["extension"], "subdomain" => (string) $session["subdomain"], "domain_uuid" => $domain]);
                $content[] = [
                    "extension" => (string) $row["extension"],
                    "name" => trim((string) $row["first_name"] . " " . (string) $row["last_name"]),
                    "role" => $names[$mode] ?? "other",
                    "mode" => $mode,
                ];
            }
        } elseif ($resource === "chats" || $resource === "chat") {
            $subdomain = (string) $session["subdomain"];
            $parse = function (string $member) use ($subdomain): ?array {
                return $this->chatConversation($subdomain, $member);
            };
            if ($resource === "chats") {
                $states = ["all" => "", "new" => "-new", "active" => "-active", "closed" => "-close"];
                $state = strtolower((string) $this->request->getQuery("state", null, "all"));
                if (!isset($states[$state])) {
                    $this->response->setStatusCode(400, "Bad Request");
                    $this->response->setContent(json_encode(["result" => "error", "message" => "state must be all, new, active or closed."]));
                    return $this->response;
                }
                $page = max(1, (int) $this->request->getQuery("page", "int", 1));
                $key = $subdomain . "-conversation" . $states[$state];
                $total = (int) $this->redis->zcard($key);
                $members = (array) $this->redis->zrevrange($key, ($page - 1) * 25, $page * 25 - 1, ["withscores" => true]);
                $conversations = [];
                foreach ($members as $member => $score) {
                    $info = $parse((string) $member);
                    if ($info === null) {
                        continue;
                    }
                    $row = (array) $this->redis->hmget($info["userKey"], ["allocated_room", "Dept", "extAgentName", "extAgentExtension", "agent_unread", "lastSeen", "firstChatTimestamp", "last_message", "locationCountry", "ratings", "status"]);
                    $conversations[] = [
                        "conversation" => (string) $member,
                        "channel" => $info["channel"],
                        "customer" => $info["name"],
                        "contact" => $info["address"],
                        "state" => (string) ($row[0] ?? ""),
                        "department" => (string) ($row[1] ?? ""),
                        "agentName" => (string) ($row[2] ?? ""),
                        "agentExtension" => (string) ($row[3] ?? ""),
                        "unread" => (int) ($row[4] ?? 0),
                        "lastSeen" => (string) ($row[5] ?? ""),
                        "startedAt" => (string) ($row[6] ?? ""),
                        "lastMessage" => mb_substr((string) ($row[7] ?? ""), 0, 200),
                        "country" => (string) ($row[8] ?? ""),
                        "rating" => (string) ($row[9] ?? ""),
                        "customerOnline" => (string) ($row[10] ?? "") === "online",
                        "updatedAt" => (string) $score,
                    ];
                }
                $content = ["state" => $state, "page" => $page, "total" => $total, "hasMore" => $page * 25 < $total, "conversations" => $conversations];
            } else {
                $member = (string) $this->request->getQuery("conversation", null, "");
                $info = $member !== "" && strlen($member) <= 300 ? $parse($member) : null;
                if ($info === null || $this->redis->zscore($subdomain . "-conversation", $member) === null) {
                    $this->response->setStatusCode(404, "Not Found");
                    $this->response->setContent(json_encode(["result" => "error", "message" => "No conversation with that id on this account (see chat.conversations)."]));
                    return $this->response;
                }
                $messages = [];
                if ($info["inbox"] !== "") {
                    $raw = array_values((array) $this->redis->lrange($info["inbox"], 0, 249));
                    for ($i = 0; $i + 4 < count($raw); $i += 5) {
                        $profile = (string) $raw[$i + 1];
                        $slash = strrpos($profile, "\\");
                        $messages[] = [
                            "from" => (string) $raw[$i + 2],
                            "name" => $slash === false ? $profile : substr($profile, $slash + 1),
                            "at" => (string) $raw[$i + 3],
                            "text" => (string) $raw[$i + 4],
                        ];
                    }
                }
                $content = [
                    "conversation" => $member,
                    "channel" => $info["channel"],
                    "customer" => $info["name"],
                    "contact" => $info["address"],
                    "order" => "newest first, up to 50 messages",
                    "notes" => $info["inbox"] === "" ? ["Messages of " . $info["channel"] . " conversations are read in the RingQ app."] : [],
                    "messages" => $messages,
                ];
            }
        } elseif ($resource === "outboundrule") {
            $routes = ["BLOCK"];
            $gatewayRows = $this->db->fetchAll(
                "SELECT gateway, gateway_uuid::text AS gateway_uuid, enabled::text AS enabled FROM v_gateways WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY gateway",
                $assoc,
                ["domain" => $domain]
            );
            foreach ($gatewayRows as $row) {
                $gateway = (string) $row["gateway"];
                if ($gateway !== "" && $gateway === strtolower($gateway) && $gateway !== "block" && !in_array($gateway, $routes, true)) {
                    $routes[] = $gateway;
                }
            }
            $routeProblem = function (array $row) use ($routes, $gatewayRows): ?string {
                $action = trim((string) $row["action"]);
                if ($action === "") {
                    return "has no trunk, so the calls it matches connect and then drop (\"sorry your call…\"). Choose a trunk or BLOCK and save it again.";
                }
                if ($action === "BLOCK" || in_array($action, $routes, true)) {
                    return null;
                }
                foreach ($gatewayRows as $gateway) {
                    if (strtolower((string) $gateway["gateway"]) === strtolower($action)) {
                        return "uses trunk " . $action . ", but the app looks trunks up by a lower-case name, so the saved route has no trunk and calls connect and then drop. Rename the trunk to lower case and save the rule again.";
                    }
                }
                return "uses trunk " . $action . ", which does not exist on this account, so the calls it matches connect and then drop. Choose one of the trunks in routes and save it again.";
            };
            $liveRouteProblems = function () use ($gatewayRows, $domain, $assoc): array {
                $byUuid = [];
                foreach ($gatewayRows as $gateway) {
                    $byUuid[strtolower((string) $gateway["gateway_uuid"])] = $gateway;
                }
                $problems = [];
                foreach ($this->db->fetchAll(
                    "SELECT dialplan_xml FROM v_dialplans WHERE domain_uuid = CAST(:domain AS uuid) AND dialplan_enabled::text = 'true' AND dialplan_xml LIKE '%sofia/gateway/%'",
                    $assoc,
                    ["domain" => $domain]
                ) as $plan) {
                    preg_match_all('/<extension\s+name="([^"]*)"[^>]*>(.*?)<\/extension>/s', (string) $plan["dialplan_xml"], $extensions, PREG_SET_ORDER);
                    foreach ($extensions as $extension) {
                        $name = html_entity_decode($extension[1], ENT_QUOTES);
                        preg_match_all('#sofia/gateway/([^/"\s]*)/#', $extension[2], $bridges);
                        foreach (array_unique($bridges[1]) as $uuid) {
                            $uuid = strtolower($uuid);
                            if ($uuid === "") {
                                $problems[] = "The live outbound route \"" . $name . "\" sends calls to an empty trunk (sofia/gateway//), so they connect and then drop. Save that rule again with a trunk.";
                            } elseif (!isset($byUuid[$uuid])) {
                                $problems[] = "The live outbound route \"" . $name . "\" sends calls to a trunk that no longer exists (gateway " . $uuid . "), so they fail. Save that rule again with an existing trunk.";
                            } elseif (!in_array(strtolower((string) $byUuid[$uuid]["enabled"]), ["true", "t", "1"], true)) {
                                $problems[] = "The live outbound route \"" . $name . "\" sends calls to trunk " . (string) $byUuid[$uuid]["gateway"] . ", which is disabled, so they fail. Enable the trunk or choose another one.";
                            }
                        }
                    }
                }
                return array_values(array_unique($problems));
            };
            $callerIds = [];
            foreach ($this->db->fetchAll(
                "SELECT did_number FROM q_dids WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY did_number",
                $assoc,
                ["domain" => $domain]
            ) as $row) {
                $number = trim((string) $row["did_number"]);
                if ($number !== "" && !in_array($number, $callerIds, true)) {
                    $callerIds[] = $number;
                }
            }
            $edit = function (array $row): array {
                return [
                    "outbound_uuid" => (string) $row["outbound_uuid"],
                    "outbound_name" => (string) $row["outbound_name"],
                    "prefix_pattern" => (string) $row["prefix_pattern"],
                    "calls_extensions" => (string) $row["calls_extensions"],
                    "team_extensions" => (string) $row["team_extensions"],
                    "extension_range" => (string) $row["extension_range"],
                    "calls_number_length" => (string) $row["calls_number_length"],
                    "action" => (string) $row["action"] === "" ? "BLOCK" : (string) $row["action"],
                    "strip" => (string) $row["strip"],
                    "prepend" => (string) $row["prepend"],
                    "outbound_caller_id" => (string) $row["outbound_caller_id"],
                    "sip_from_user" => (string) $row["custom_user"],
                    "sip_from_display_name" => (string) $row["custom_display"],
                    "sip_from_host" => (string) $row["custom_host"],
                    "cid_type" => (string) $row["custom_cid"],
                ];
            };
            $columns = "outbound_uuid::text AS outbound_uuid, outbound_name, priority, prefix_pattern, calls_extensions, team_extensions, extension_range, calls_number_length, action, strip, prepend, outbound_caller_id, custom_user, custom_display, custom_host, custom_cid";
            $entity = (string) $id;
            if ($entity === "") {
                $rules = [];
                foreach ($this->db->fetchAll(
                    "SELECT $columns FROM q_outbound_rules WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY priority, dial_plan_order",
                    $assoc,
                    ["domain" => $domain]
                ) as $row) {
                    $rule = $edit($row);
                    $rule["emergency"] = (int) $row["priority"] < 0;
                    $rule["routeProblem"] = $routeProblem($row);
                    $rules[] = $rule;
                }
                $problems = [];
                foreach ($rules as $rule) {
                    if ($rule["routeProblem"] !== null) {
                        $problems[] = ($rule["emergency"] ? "Emergency rule \"" : "Outbound rule \"") . $rule["outbound_name"] . "\" " . $rule["routeProblem"];
                    }
                }
                foreach ($liveRouteProblems() as $problem) {
                    $problems[] = $problem;
                }
                $content = [
                    "problems" => $problems,
                    "rules" => $rules,
                    "routeOptions" => array_map(function ($name) {
                        return ["name" => $name];
                    }, $routes),
                    "callerIdOptions" => array_map(function ($number) {
                        return ["number" => $number];
                    }, $callerIds),
                ];
            } else {
                if (!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/D', $entity)) {
                    $this->response->setStatusCode(400, "Bad Request");
                    $this->response->setContent(json_encode(["result" => "error", "message" => "Give the rule's outbound_uuid."]));
                    return $this->response;
                }
                $row = $this->db->fetchOne(
                    "SELECT $columns FROM q_outbound_rules WHERE domain_uuid = CAST(:domain AS uuid) AND outbound_uuid::text = :entity LIMIT 1",
                    $assoc,
                    ["domain" => $domain, "entity" => $entity]
                );
                if (!$row) {
                    $this->response->setStatusCode(404, "Not Found");
                    $this->response->setContent(json_encode(["result" => "error", "message" => "No outbound or emergency rule with that id."]));
                    return $this->response;
                }
                $content = [
                    "outbound_uuid" => (string) $row["outbound_uuid"],
                    "emergency" => (int) $row["priority"] < 0,
                    "routeProblem" => $routeProblem($row),
                    "edit" => $edit($row),
                    "routes" => $routes,
                    "callerIds" => $callerIds,
                ];
            }
        } elseif ($resource === "sipprofiles") {
            $content = $this->sipProfileHealth();
            unset($content["enabled"]);
        } elseif ($resource === "dbowners") {
            $content = $this->databaseOwnership();
        } elseif ($resource === "permissions") {
            if (ControllerBase::isSharedServer((string) $session["subdomain"]) && empty($session["mcp_staff"])) {
                $this->response->setStatusCode(403, "Forbidden");
                $this->response->setContent(json_encode(["result" => "error", "message" => "This server is shared by several accounts, so its permissions are checked by RingQ support. (Code AC4034)"]));
                return $this->response;
            }
            $area = strtolower(trim((string) $this->request->getQuery("area", null, "all")));
            $areas = ["files", "database", "services", "sockets", "cron", "security", "logs"];
            if ($area !== "all" && !in_array($area, $areas, true)) {
                $this->response->setStatusCode(400, "Bad Request");
                $this->response->setContent(json_encode(["result" => "error", "message" => "area must be all, " . implode(", ", $areas) . "."]));
                return $this->response;
            }
            $content = $this->permissionsReport($area === "all" ? $areas : [$area]);
        } elseif ($resource === "queueagents") {
            $content = $this->callCenterTierHealth($domain);
        } elseif ($resource === "cdrpipeline") {
            $content = $this->cdrPipelineHealth((string) $session["subdomain"], (string) $domain);
        } elseif ($resource === "mail") {
            $content = $this->mailHealth((string) $session["subdomain"], (string) $domain);
        } elseif ($resource === "updatehealth") {
            $content = $this->updateHealth((string) $session["subdomain"]);
        } elseif ($resource === "push") {
            $only = trim((string) $this->request->getQuery("extension"));
            if ($only !== "" && !preg_match('/^[0-9]{2,10}$/D', $only)) {
                $this->response->setStatusCode(400, "Bad Request");
                $this->response->setContent(json_encode(["result" => "error", "message" => "Give an extension number."]));
                return $this->response;
            }
            $content = $this->pushHealth((string) $session["subdomain"], (string) $domain, $only === "" ? null : $only);
        } elseif ($resource === "aiagent") {
            // The AI agent (Global Settings > AI agent, extension 5555) and why it might not
            // answer. Never returns an API key: health says whether one is saved.
            $sub = (string) $session["subdomain"];
            $get = function (string $key) use ($sub): string {
                $value = $this->redis->get("ai:" . $sub . "-" . $key);
                return ($value === null || $value === false || $value === "null") ? "" : (string) $value;
            };
            $split = function (string $csv): array {
                return $csv === "" ? [] : array_map("trim", explode(",", $csv));
            };
            $keywords = $split($get("keywords"));
            $messages = $split($get("keywordMessages"));
            $destinations = $split($get("keywordExtensions"));
            $rows = [];
            foreach ($keywords as $i => $keyword) {
                if ($keyword !== "") {
                    $rows[] = ["keyword" => $keyword, "message" => $messages[$i] ?? "", "destination" => $destinations[$i] ?? ""];
                }
            }
            $edit = [];
            foreach (["defaultLanguage", "keywords", "keywordMessages", "keywordExtensions", "greetings", "voice", "noiseField", "prompt", "context"] as $field) {
                $edit[$field] = $get($field);
            }
            $tokenSet = $get("token") !== "" || $get("aiAgentChatgptToken") !== "";
            $dialplan = $this->db->fetchOne(
                "SELECT dialplan_enabled::text AS enabled, dialplan_xml FROM v_dialplans WHERE domain_uuid = CAST(:domain AS uuid) AND dialplan_number = '5555' LIMIT 1",
                $assoc,
                ["domain" => $domain]
            );
            $dialplanXml = is_array($dialplan) ? (string) $dialplan["dialplan_xml"] : "";
            $dialplanKey = $dialplanXml !== "" && strpos($dialplanXml, 'STREAM_OPENAI_API_KEY=""') === false
                && strpos($dialplanXml, 'STREAM_OPENAI_API_KEY="/') === false;
            $script = dirname(__DIR__) . "/scripts/fs-custom-modules.sh";
            $modules = is_file($script) ? json_decode((string) @shell_exec("/bin/bash " . escapeshellarg($script) . " status 2>/dev/null"), true) : null;
            $openai = null;
            foreach ((array) ($modules["modules"] ?? []) as $module) {
                if (($module["name"] ?? "") === "mod_openai_audio_stream") {
                    $openai = $module;
                }
            }
            $problems = [];
            if (!$tokenSet) {
                $problems[] = "No OpenAI (ChatGPT) token is saved. Enter it on Global Settings > AI agent > Settings and save.";
            }
            if (!is_array($dialplan)) {
                $problems[] = "The AI agent number 5555 has no dial plan yet. Save the AI agent settings once.";
            } else {
                if (!in_array(strtolower((string) $dialplan["enabled"]), ["true", "t", "1"], true)) {
                    $problems[] = "The AI agent dial plan (5555) is disabled.";
                }
                if ($tokenSet && !$dialplanKey) {
                    $problems[] = "The AI agent dial plan was built without the token. Save the AI agent settings again.";
                }
            }
            if ($openai === null) {
                $problems[] = "Could not check the FreeSWITCH AI module on this server.";
            } elseif (!$openai["file"] && !$openai["build"]) {
                $problems[] = "mod_openai_audio_stream is missing and there is no build to restore it from. RingQ support has to rebuild it.";
            } elseif (!$openai["file"]) {
                $problems[] = "mod_openai_audio_stream was removed from FreeSWITCH. Run ai_agent.repair_module to restore it.";
            } elseif ($openai["loaded"] === "false") {
                $problems[] = "mod_openai_audio_stream is installed but not loaded. Run ai_agent.repair_module to load it.";
            }
            if ($get("defaultLanguage") === "") {
                $problems[] = "No language is selected.";
            }
            $content = [
                "settings" => [
                    "languages" => $split($get("defaultLanguage")),
                    "keywords" => $rows,
                    "voice" => $get("voice"),
                    "noiseField" => $get("noiseField"),
                    "greetings" => array_values(array_filter($split($get("greetings")), "strlen")),
                    "prompt" => $get("prompt"),
                    "context" => $get("context"),
                    "number" => "5555",
                ],
                "edit" => $edit,
                "health" => [
                    "working" => $problems === [],
                    "problems" => $problems,
                    "tokenSaved" => $tokenSet,
                    "dialplan" => ["exists" => is_array($dialplan), "hasToken" => $dialplanKey],
                    "modules" => $modules["modules"] ?? null,
                ],
            ];
        } elseif ($resource === "holidays") {
            $rows = $this->db->fetchAll(
                "SELECT id, holiday_name, day, month, year, day2, month2, year2, time, recurring, holiday_greeting, extensions
                   FROM q_holidays WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY year, month, day, id",
                $assoc,
                ["domain" => $domain]
            );
            $date = function ($y, $m, $d) {
                return sprintf("%04d-%02d-%02d", (int) $y, (int) $m, (int) $d);
            };
            $holidays = [];
            $extensionHolidays = 0;
            foreach ($rows as $row) {
                if ($row["extensions"] !== null && (string) $row["extensions"] !== "") {
                    $extensionHolidays++;
                    continue;
                }
                $from = 0;
                $to = 1440;
                $time = (string) ($row["time"] ?? "");
                if (preg_match('/^(\d+)-(\d+)$/', $time, $m)) {
                    $from = (int) $m[1];
                    $to = (int) $m[2];
                }
                $holidays[] = [
                    "id" => (string) $row["id"],
                    "name" => (string) $row["holiday_name"],
                    "start" => $date($row["year"], $row["month"], $row["day"]),
                    "end" => $date($row["year2"] ?: $row["year"], $row["month2"] ?: $row["month"], $row["day2"] ?: $row["day"]),
                    "from" => sprintf("%02d:%02d", intdiv($from, 60), $from % 60),
                    "to" => sprintf("%02d:%02d", intdiv($to, 60), $to % 60),
                    "recurring" => (int) $row["recurring"] === 1 ? "yes" : "no",
                    "greeting" => (string) $row["holiday_greeting"],
                ];
            }
            $exempt = $this->db->fetchAll(
                "SELECT extension FROM q_holiday_exemptions WHERE domain_uuid = CAST(:domain AS uuid) ORDER BY extension",
                $assoc,
                ["domain" => $domain]
            );
            $content = [
                "holidays" => $holidays,
                "extensionHolidays" => $extensionHolidays,
                "exemptExtensions" => array_map(function ($r) {
                    return ["extension" => (string) $r["extension"]];
                }, $exempt),
            ];
        } else {
            $entity = (string) $id;
            if (!preg_match('/^[0-9]{2,10}$/', $entity)) {
                $this->response->setStatusCode(400, "Bad Request");
                $this->response->setContent(json_encode(["result" => "error", "message" => "Give the queue, IVR or extension number."]));
                return $this->response;
            }
            $kind = "";
            $checks = [
                "queue" => "SELECT 1 FROM v_call_center_queues WHERE domain_uuid = CAST(:domain AS uuid) AND queue_extension = :entity LIMIT 1",
                "ivr" => "SELECT 1 FROM v_ivr_menus WHERE domain_uuid = CAST(:domain AS uuid) AND ivr_menu_extension = :entity LIMIT 1",
                "extension" => "SELECT 1 FROM v_extensions WHERE domain_uuid = CAST(:domain AS uuid) AND extension = :entity LIMIT 1",
            ];
            foreach ($checks as $name => $sql) {
                if ($this->db->fetchOne($sql, $assoc, ["domain" => $domain, "entity" => $entity])) {
                    $kind = $name;
                    break;
                }
            }
            if ($kind === "") {
                $this->response->setStatusCode(404, "Not Found");
                $this->response->setContent(json_encode(["result" => "error", "message" => "No queue, IVR or extension with that number."]));
                return $this->response;
            }
            $rows = $this->db->fetchAll(
                "SELECT dialplan_description FROM v_dialplans
                  WHERE domain_uuid = CAST(:domain AS uuid) AND dialplan_number = :entity
                    AND (dialplan_name LIKE 'nonwork-%' OR dialplan_name LIKE 'break-%')",
                $assoc,
                ["domain" => $domain, "entity" => $entity]
            );
            $office = [];
            $break = [];
            foreach ($rows as $row) {
                $parts = explode("-", (string) $row["dialplan_description"]);
                if (count($parts) < 4 || !ctype_digit($parts[1]) || !ctype_digit($parts[2]) || !ctype_digit($parts[3])) {
                    continue;
                }
                $entry = ["a" => (int) $parts[2], "b" => (int) $parts[3], "dest" => (string) ($parts[4] ?? "")];
                if ($parts[0] === "1") {
                    $office[(int) $parts[1]] = $entry;
                } elseif ($parts[0] === "2") {
                    $break[(int) $parts[1]] = $entry;
                }
            }
            $hhmm = function (int $m) {
                return sprintf("%02d:%02d", intdiv($m, 60), $m % 60);
            };
            $after = function (string $dest) {
                if ($dest === "") {
                    return "hangup";
                }
                if (strpos($dest, "*99") === 0) {
                    return "vm:" . substr($dest, 3);
                }
                return $dest;
            };
            $schedule = $this->db->fetchOne(
                "SELECT work_extensions, break_extensions FROM q_time_schedules WHERE domain_uuid = CAST(:domain AS uuid) LIMIT 1",
                $assoc,
                ["domain" => $domain]
            );
            $member = function ($list) use ($entity) {
                return in_array($entity, array_map("trim", explode(",", (string) $list)), true);
            };
            $days = ["sunday" => 1, "monday" => 2, "tuesday" => 3, "wednesday" => 4, "thursday" => 5, "friday" => 6, "saturday" => 7];
            $officeDays = [];
            $breakDays = [];
            $officeAfter = "hangup";
            $breakAfter = "hangup";
            foreach (["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"] as $name) {
                $code = $days[$name];
                if (isset($office[$code])) {
                    $o = $office[$code];
                    $closed = $o["a"] === 1440 && $o["b"] === 0;
                    $officeDays[] = [
                        "day" => $name,
                        "state" => $closed ? "closed" : "hours",
                        "open" => $closed ? "" : $hhmm($o["b"]),
                        "close" => $closed ? "" : $hhmm(max(0, $o["a"] - 1)),
                        "afterHours" => $after($o["dest"]),
                    ];
                    if ($officeAfter === "hangup" && $o["dest"] !== "") {
                        $officeAfter = $after($o["dest"]);
                    }
                } else {
                    $officeDays[] = ["day" => $name, "state" => "open24", "open" => "00:00", "close" => "23:59", "afterHours" => "hangup"];
                }
                if (isset($break[$code])) {
                    $k = $break[$code];
                    $allDay = $k["a"] === 0 && $k["b"] === 1440;
                    $breakDays[] = [
                        "day" => $name,
                        "state" => $allDay ? "allday" : "hours",
                        "start" => $hhmm($k["a"]),
                        "end" => $hhmm(max(0, $k["b"] - 1)),
                        "afterHours" => $after($k["dest"]),
                    ];
                    if ($breakAfter === "hangup" && $k["dest"] !== "") {
                        $breakAfter = $after($k["dest"]);
                    }
                } else {
                    $breakDays[] = ["day" => $name, "state" => "none", "start" => "", "end" => "", "afterHours" => "hangup"];
                }
            }
            $content = [
                "entity" => $entity,
                "kind" => $kind,
                "office" => [
                    "followsAccount" => $schedule ? $member($schedule["work_extensions"]) : false,
                    "afterHours" => $officeAfter,
                    "days" => $officeDays,
                ],
                "break" => [
                    "followsAccount" => $schedule ? $member($schedule["break_extensions"]) : false,
                    "afterHours" => $breakAfter,
                    "days" => $breakDays,
                ],
            ];
        }
        $this->response->setContent(json_encode(["result" => "success", "content" => $content], JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE));
        return $this->response;
    }

    private function tenantChannels(string $subdomain): array
    {
        require_once __DIR__ . "/../library/ServiceHealth.php";
        $mine = [];
        foreach ((array) (\ServiceHealth::channels()["rows"] ?? []) as $row) {
            if (!is_array($row) || $subdomain === "") {
                continue;
            }
            $context = (string) ($row["context"] ?? "");
            $presence = (string) ($row["presence_id"] ?? "");
            if ($context === $subdomain || ($presence !== "" && substr($presence, -(strlen($subdomain) + 1)) === "@" . $subdomain)) {
                $mine[] = $row;
            }
        }
        return $mine;
    }

    // Restores the FreeSWITCH modules RingQ builds from source (the AI agent's
    // mod_openai_audio_stream, mod_bcg729) from their build output and loads them. Server-wide;
    // runs one fixed script with no input. MCP: ai_agent.repair_module (owner, approval).
    public function aiagentrepairAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isPost()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "POST required."]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $script = dirname(__DIR__) . "/scripts/fs-custom-modules.sh";
        if (!is_file($script)) {
            $this->response->setStatusCode(502, "Bad Gateway");
            $this->response->setContent(json_encode(["result" => "error", "message" => "The module repair script is not on this server yet."]));
            return $this->response;
        }
        $status = function () use ($script) {
            $out = json_decode((string) @shell_exec("/bin/bash " . escapeshellarg($script) . " status 2>/dev/null"), true);
            return is_array($out) ? ($out["modules"] ?? []) : [];
        };
        $before = $status();
        // php-fpm runs under systemd with ProtectSystem=full, so /usr is read-only for PHP and for
        // everything it starts, sudo included: the heal ran as root and still could not write
        // /usr/lib/freeswitch/mod. systemd-run starts the heal as its own unit, outside that sandbox.
        $heal = "/bin/bash " . escapeshellarg($script) . " heal";
        if (is_dir("/run/systemd/system") && is_executable("/usr/bin/systemd-run")) {
            $heal = "/usr/bin/systemd-run --quiet --wait --collect -p RuntimeMaxSec=120 " . $heal;
        }
        @shell_exec("/usr/bin/sudo -n " . $heal . " 2>&1");
        $after = $status();
        $openai = null;
        foreach ($after as $module) {
            if (($module["name"] ?? "") === "mod_openai_audio_stream") {
                $openai = $module;
            }
        }
        $ok = is_array($openai) && ($openai["loaded"] ?? "") === "true";
        if ($ok) {
            $message = "mod_openai_audio_stream is installed and loaded.";
        } elseif (is_array($openai) && empty($openai["build"]) && empty($openai["file"])) {
            $message = "mod_openai_audio_stream is missing and there is no build to restore it from; it has to be rebuilt.";
        } else {
            $message = "The AI module is still not loaded. Check /var/log/ringq-fs-modules.log on the server.";
        }
        $this->response->setContent(json_encode([
            "result" => $ok ? "success" : "error",
            "message" => $message,
            "content" => ["before" => $before, "after" => $after],
        ]));
        return $this->response;
    }

    // Global Settings > AI agent > Test connection: can this server reach OpenAI with the saved
    // token, open the realtime voice connection the 5555 dial plan uses, and get a reply.
    // POST tests the saved token (or "token" in the body, to check one before saving it);
    // GET returns the last result. Never returns the token.
    public function aiagenttestAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        require_once dirname(__DIR__) . "/library/AiVoice.php";
        $sub = (string) $session["subdomain"];
        $lastKey = "ai:" . $sub . "-lastTest";
        if (!$this->request->isPost()) {
            $last = json_decode((string) $this->redis->get($lastKey), true);
            $this->response->setContent(json_encode(["result" => "success", "message" => "", "content" => is_array($last) ? $last : null]));
            return $this->response;
        }
        $body = json_decode((string) file_get_contents("php://input"), true);
        $typed = trim((string) (is_array($body) ? ($body["token"] ?? "") : $this->request->getPost("token", "string", "")));
        // Same lookup as the 5555 dial plan build (AccountsController)
        $saved = (string) $this->redis->get("ai:" . $sub . "-token");
        if ($saved === "" || $saved === "null") $saved = (string) $this->redis->get("ai:" . $sub . "-aiAgentChatgptToken");
        if ($saved === "null") $saved = "";
        $token = $typed !== "" ? $typed : $saved;

        set_time_limit(60);
        $result = \AiVoice::connectionTest($token);
        $result["tokenSource"] = $typed !== "" && $typed !== $saved ? "typed" : "saved";

        // The 5555 dial plan carries its own copy of the token: an older one there means calls
        // still use it even though the test passes.
        if ($result["tokenSource"] === "saved" && $saved !== "") {
            $xml = (string) $this->db->fetchColumn(
                "SELECT dialplan_xml FROM v_dialplans WHERE domain_uuid = CAST(:domain AS uuid) AND dialplan_number = '5555' LIMIT 1",
                ["domain" => $session["domain_uuid"]]
            );
            $inPlan = preg_match('/STREAM_OPENAI_API_KEY=([^"]*)"/', $xml, $m) ? html_entity_decode($m[1], ENT_QUOTES | ENT_XML1) : null;
            if ($xml === "") {
                $result["steps"][] = ["key" => "dialplan", "label" => "Calls to 5555 use this token", "ok" => false, "ms" => 0,
                    "detail" => "The AI agent number 5555 has no dial plan yet. Save the AI agent settings once."];
                $result["ok"] = false;
            } elseif ($inPlan !== $saved) {
                $result["steps"][] = ["key" => "dialplan", "label" => "Calls to 5555 use this token", "ok" => false, "ms" => 0,
                    "detail" => "Calls to 5555 still use a different token. Press Save changes on the AI agent page to update them."];
                $result["ok"] = false;
            } else {
                $result["steps"][] = ["key" => "dialplan", "label" => "Calls to 5555 use this token", "ok" => true, "ms" => 0,
                    "detail" => "The 5555 dial plan uses the saved token."];
            }
        }
        $result["by"] = (string) ($session["extension"] ?? "");
        $this->redis->setex($lastKey, 30 * 86400, json_encode($result));
        \AiVoice::log($this->redis, $sub, "test", $result["ok"] ? "Connection test passed" : "Connection test failed: " . \AiVoice::firstProblem($result), [
            "by" => $result["by"], "steps" => array_map(function ($s) { return $s["key"] . "=" . var_export($s["ok"], true); }, $result["steps"]),
        ]);
        $this->response->setContent(json_encode(["result" => "success", "message" => "", "content" => $result]));
        return $this->response;
    }

    // Service restart > AI Voice: the FreeSWITCH module the AI agent (5555) streams through.
    // GET {loaded, detail}; POST ends the calls on 5555 and reloads the module. Lives here and
    // not in register/system so it ships without touching RegisterController.
    public function aiagentrestartAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $script = dirname(__DIR__) . "/scripts/fs-custom-modules.sh";
        $module = function () use ($script) {
            if (!is_file($script)) return null;
            $out = json_decode((string) @shell_exec("timeout 15 /bin/bash " . escapeshellarg($script) . " status 2>/dev/null"), true);
            foreach ((array) ($out["modules"] ?? []) as $m) {
                if (($m["name"] ?? "") === "mod_openai_audio_stream") return $m;
            }
            return null;
        };
        $state = function ($ai) {
            if (is_array($ai) && ($ai["loaded"] ?? "") === "true") return ["loaded" => true, "detail" => ""];
            if (!is_array($ai) || ($ai["loaded"] ?? "") === "unknown") return ["loaded" => false, "detail" => "not answering"];
            if (empty($ai["file"]) && empty($ai["build"])) return ["loaded" => false, "detail" => "not installed on this server"];
            return ["loaded" => false, "detail" => "module not loaded"];
        };
        if (!$this->request->isPost()) {
            $this->response->setContent(json_encode(["result" => "success", "message" => "", "content" => $state($module())]));
            return $this->response;
        }
        if (!is_file($script)) {
            $this->response->setContent(json_encode(["result" => "error", "message" => "AI Voice restart is not on this server yet. Update the server first."]));
            return $this->response;
        }
        // php-fpm's ProtectSystem keeps /usr read-only for us, so the script runs as its own unit
        $run = "/bin/bash " . escapeshellarg($script) . " restart";
        if (is_dir("/run/systemd/system") && is_executable("/usr/bin/systemd-run")) {
            $run = "/usr/bin/systemd-run --quiet --wait --collect --pipe -p RuntimeMaxSec=90 " . $run;
        }
        $out = [];
        exec("timeout 100 /usr/bin/sudo -n " . $run . " 2>/dev/null", $out);
        $result = json_decode((string) end($out), true);
        $now = $state($module());
        $dropped = (int) ($result["dropped"] ?? 0);
        require_once dirname(__DIR__) . "/library/AiVoice.php";
        \AiVoice::log($this->redis, (string) $session["subdomain"], "restart",
            ($now["loaded"] ? "AI Voice restarted" : "AI Voice restart failed") . ", " . $dropped . " AI call(s) ended",
            ["by" => (string) ($session["extension"] ?? "")]);
        $this->audit("service-restart", "restart", [
            "entity" => "AI Voice",
            "result" => $now["loaded"] ? "success" : "error",
            "metadata" => ["type" => 11, "dropped" => $dropped],
        ]);
        if (!$now["loaded"]) {
            $message = $now["detail"] === "not installed on this server"
                ? "The AI Voice module is not installed on this server. Contact RingQ support."
                : "AI Voice did not come back. Contact RingQ support if it stays offline.";
            $this->response->setContent(json_encode(["result" => "error", "message" => $message, "content" => $now]));
            return $this->response;
        }
        $this->response->setContent(json_encode(["result" => "success", "message" => "", "content" => $now + ["dropped" => $dropped]]));
        return $this->response;
    }

    // Global Settings > AI agent > Log: each call to the AI agent (5555) with what happened
    // between it and OpenAI, plus connection tests and AI Voice restarts. GET ?days=1..30.
    public function aiagentlogAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        require_once dirname(__DIR__) . "/library/AiVoice.php";
        $sub = (string) $session["subdomain"];
        $days = max(1, min(30, (int) $this->request->getQuery("days", "int", 7)));
        $since = time() - $days * 86400;
        $rows = $this->db->fetchAll(
            "SELECT xml_cdr_uuid::text AS uuid, caller_id_name, caller_id_number, direction,
                    start_epoch, answer_epoch, end_epoch, billsec, duration, hangup_cause
               FROM q_ringq_cdr
              WHERE domain_uuid = CAST(:domain AS uuid)
                AND (destination_number = '5555' OR caller_destination = '5555')
                AND start_epoch >= :since
              ORDER BY start_epoch DESC
              LIMIT 300",
            \Phalcon\Db\Enum::FETCH_ASSOC,
            ["domain" => $session["domain_uuid"], "since" => $since]
        );
        $starts = [];
        foreach ($rows as $row) {
            $starts[(string) $row["uuid"]] = (int) $row["start_epoch"];
        }
        $results = \AiVoice::callResults($this->redis, $sub, $starts);
        $calls = [];
        foreach ($rows as $row) {
            $r = $results[(string) $row["uuid"]] ?? ["result" => "unknown", "reason" => "", "errors" => 0, "lines" => []];
            $calls[] = [
                "uuid" => (string) $row["uuid"],
                "start" => (int) $row["start_epoch"],
                "callerName" => (string) $row["caller_id_name"],
                "caller" => (string) $row["caller_id_number"],
                "direction" => (string) $row["direction"],
                "talk" => (int) $row["billsec"],
                "hangupCause" => (string) $row["hangup_cause"],
                "result" => $r["result"],
                "reason" => $r["reason"],
                "errors" => (int) $r["errors"],
                "lines" => $r["lines"],
            ];
        }
        $events = array_values(array_filter(\AiVoice::readLog($this->redis, $sub, 200), function ($e) use ($since) {
            return (int) ($e["at"] ?? 0) >= $since;
        }));
        $last = json_decode((string) $this->redis->get("ai:" . $sub . "-lastTest"), true);
        $this->response->setContent(json_encode([
            "result" => "success",
            "message" => "",
            "content" => [
                "days" => $days,
                "calls" => $calls,
                "events" => $events,
                "lastTest" => is_array($last) ? $last : null,
                "summary" => [
                    "total" => count($calls),
                    "connected" => count(array_filter($calls, function ($c) { return $c["result"] === "connected"; })),
                    "failed" => count(array_filter($calls, function ($c) { return $c["result"] === "failed"; })),
                ],
            ],
        ]));
        return $this->response;
    }

    // SIP profiles as FreeSWITCH sees them, the TLS files compared with all.pem, and each
    // problem with what to do. Shared by api/lists/sipprofiles and api/siprepair.
    private function sipProfileHealth(): array
    {
        $rows = [];
        try {
            $rows = $this->db->fetchAll(
                "SELECT p.sip_profile_name AS name, p.sip_profile_enabled::text AS enabled,
                        MAX(CASE WHEN s.sip_profile_setting_name = 'sip-ip' AND s.sip_profile_setting_enabled::text = 'true' THEN s.sip_profile_setting_value END) AS sip_ip,
                        MAX(CASE WHEN s.sip_profile_setting_name = 'rtp-ip' AND s.sip_profile_setting_enabled::text = 'true' THEN s.sip_profile_setting_value END) AS rtp_ip,
                        MAX(CASE WHEN s.sip_profile_setting_name = 'ext-sip-ip' AND s.sip_profile_setting_enabled::text = 'true' THEN s.sip_profile_setting_value END) AS ext_sip_ip,
                        MAX(CASE WHEN s.sip_profile_setting_name = 'ext-rtp-ip' AND s.sip_profile_setting_enabled::text = 'true' THEN s.sip_profile_setting_value END) AS ext_rtp_ip,
                        MAX(CASE WHEN s.sip_profile_setting_name = 'sip-port' AND s.sip_profile_setting_enabled::text = 'true' THEN s.sip_profile_setting_value END) AS sip_port
                   FROM v_sip_profiles p
                   LEFT JOIN v_sip_profile_settings s ON s.sip_profile_uuid = p.sip_profile_uuid
                  GROUP BY p.sip_profile_name, p.sip_profile_enabled
                  ORDER BY CASE p.sip_profile_name WHEN 'internal' THEN 0 WHEN 'external' THEN 1 ELSE 2 END, p.sip_profile_name",
                \Phalcon\Db\Enum::FETCH_ASSOC
            );
        } catch (\Throwable $e) {
            error_log("sipProfileHealth: " . $e->getMessage());
        }
        $enabled = [];
        foreach ($rows as $row) {
            $name = (string) $row["name"];
            if (in_array(strtolower((string) $row["enabled"]), ["true", "t", "1"], true) && preg_match('/^[A-Za-z0-9_.-]{1,64}$/', $name)) {
                $enabled[] = $name;
            }
        }

        $script = dirname(__DIR__) . "/scripts/fs-sip-profiles.sh";
        $status = null;
        if (is_file($script)) {
            $status = json_decode((string) @shell_exec("/bin/bash " . escapeshellarg($script) . " status " . implode(" ", array_map("escapeshellarg", $enabled)) . " 2>/dev/null"), true);
        }
        $running = [];
        foreach ((array) ($status["profiles"] ?? []) as $profile) {
            $running[(string) ($profile["name"] ?? "")] = !empty($profile["running"]);
        }
        $localIps = array_values(array_filter((array) ($status["localIps"] ?? []), "is_string"));
        $serverIps = array_values(array_filter($localIps, function ($ip) {
            return strpos($ip, "127.") !== 0;
        }));

        $problems = [];
        if (!is_file($script)) {
            $problems[] = "The SIP profile check is not on this server yet; update the server.";
        } elseif (!is_array($status)) {
            $problems[] = "Could not check FreeSWITCH on this server.";
        } elseif (empty($status["fsUp"])) {
            $problems[] = "FreeSWITCH is not answering, so no SIP profile can run. It has to be restarted on the server.";
        }

        $profiles = [];
        foreach ($rows as $row) {
            $name = (string) $row["name"];
            $isEnabled = in_array($name, $enabled, true);
            $isRunning = $running[$name] ?? false;
            $profiles[] = [
                "name" => $name,
                "enabled" => $isEnabled,
                "running" => $isRunning,
                "sipIp" => (string) $row["sip_ip"],
                "rtpIp" => (string) $row["rtp_ip"],
                "extSipIp" => (string) $row["ext_sip_ip"],
                "extRtpIp" => (string) $row["ext_rtp_ip"],
                "port" => (string) $row["sip_port"],
            ];
            if (!$isEnabled || !is_array($status) || empty($status["fsUp"]) || $isRunning) {
                continue;
            }
            $notLocal = [];
            foreach (["SIP IP" => (string) $row["sip_ip"], "RTP IP" => (string) $row["rtp_ip"]] as $label => $value) {
                if (filter_var($value, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) && $localIps !== [] && !in_array($value, $localIps, true)) {
                    $notLocal[] = $label . " " . $value;
                }
            }
            $effect = $name === "internal"
                ? "phones, desk phones and the web app cannot register"
                : ($name === "external" ? "SIP trunks cannot register or carry calls" : "nothing using it can connect");
            if ($notLocal !== []) {
                $problems[] = "The " . $name . " SIP profile is not running, so " . $effect . ": its " . implode(" and ", $notLocal)
                    . " is not an address on this server (it has " . ($serverIps !== [] ? implode(", ", $serverIps) : "none") . ")."
                    . " Run sip.repair to set it back to " . '$${local_ip_v4}' . " (the address FreeSWITCH finds on this server); the public IP stays in Ext. IP.";
            } else {
                $problems[] = "The " . $name . " SIP profile is not running, so " . $effect . ". Run sip.repair to start it.";
            }
        }

        $tls = is_array($status) ? ($status["tls"] ?? null) : null;
        if (is_array($tls)) {
            $all = (string) ($tls["allPem"] ?? "");
            if ($all === "missing" || $all === "broken") {
                $problems[] = "The FreeSWITCH certificate bundle (all.pem) is " . $all . ". Renew the SSL certificate (Global Settings > SSL Certificate) first.";
            }
            foreach ((array) ($tls["files"] ?? []) as $file) {
                $state = (string) ($file["state"] ?? "");
                $fileName = (string) ($file["name"] ?? "");
                if ($state === "stale") {
                    $problems[] = $fileName . " still holds an old certificate or key, not the current one in all.pem, so the secure SIP and WebSocket (7443) ports cannot start. Run sip.repair to point it at all.pem.";
                }
            }
        }

        $ringqConfig = is_array($status) ? (string) ($status["ringqConfig"] ?? "") : "";
        if ($ringqConfig === "blocked" || $ringqConfig === "unreadable") {
            $problems[] = "FreeSWITCH cannot read its RingQ settings in /etc/ringq ("
                . ($ringqConfig === "blocked" ? "it cannot open the folder" : "config.conf is not readable")
                . "), so SIP profiles, extensions and the dial plan stop loading as soon as the cache is cleared or FreeSWITCH restarts. Run sip.repair to give it read access back.";
        }

        $queue = is_array($status) && is_array($status["wssQueue"] ?? null) ? $status["wssQueue"] : null;
        if ($queue !== null && !empty($queue["full"])) {
            $problems[] = "Port 7443 is not accepting new connections (" . (int) ($queue["queued"] ?? 0) . " waiting, room for "
                . (int) ($queue["backlog"] ?? 0) . "), so phones and the web app show offline although the internal profile reads RUNNING."
                . " FreeSWITCH has to be restarted on the server; sip.repair never restarts a running profile.";
        }

        $certificate = null;
        if (is_array($status) && !empty($running["internal"])) {
            require_once __DIR__ . "/../library/ServiceHealth.php";
            $auth = $this->session->get("auth");
            $host = strtolower(trim((string) (is_array($auth) ? ($auth["subdomain"] ?? "") : "")));
            if ($host !== "") {
                $addresses = array_values(array_unique(array_merge(["127.0.0.1"], $serverIps)));
                $served = [
                    \ServiceHealth::servedCertificate($host, 443, \ServiceHealth::SERVED_CERT_PORTS[443], $addresses),
                    \ServiceHealth::servedCertificate($host, 7443, \ServiceHealth::SERVED_CERT_PORTS[7443], $addresses),
                ];
                $certificate = $served[1];
                if (!empty($certificate["reachable"])) {
                    foreach (\ServiceHealth::servedCertificateProblems($served, $host, 7443) as $problem) {
                        $problems[] = $problem;
                    }
                }
            }
        }

        return [
            "working" => $problems === [],
            "problems" => $problems,
            "fsUp" => is_array($status) && !empty($status["fsUp"]),
            "profiles" => $profiles,
            "tls" => $tls,
            "ringqConfig" => $ringqConfig,
            "wssQueue" => $queue,
            "certificate7443" => $certificate,
            "localIps" => $localIps,
            "enabled" => $enabled,
        ];
    }

    private function databaseOwnership(): array
    {
        $who = [];
        $objects = [];
        try {
            $who = $this->db->fetchOne(
                "SELECT current_user AS role, current_database() AS db, (SELECT rolsuper::text FROM pg_roles WHERE rolname = current_user) AS super",
                \Phalcon\Db\Enum::FETCH_ASSOC
            ) ?: [];
            $objects = $this->db->fetchAll(
                "SELECT c.relname AS name, c.relkind AS kind, pg_get_userbyid(c.relowner) AS owner,
                        (CASE WHEN c.relkind = 'S' THEN has_sequence_privilege(c.oid, 'SELECT') ELSE has_table_privilege(c.oid, 'SELECT') END)::text AS readable
                   FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
                  WHERE n.nspname = 'public' AND c.relkind IN ('r','p','v','m','f','S')
                    AND pg_get_userbyid(c.relowner) <> current_user
                  ORDER BY c.relname",
                \Phalcon\Db\Enum::FETCH_ASSOC
            );
        } catch (\Throwable $e) {
            error_log("databaseOwnership: " . $e->getMessage());
            return ["working" => false, "problems" => ["Could not read the database."], "database" => "", "role" => "", "superuser" => false, "objects" => []];
        }
        $kinds = ["r" => "table", "p" => "table", "v" => "view", "m" => "materialized view", "f" => "foreign table", "S" => "sequence"];
        $list = [];
        $unreadable = [];
        foreach ($objects as $row) {
            $readable = in_array(strtolower((string) $row["readable"]), ["true", "t", "1"], true);
            $list[] = [
                "name" => (string) $row["name"],
                "kind" => $kinds[(string) $row["kind"]] ?? "relation",
                "owner" => (string) $row["owner"],
                "readable" => $readable,
            ];
            if (!$readable) {
                $unreadable[] = (string) $row["name"];
            }
        }
        $role = (string) ($who["role"] ?? "");
        $superuser = in_array(strtolower((string) ($who["super"] ?? "")), ["true", "t", "1"], true);
        $problems = [];
        if ($list !== [] && !$superuser) {
            $names = array_column($list, "name");
            $problems[] = count($list) . " database object(s) are owned by another role instead of " . $role . ": "
                . implode(", ", array_slice($names, 0, 20)) . (count($names) > 20 ? ", …" : "") . "."
                . ($unreadable !== [] ? " The app cannot read " . count($unreadable) . " of them, so whatever uses them fails (for example a queue that rings nobody)." : "")
                . " Time Machine backups (pg_dump as " . $role . ") fail on them. Run database.repair_ownership to give them to " . $role . ".";
        }
        $schema = $this->databaseSchemaPrivileges();
        if (!$superuser && $schema !== [] && (!$schema["usage"] || !$schema["create"])) {
            $problems[] = $role . " cannot " . (!$schema["usage"] ? "use" : "create tables in") . " schema public, so updates that add tables or columns fail with \"permission denied for schema public\". Run database.repair_ownership to grant it.";
        }
        return [
            "working" => $problems === [],
            "problems" => $problems,
            "database" => (string) ($who["db"] ?? ""),
            "role" => $role,
            "superuser" => $superuser,
            "objects" => $list,
            "schema" => $schema,
        ];
    }

    private function databaseSchemaPrivileges(): array
    {
        try {
            $row = $this->db->fetchOne(
                "SELECT has_schema_privilege(current_user, 'public', 'USAGE')::text AS usage, has_schema_privilege(current_user, 'public', 'CREATE')::text AS create_priv,
                        (SELECT pg_get_userbyid(nspowner) FROM pg_namespace WHERE nspname = 'public') AS owner",
                \Phalcon\Db\Enum::FETCH_ASSOC
            ) ?: [];
        } catch (\Throwable $e) {
            error_log("databaseSchemaPrivileges: " . $e->getMessage());
            return [];
        }
        $yes = function ($v) { return in_array(strtolower((string) $v), ["true", "t", "1"], true); };
        return ["usage" => $yes($row["usage"] ?? ""), "create" => $yes($row["create_priv"] ?? ""), "owner" => (string) ($row["owner"] ?? "")];
    }

    public function dbownerrepairAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isPost()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "POST required."]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $script = dirname(__DIR__) . "/scripts/db-owner-heal.sh";
        if (!is_file($script)) {
            $this->response->setStatusCode(502, "Bad Gateway");
            $this->response->setContent(json_encode(["result" => "error", "message" => "The database ownership repair is not on this server yet."]));
            return $this->response;
        }
        $before = $this->databaseOwnership();
        $name = '/^[A-Za-z_][A-Za-z0-9_]{0,62}$/D';
        if (!preg_match($name, $before["database"]) || !preg_match($name, $before["role"])) {
            $this->response->setStatusCode(500, "Internal Server Error");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Could not tell which database and role the app uses."]));
            return $this->response;
        }
        $schemaMissing = !empty($before["schema"]) && (!$before["schema"]["usage"] || !$before["schema"]["create"]);
        if (($before["objects"] !== [] || $schemaMissing) && !$before["superuser"]) {
            $fix = "/bin/bash " . escapeshellarg($script) . " fix " . escapeshellarg($before["database"]) . " " . escapeshellarg($before["role"]);
            if (is_dir("/run/systemd/system") && is_executable("/usr/bin/systemd-run")) {
                $fix = "/usr/bin/systemd-run --quiet --wait --collect -p RuntimeMaxSec=120 " . $fix;
            }
            @shell_exec("/usr/bin/sudo -n " . $fix . " 2>&1");
        }
        $after = $this->databaseOwnership();
        $ok = $after["working"];
        $queueAgents = $this->reloadCallCenterTiers(null);
        if (($before["objects"] === [] && !$schemaMissing) || $before["superuser"]) {
            $message = "Nothing to repair: the app role can use every database object.";
        } elseif ($ok) {
            $message = $before["objects"] !== [] ? "Ownership given to " . $after["role"] . ": " . implode(", ", array_column($before["objects"], "name")) . "." : "";
            $message = trim($message . ($schemaMissing ? " Granted " . $after["role"] . " use of schema public." : ""));
        } else {
            $message = ($after["objects"] !== [] ? "Still owned by another role: " . implode(", ", array_column($after["objects"], "name")) . ". " : "")
                . (!empty($after["schema"]) && (!$after["schema"]["usage"] || !$after["schema"]["create"]) ? $after["role"] . " still cannot use schema public. " : "")
                . "Details are in /var/log/ringq-db-owner.log on the server.";
        }
        if ($queueAgents["added"] > 0) {
            $message .= " Loaded " . $queueAgents["added"] . " queue agent(s) that the call center had dropped.";
        }
        if (!$queueAgents["after"]["working"]) {
            $message .= " Queue agents: " . implode(" ", $queueAgents["after"]["problems"]);
        }
        $this->response->setContent(json_encode([
            "result" => $ok ? "success" : "error",
            "message" => $message,
            "content" => ["before" => $before, "after" => $after, "queueAgents" => $queueAgents],
        ]));
        return $this->response;
    }

    private function callCenterTiers(?string $domainUuid): array
    {
        $assoc = \Phalcon\Db\Enum::FETCH_ASSOC;
        $has = $this->db->fetchOne("SELECT (to_regclass('public.q_call_center_tier_order') IS NOT NULL)::text AS x", $assoc) ?: [];
        $ordered = in_array(strtolower((string) ($has["x"] ?? "")), ["true", "t", "1"], true);
        $sql = "SELECT t.call_center_agent_uuid::text AS agent, q.queue_extension::text || '@' || d.domain_name AS queue,
                       coalesce(a.agent_name, '') AS agent_name, "
            . ($ordered
                ? "coalesce(o.tier_level, greatest(coalesce(t.tier_level, 0), coalesce(t.tier_position, 0) + 1)) AS level, coalesce(o.tier_position, 0) AS position "
                : "coalesce(t.tier_level, 0) AS level, coalesce(t.tier_position, 0) AS position ")
            . "FROM v_call_center_tiers t JOIN v_domains d ON d.domain_uuid = t.domain_uuid
                 JOIN v_call_center_queues q ON q.call_center_queue_uuid = t.call_center_queue_uuid
                 LEFT JOIN v_call_center_agents a ON a.call_center_agent_uuid = t.call_center_agent_uuid "
            . ($ordered ? "LEFT JOIN q_call_center_tier_order o ON o.call_center_queue_uuid = t.call_center_queue_uuid AND o.call_center_agent_uuid = t.call_center_agent_uuid " : "")
            . ($domainUuid !== null ? "WHERE t.domain_uuid::text = :domain " : "")
            . "ORDER BY 2, 1";
        return $this->db->fetchAll($sql, $assoc, $domainUuid !== null ? ["domain" => $domainUuid] : []);
    }

    private function liveCallCenterTiers(): ?array
    {
        $raw = @shell_exec("/usr/bin/fs_cli -x " . escapeshellarg('json {"command":"callcenter_config","data":{"arguments":"tier list"}}') . " 2>/dev/null");
        $decoded = is_string($raw) ? json_decode(trim($raw), true) : null;
        if (!is_array($decoded) || ($decoded["status"] ?? "") !== "success") {
            return null;
        }
        $live = [];
        foreach (is_array($decoded["response"] ?? null) ? $decoded["response"] : [] as $row) {
            if (is_array($row)) {
                $live[strtolower((string) ($row["queue"] ?? "") . "|" . (string) ($row["agent"] ?? ""))] = $row;
            }
        }
        return $live;
    }

    private function callCenterTierHealth(?string $domainUuid): array
    {
        try {
            $expected = $this->callCenterTiers($domainUuid);
        } catch (\Throwable $e) {
            error_log("callCenterTierHealth: " . $e->getMessage());
            $denied = stripos($e->getMessage(), "permission denied") !== false;
            return [
                "working" => false,
                "readable" => false,
                "problems" => [$denied
                    ? "The app cannot read the queue agent tables (" . trim(preg_replace('/\s+/', " ", $e->getMessage())) . "), so FreeSWITCH loads no queue agents and every queue rings nobody. Run database.repair_ownership; it reloads the queue agents afterwards."
                    : "Could not read the queue agents from the database."],
                "configured" => 0,
                "loaded" => null,
                "missing" => [],
            ];
        }
        $live = $this->liveCallCenterTiers();
        $missing = [];
        foreach ($expected as $row) {
            if ($live !== null && !isset($live[strtolower($row["queue"] . "|" . $row["agent"])])) {
                $missing[] = [
                    "queue" => (string) $row["queue"],
                    "agent" => (string) $row["agent"],
                    "agentName" => (string) $row["agent_name"],
                    "level" => (int) $row["level"],
                    "position" => (int) $row["position"],
                ];
            }
        }
        $problems = [];
        if ($live === null) {
            $problems[] = "Could not ask FreeSWITCH which queue agents are loaded (fs_cli did not answer).";
        } elseif ($missing !== []) {
            $names = array_map(function ($m) {
                return ($m["agentName"] !== "" ? $m["agentName"] : $m["agent"]) . " in " . $m["queue"];
            }, $missing);
            $problems[] = count($missing) . " of " . count($expected) . " queue agent(s) are set up but not loaded in the call center, so those queues do not ring them and the wallboard does not show them: "
                . implode(", ", array_slice($names, 0, 20)) . (count($names) > 20 ? ", …" : "") . ". Run queues.reload_agents.";
        }
        return [
            "working" => $problems === [],
            "readable" => true,
            "problems" => $problems,
            "configured" => count($expected),
            "loaded" => $live === null ? null : count($expected) - count($missing),
            "missing" => $missing,
        ];
    }

    private function reloadCallCenterTiers(?string $domainUuid): array
    {
        $before = $this->callCenterTierHealth($domainUuid);
        if (!$before["readable"] || $before["loaded"] === null) {
            return ["reloaded" => false, "added" => 0, "failed" => [], "before" => $before, "after" => $before];
        }
        foreach (["/var/cache/ringq", "/var/cache/fusionpbx"] as $dir) {
            foreach (glob($dir . "/configuration.callcenter.conf.*") ?: [] as $file) {
                @unlink($file);
            }
        }
        $added = 0;
        $failed = [];
        foreach ($before["missing"] as $m) {
            if (!preg_match('/^[0-9A-Za-z*#+_-]{1,20}@[A-Za-z0-9.-]{1,253}$/D', $m["queue"]) || !preg_match('/^[0-9A-Fa-f-]{36}$/D', $m["agent"])) {
                $failed[] = $m["agent"] . " in " . $m["queue"] . ": unexpected name";
                continue;
            }
            $out = (string) @shell_exec("/usr/bin/fs_cli -x " . escapeshellarg("callcenter_config tier add " . $m["queue"] . " " . $m["agent"] . " " . $m["level"] . " " . $m["position"]) . " 2>/dev/null");
            if (strpos($out, "+OK") !== false) {
                $added++;
            } else {
                $failed[] = ($m["agentName"] !== "" ? $m["agentName"] : $m["agent"]) . " in " . $m["queue"] . ": " . (trim($out) !== "" ? trim($out) : "no answer");
            }
        }
        return ["reloaded" => true, "added" => $added, "failed" => $failed, "before" => $before, "after" => $this->callCenterTierHealth($domainUuid)];
    }

    public function queueagentreloadAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["domain_uuid"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isPost()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "POST required."]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $result = $this->reloadCallCenterTiers((string) $session["domain_uuid"]);
        $after = $result["after"];
        if (!$result["reloaded"]) {
            $message = implode(" ", $after["problems"]);
        } elseif ($after["working"]) {
            $message = $result["added"] > 0
                ? "Loaded " . $result["added"] . " queue agent(s); all " . $after["configured"] . " are loaded now."
                : "Nothing to load: all " . $after["configured"] . " queue agent(s) were already loaded.";
        } else {
            $message = "Loaded " . $result["added"] . " queue agent(s); still missing: " . implode("; ", $result["failed"] !== [] ? $result["failed"] : $after["problems"]);
        }
        $this->response->setContent(json_encode([
            "result" => $result["reloaded"] && $after["working"] ? "success" : "error",
            "message" => $message,
            "content" => $result,
        ]));
        return $this->response;
    }

    private function serviceRestartState(string $service): array
    {
        require_once __DIR__ . "/../library/ServiceHealth.php";
        if ($service === "freeswitch") {
            $unit = "unknown";
            foreach (\ServiceHealth::systemdUnits() as $u) {
                if ($u["name"] === "freeswitch") {
                    $unit = $u["state"];
                }
            }
            $profiles = \ServiceHealth::sofiaProfiles();
            $channels = \ServiceHealth::channels();
            return [
                "service" => $unit,
                "profiles" => $profiles["profiles"],
                "profilesError" => $profiles["error"],
                "channels" => count($channels["rows"]),
                "channelsError" => $channels["error"],
            ];
        }
        $node = \ServiceHealth::nodeServices();
        $online = 0;
        foreach ($node["services"] as $app) {
            $online += ($app["state"] ?? "") === "online" ? 1 : 0;
        }
        return ["apps" => $node["services"], "online" => $online, "total" => count($node["services"]), "error" => $node["error"]];
    }

    public function servicerestartAction($service = "")
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isPost()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "POST required."]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $service = strtolower((string) $service);
        if (!in_array($service, ["freeswitch", "node"], true)) {
            $this->response->setStatusCode(400, "Bad Request");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Restart freeswitch or node."]));
            return $this->response;
        }
        $script = dirname(__DIR__) . "/scripts/service-restart.sh";
        if (!is_file($script)) {
            $this->response->setStatusCode(502, "Bad Gateway");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Service restart is not on this server yet."]));
            return $this->response;
        }
        $body = json_decode((string) $this->request->getRawBody(), true);
        $body = is_array($body) ? $body : [];
        $before = $this->serviceRestartState($service);
        if ($service === "freeswitch" && $before["channels"] > 0 && (string) ($body["drop_calls"] ?? "0") !== "1") {
            $this->response->setStatusCode(409, "Conflict");
            $this->response->setContent(json_encode([
                "result" => "error",
                "message" => "FreeSWITCH has " . $before["channels"] . " call channel(s) up on this server. Restarting drops them; send drop_calls 1 to restart anyway, or wait until they end.",
                "content" => ["before" => $before],
            ]));
            return $this->response;
        }
        $run = "/bin/bash " . escapeshellarg($script) . " " . $service;
        if (is_dir("/run/systemd/system") && is_executable("/usr/bin/systemd-run")) {
            $run = "/usr/bin/systemd-run --quiet --wait --collect --pipe -p RuntimeMaxSec=180"
                . ($service === "node" ? " -p KillMode=process" : "") . " " . $run;
        }
        $raw = trim((string) @shell_exec("/usr/bin/sudo -n " . $run . " 2>/dev/null"));
        $outcome = json_decode($raw, true);
        if (!is_array($outcome)) {
            $outcome = ["ok" => false, "error" => "The restart did not report back."];
        }
        $after = $this->serviceRestartState($service);
        $ok = !empty($outcome["ok"]);
        if ($service === "freeswitch") {
            $message = $ok
                ? "FreeSWITCH restarted after " . intval($outcome["waited"] ?? 0) . " seconds; " . intval($outcome["profilesRunning"] ?? 0) . " SIP profile(s) running."
                : "FreeSWITCH restart did not finish: " . (string) ($outcome["error"] ?? "unknown") . ". Details are in /var/log/ringq-service-restart.log on the server.";
        } else {
            $started = (array) ($outcome["started"] ?? []);
            $ok = $ok && $after["total"] > 0 && $after["online"] === $after["total"];
            $message = ($ok ? "Node services restarted: " : "Node services restarted, but not all are online: ")
                . $after["online"] . " of " . $after["total"] . " online"
                . ($started ? "; started again: " . implode(", ", $started) : "") . ".";
            if (!empty($outcome["error"])) {
                $message = "Node services were not restarted: " . (string) $outcome["error"] . ".";
            }
        }
        $this->response->setContent(json_encode([
            "result" => $ok ? "success" : "error",
            "message" => $message,
            "content" => ["before" => $before, "after" => $after, "outcome" => $outcome],
        ]));
        return $this->response;
    }

    private function updateExpectedColumns(): array
    {
        return [
            "agent_details.update_date", "member_board.waiting_seconds", "q_call_journeys.call_type", "q_call_ratings.queue_name",
            "q_company_modes.permission5", "q_company_modes.permission6", "q_company_modes.real_network", "q_contacts.contacttype",
            "q_contacts.createdate", "q_contacts.createdby", "q_dids.country", "q_dids.sip_trunk_name", "q_email_notifications.concurrent_limit",
            "q_outbound_rules.custom_cid", "q_outbound_rules.custom_display", "q_outbound_rules.custom_host", "q_outbound_rules.custom_user",
            "q_storage_retention.archive", "tunnel_config.deleted_at", "tunnel_config.offline_reason", "tunnel_config.phones_registered",
            "tunnel_config.router_phone", "tunnel_config.rtp_sessions", "tunnel_config.uptime_seconds", "tunnel_config.version",
            "v_dialplans.exceeded2", "v_extensions.follow_external", "v_extensions.follow_external2", "v_extensions.follow_external3",
            "v_extensions.follow_internal", "v_extensions.follow_internal2", "v_extensions.follow_internal3", "v_extensions.parallel_external",
            "v_extensions.parallel_external2", "v_extensions.parallel_external3", "v_extensions.parallel_ring", "v_extensions.parallel_ring2",
            "v_extensions.pickup_group", "v_gateways.custom_display", "v_gateways.custom_match", "v_gateways.custom_user",
            "v_gateways.privacy_header", "v_gateways.real_network"
        ];
    }

    private function updateHealthScript(int $since): array
    {
        $script = dirname(__DIR__) . "/scripts/update-health.php";
        if (!is_file($script)) {
            return [];
        }
        $run = "/usr/bin/php " . escapeshellarg($script) . " " . intval($since);
        if (is_dir("/run/systemd/system") && is_executable("/usr/bin/systemd-run")) {
            $run = "/usr/bin/systemd-run --quiet --wait --collect --pipe -p RuntimeMaxSec=60 " . $run;
        }
        $out = json_decode(trim((string) @shell_exec("/usr/bin/sudo -n " . $run . " 2>/dev/null")), true);
        return is_array($out) && !empty($out["ok"]) ? $out : [];
    }

    private function updateHealth(string $subdomain): array
    {
        require_once __DIR__ . "/../library/ServiceHealth.php";
        require_once __DIR__ . "/../library/UpdateReadiness.php";
        $now = time();
        $shared = substr_count($subdomain, ".") >= 3;
        $problems = [];
        $notes = [];
        $iso = function (int $at): ?string {
            return $at > 0 ? gmdate("Y-m-d\TH:i:s\Z", $at) : null;
        };

        $codeVersion = (string) $this->version;
        $serverVersion = (string) (\ServiceHealth::serverVersion($this->redis) ?? "");
        $codeUpdatedAt = (int) @filemtime(__FILE__);
        if ($serverVersion !== "" && $serverVersion !== $codeVersion) {
            $problems[] = "The code on this server is version " . $codeVersion . " but the server reports " . $serverVersion . ", so the last update did not finish recording its version. Run the update again.";
        }

        $last = null;
        try {
            $run = \UpdateReadiness::progress($this->redis);
        } catch (\Throwable $e) {
            $run = null;
        }
        if (is_array($run)) {
            $failing = [];
            foreach ((array) ($run["checks"] ?? []) as $check) {
                if (!empty($check["blocking"]) && empty($check["ok"])) {
                    $failing[] = (string) ($check["label"] ?? $check["key"] ?? "") . ": " . (string) ($check["detail"] ?? "");
                }
            }
            $last = [
                "state" => (string) ($run["state"] ?? ""),
                "from" => (string) ($run["fromVersion"] ?? ""),
                "to" => (string) ($run["toVersion"] ?? ""),
                "at" => (string) ($run["at"] ?? ($run["updatedAt"] ?? "")),
                "ready" => !empty($run["ready"]),
                "failing" => $failing,
            ];
            if (($run["state"] ?? "") === "done" && empty($run["ready"])) {
                $problems[] = "The last update (" . $last["from"] . " to " . $last["to"] . ") finished but the server was not ready for calls: " . implode("; ", $failing) . ".";
            }
        } else {
            $notes[] = "No update has been recorded on this server since update tracking was added.";
        }

        $missing = [];
        $expected = $this->updateExpectedColumns();
        try {
            $tables = array_values(array_unique(array_map(function ($pair) {
                return explode(".", $pair)[0];
            }, $expected)));
            $present = [];
            $tablesPresent = [];
            foreach ($this->db->fetchAll(
                "SELECT table_name, column_name FROM information_schema.columns WHERE table_schema = 'public' AND table_name = ANY(string_to_array(:tables, ','))",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["tables" => implode(",", $tables)]
            ) as $row) {
                $present[strtolower($row["table_name"] . "." . $row["column_name"])] = true;
                $tablesPresent[strtolower($row["table_name"])] = true;
            }
            foreach ($expected as $pair) {
                if (!isset($present[$pair])) {
                    $missing[] = $pair;
                }
            }
            $missingTables = [];
            foreach ($tables as $table) {
                if (!isset($tablesPresent[$table])) {
                    $missingTables[] = $table;
                }
            }
            $missing = array_values(array_filter($missing, function ($pair) use ($missingTables) {
                return !in_array(explode(".", $pair)[0], $missingTables, true);
            }));
            if ($missingTables !== []) {
                $problems[] = count($missingTables) . " database table(s) the update creates are missing (" . implode(", ", $missingTables) . "), so the database migration did not run or stopped part way; features using them fail. Run the update again.";
            }
            if ($missing !== []) {
                $problems[] = count($missing) . " database column(s) the update adds are missing (" . implode(", ", array_slice($missing, 0, 8)) . (count($missing) > 8 ? ", ..." : "") . "), so the database migration did not run or stopped part way; features using them fail. Run the update again.";
            }
        } catch (\Throwable $e) {
            error_log("updateHealth columns: " . $e->getMessage());
            $notes[] = "Could not read the database columns.";
        }

        $worker = $this->mailWorkerState();
        if ($worker !== "RUNNING" && $worker !== "unknown") {
            $problems[] = "The background worker (ringq-worker) is " . $worker . ": emails, Cliniko and Salesforce sync and Time Machine jobs do not run. RingQ support must start it (supervisorctl start ringq-worker).";
        }

        $node = \ServiceHealth::nodeServices();
        $down = [];
        foreach ((array) ($node["services"] ?? []) as $svc) {
            if (($svc["state"] ?? "") !== "online") {
                $down[] = (string) ($svc["name"] ?? "") . " " . (string) ($svc["state"] ?? "unknown");
            }
        }
        if ($down !== []) {
            $problems[] = "Node services not running: " . implode(", ", $down) . ". Run services.restart_node.";
        } elseif (!empty($node["error"])) {
            $notes[] = "Could not read pm2: " . (string) $node["error"] . ".";
        }

        $since = max($codeUpdatedAt, $now - 7 * 86400);
        $logs = $this->updateHealthScript($since);
        $cron = (array) ($logs["cron"] ?? []);
        $web = (array) ($logs["web"] ?? []);
        if ($logs === []) {
            $notes[] = "Could not read the cron and web error logs (the check is missing or did not answer); update the server.";
        } else {
            if ((int) ($cron["errors"] ?? 0) > 0) {
                $problems[] = (int) $cron["errors"] . " error(s) from scheduled tasks (cli.php) since the update" . ($shared ? "." : "; last: " . (string) end($cron["last"]) . ".");
            }
            if ((int) ($web["fatal"] ?? 0) > 0) {
                $problems[] = (int) $web["fatal"] . " PHP fatal error(s) in the web app since the update" . ($shared ? "." : "; last: " . (string) end($web["last"]) . ".");
            }
            if (!empty($web["aclRefused"])) {
                $notes[] = "Requests refused by the access list since the update (if an app uses one of these, it needs registering): " . implode(", ", array_map(function ($action, $count) {
                    return $action . " x" . $count;
                }, array_keys($web["aclRefused"]), $web["aclRefused"])) . ".";
            }
        }

        if ($problems === []) {
            $notes[] = "Nothing the last update could have broken was found.";
        }

        return [
            "working" => $problems === [],
            "problems" => $problems,
            "notes" => $notes,
            "version" => ["code" => $codeVersion, "server" => $serverVersion, "codeUpdatedAt" => $iso($codeUpdatedAt)],
            "lastUpdate" => $last,
            "missingColumns" => $missing,
            "missingTables" => $missingTables ?? [],
            "worker" => $worker,
            "nodeServicesDown" => $down,
            "since" => $iso($since),
            "cronErrors" => (int) ($cron["errors"] ?? 0),
            "phpFatalErrors" => (int) ($web["fatal"] ?? 0),
            "recentErrors" => $shared ? [] : array_values(array_merge((array) ($cron["last"] ?? []), (array) ($web["last"] ?? []))),
            "aclRefused" => (object) ((array) ($web["aclRefused"] ?? [])),
        ];
    }

    public function mailtestAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || empty($session["domain_uuid"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isPost()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "POST required."]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $fqdn = (string) $session["subdomain"];
        $to = $this->accountOwnerEmail((string) $session["domain_uuid"]);
        if ($to === "") {
            $this->response->setStatusCode(409, "Conflict");
            $this->response->setContent(json_encode(["result" => "error", "message" => "The account owner has no email address, so there is nowhere to send the test."]));
            return $this->response;
        }
        if (!$this->redis->set("mailTest:cooldown:" . $fqdn, "1", "EX", 300, "NX")) {
            $this->response->setStatusCode(429, "Too Many Requests");
            $this->response->setContent(json_encode(["result" => "error", "message" => "A test email was sent less than 5 minutes ago. Check mail.status for its result."]));
            return $this->response;
        }
        $id = bin2hex(random_bytes(8));
        $now = time();
        $this->redis->setex("mailTest:pending:" . $fqdn, 3600, json_encode(["id" => $id, "requestedAt" => $now, "to" => $to]));
        $this->redis->lpush("email_queue", json_encode(["type" => "mail_test", "data" => ["id" => $id, "email" => $to, "fqdn" => $fqdn, "requestedAt" => $now]]));
        $this->response->setContent(json_encode([
            "result" => "success",
            "message" => "A test email was queued to the account owner (" . $to . "). Run mail.status in a minute to see how it was sent.",
            "content" => ["id" => $id, "to" => $to, "queuedAt" => gmdate("Y-m-d\TH:i:s\Z", $now)],
        ]));
        return $this->response;
    }

    private function chatConversation(string $subdomain, string $member): ?array
    {
        if ($subdomain === "" || strlen($member) > 300 || !preg_match('/^([^-]*)-(.+)-(website|whatsapp|facebook|telnyx|twilio|telegram|line)-([A-Za-z0-9]+)$/D', $member, $m)) {
            return null;
        }
        [, $name, $address, $channel, $last] = $m;
        $id = $channel === "website" ? $last : $address;
        $email = $channel === "website" ? $address : $last;
        $userKey = "$id-$channel-$name-$email-$subdomain";
        $ourNumber = (string) $this->redis->hget($userKey, "ourNumber");
        $ourNumber = $ourNumber !== "" ? $ourNumber : $id;
        $inboxes = [
            "website" => "$subdomain-external-$email-$id",
            "facebook" => "$subdomain:facebook:919894340047:$email",
            "whatsapp" => "$subdomain:whatsapp:919894340047:$id-$email",
            "telnyx" => "$subdomain:telnyx:$ourNumber:$ourNumber-$email",
            "twilio" => "$subdomain:twilio:$ourNumber:$ourNumber-$email",
            "telegram" => "$subdomain:telegram:$ourNumber:$ourNumber-$email",
            "line" => "$subdomain:line:$id:$id-$email",
        ];
        return ["name" => $name, "address" => $address, "channel" => $channel, "id" => $id, "email" => $email, "userKey" => $userKey, "inbox" => $inboxes[$channel]];
    }

    private function chatAgentKey(string $subdomain, string $extension): string
    {
        if ($extension === "" || !preg_match('/^[0-9A-Za-z]{1,32}$/', $extension)) {
            return "";
        }
        foreach ((array) $this->redis->lrange($subdomain . "-agent_data", 0, -1) as $key) {
            $key = (string) $key;
            if (strpos($key, $extension . "-Agent-") === 0 && substr($key, -strlen("-" . $subdomain)) === "-" . $subdomain) {
                return $key;
            }
        }
        return "";
    }

    private function chatWriteRequest(string $verb)
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        $fail = function (int $status, string $message) {
            $this->response->setStatusCode($status);
            $this->response->setContent(json_encode(["result" => "error", "message" => $message]));
            return $this->response;
        };
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            return $fail(401, "Unauthorized. (Code AI1001)");
        }
        if (!$this->request->isPost()) {
            return $fail(405, "POST required.");
        }
        if (!in_array($this->permissionModeOf($session), [7, 8], true)) {
            return $fail(403, "Only an owner or a manager can " . $verb . " chats. (Code AC4035)");
        }
        $subdomain = (string) $session["subdomain"];
        $body = json_decode((string) $this->request->getRawBody(), true);
        $body = is_array($body) ? $body : [];
        $member = is_string($body["conversation"] ?? null) ? $body["conversation"] : "";
        $conversation = $member !== "" ? $this->chatConversation($subdomain, $member) : null;
        if ($conversation === null || $this->redis->zscore($subdomain . "-conversation", $member) === null) {
            return $fail(404, "No conversation with that id on this account (see chat.conversations).");
        }
        $client = (array) $this->redis->hgetall($conversation["userKey"]);
        if ($client === []) {
            return $fail(404, "The record of that conversation is missing, so it cannot be changed.");
        }
        if ((string) ($client["allocated_room"] ?? "") === "CLOSED") {
            return $fail(409, "That conversation is already resolved.");
        }
        $assigned = json_decode((string) ($client["assigned_agent"] ?? ""), true);
        $conversation["member"] = $member;
        $conversation["room"] = (string) ($client["allocated_room"] ?? "");
        $conversation["prevagent"] = is_array($assigned) && isset($assigned[0]) ? (string) $assigned[0] : "";
        return ["session" => $session, "subdomain" => $subdomain, "body" => $body, "conversation" => $conversation, "fail" => $fail];
    }

    private function chatEmit(string $subdomain, string $extension, array $arg): bool
    {
        try {
            $client = new Client(Client::engine(Client::CLIENT_4X, "ws://127.0.0.1:5001", ["persistent" => false]));
            $client->initialize();
            $client->emit("communicateChat", ["arg" => $arg, "subdomain" => $subdomain, "extension" => $extension, "ip" => ""]);
            $client->close();
            return true;
        } catch (\Throwable $e) {
            error_log("[chat] communicateChat to chat service failed: " . $e->getMessage());
            return false;
        }
    }

    public function chatassignAction()
    {
        $ctx = $this->chatWriteRequest("assign");
        if (!is_array($ctx)) {
            return $ctx;
        }
        $fail = $ctx["fail"];
        $subdomain = $ctx["subdomain"];
        $conversation = $ctx["conversation"];
        $extension = is_scalar($ctx["body"]["extension"] ?? null) ? trim((string) $ctx["body"]["extension"]) : "";
        $agentKey = $this->chatAgentKey($subdomain, $extension);
        if ($agentKey === "") {
            return $fail(404, "Extension " . mb_substr($extension, 0, 32) . " has not signed in to chat on this account, so chats cannot be assigned to it.");
        }
        $agent = (array) $this->redis->hgetall($agentKey);
        $name = trim((string) ($agent["Agent_Name"] ?? ""));
        $space = strpos($name, " ");
        $callerKey = $this->chatAgentKey($subdomain, (string) $ctx["session"]["extension"]);
        $sent = $this->chatEmit($subdomain, (string) $ctx["session"]["extension"], [
            "id" => $conversation["id"],
            "type" => "11",
            "agentUserkey" => $callerKey !== "" ? $callerKey : $agentKey,
            "clientUserKey" => $conversation["userKey"],
            "prevagent" => $conversation["prevagent"],
            "setAllocatedRoom" => "ACTIVE",
            "agentKeyList" => [$extension],
            "fullagentassignedkey" => $agentKey,
            "fqdn" => $subdomain,
            "clientmessagelist" => $conversation["inbox"],
            "firstname" => $space === false ? $name : substr($name, 0, $space),
            "lastname" => $space === false ? "" : substr($name, $space + 1),
        ]);
        if (!$sent) {
            return $fail(503, "The chat service did not answer, so nothing was changed. Try again in a moment.");
        }
        $this->response->setContent(json_encode([
            "result" => "success",
            "message" => "The conversation was handed to extension " . $extension . ". The chat service applies it in a moment; chat.conversations shows the new agent.",
            "content" => ["conversation" => $conversation["member"], "extension" => $extension, "agentName" => $name],
        ]));
        return $this->response;
    }

    public function chatresolveAction()
    {
        $ctx = $this->chatWriteRequest("resolve");
        if (!is_array($ctx)) {
            return $ctx;
        }
        $fail = $ctx["fail"];
        $subdomain = $ctx["subdomain"];
        $conversation = $ctx["conversation"];
        $extension = (string) $ctx["session"]["extension"];
        $agentKey = $this->chatAgentKey($subdomain, $extension);
        if ($agentKey === "") {
            return $fail(409, "Extension " . $extension . " has not signed in to chat on this account. Open Chat in the RingQ app once, then try again.");
        }
        $sent = $this->chatEmit($subdomain, $extension, [
            "id" => $conversation["id"],
            "type" => "12",
            "prevagent" => $conversation["prevagent"],
            "clientUserKey" => $conversation["userKey"],
            "channel" => $conversation["channel"],
            "setAllocatedRoom" => "CLOSED",
            "prevroom" => $conversation["room"],
            "agent_key" => $agentKey,
            "clientmessagelist" => $conversation["inbox"],
        ]);
        if (!$sent) {
            return $fail(503, "The chat service did not answer, so nothing was changed. Try again in a moment.");
        }
        $this->response->setContent(json_encode([
            "result" => "success",
            "message" => "The conversation is being resolved by extension " . $extension . ". The customer is told and the transcript is emailed as in the app.",
            "content" => ["conversation" => $conversation["member"], "resolvedBy" => $extension],
        ]));
        return $this->response;
    }

    private function permissionsScript(array $args, int $seconds): ?array
    {
        $script = dirname(__DIR__) . "/scripts/permissions.php";
        if (!is_file($script)) {
            return null;
        }
        $run = "/usr/bin/php " . escapeshellarg($script) . " " . implode(" ", array_map("escapeshellarg", $args));
        if (is_dir("/run/systemd/system") && is_executable("/usr/bin/systemd-run")) {
            $run = "/usr/bin/systemd-run --quiet --wait --collect --pipe -p RuntimeMaxSec=" . intval($seconds) . " " . $run;
        }
        $out = json_decode(trim((string) @shell_exec("/usr/bin/sudo -n " . $run . " 2>/dev/null")), true);
        return is_array($out) ? $out : null;
    }

    private function permissionsReport(array $areas): array
    {
        $content = ["areas" => $areas];
        $scriptAreas = array_values(array_diff($areas, ["database"]));
        if ($scriptAreas !== []) {
            $out = $this->permissionsScript(["status", implode(",", $scriptAreas)], 90);
            if ($out === null) {
                $content["error"] = "The permission checker is not on this server yet or did not answer.";
            } else {
                $content = array_merge($content, $out);
            }
        }
        if (in_array("database", $areas, true)) {
            $content["database"] = $this->databaseOwnership();
        }
        $problems = [];
        foreach ((array) ($content["files"] ?? []) as $entry) {
            if (empty($entry["ok"])) {
                $problems[] = ["area" => "files", "id" => (string) $entry["id"], "what" => (string) $entry["label"], "problems" => $entry["problems"], "why" => (string) $entry["why"],
                    "repair" => "permissions.repair with items [\"" . $entry["id"] . "\"]"];
            }
        }
        if (isset($content["database"]) && empty($content["database"]["working"])) {
            $problems[] = ["area" => "database", "id" => "database", "what" => "Database ownership and privileges", "problems" => $content["database"]["problems"], "why" => "The app role must own its tables and use schema public.",
                "repair" => "database.repair_ownership"];
        }
        foreach ((array) ($content["services"] ?? []) as $svc) {
            if (empty($svc["ok"])) {
                $problems[] = ["area" => "services", "id" => null, "what" => (string) $svc["service"], "problems" => [(string) $svc["note"]], "why" => "", "repair" => "report only"];
            }
        }
        foreach ((array) ($content["sockets"] ?? []) as $sock) {
            if (empty($sock["ok"])) {
                $problems[] = ["area" => "sockets", "id" => null, "what" => $sock["service"] . " (" . $sock["socket"] . ")", "problems" => [(string) $sock["note"]], "why" => "", "repair" => "report only"];
            }
        }
        foreach (["cron", "security"] as $area) {
            if (isset($content[$area]) && empty($content[$area]["ok"])) {
                $problems[] = ["area" => $area, "id" => null, "what" => $area === "cron" ? "Scheduled tasks" : "Security policy", "problems" => [(string) $content[$area]["note"]], "why" => "", "repair" => "report only"];
            }
        }
        $content["problems"] = $problems;
        $content["summary"] = $problems === []
            ? "No permission problems found" . (isset($content["logs"]["count"]) && $content["logs"]["count"] > 0 ? " now, but the logs show " . $content["logs"]["count"] . " recent permission errors (see logs.recent)." : ".")
            : count($problems) . " permission problem(s). Repair the ones with an id after reading why; the rest need a person.";
        return $content;
    }

    private function permissionsWriteRequest()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        $fail = function (int $status, string $message) {
            $this->response->setStatusCode($status);
            $this->response->setContent(json_encode(["result" => "error", "message" => $message]));
            return $this->response;
        };
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            return $fail(401, "Unauthorized. (Code AI1001)");
        }
        if (!$this->request->isPost()) {
            return $fail(405, "POST required.");
        }
        $refusal = $this->serverWideRefusal($session);
        if ($refusal !== null) {
            return $fail(403, $refusal);
        }
        $body = json_decode((string) $this->request->getRawBody(), true);
        return ["body" => is_array($body) ? $body : [], "fail" => $fail];
    }

    public function permissionsrepairAction()
    {
        $ctx = $this->permissionsWriteRequest();
        if (!is_array($ctx)) {
            return $ctx;
        }
        $fail = $ctx["fail"];
        $items = $ctx["body"]["items"] ?? null;
        if (!is_array($items) || $items === [] || count($items) > 30) {
            return $fail(400, "items must list 1 to 30 entry ids from permissions.check.");
        }
        $ids = [];
        foreach ($items as $item) {
            if (!is_string($item) || !preg_match('/^[a-z0-9-]{1,40}$/D', $item)) {
                return $fail(400, "Entry ids are lower-case words with dashes, as permissions.check lists them.");
            }
            $ids[$item] = true;
        }
        $result = $this->permissionsScript(array_merge(["fix"], array_keys($ids)), 300);
        if ($result === null) {
            return $fail(502, "The permission repair is not on this server yet or did not answer, so nothing was changed.");
        }
        if (isset($result["error"])) {
            return $fail($result["error"] === "busy" ? 409 : 400, (string) $result["message"]);
        }
        $remaining = [];
        foreach ((array) ($result["results"] ?? []) as $r) {
            foreach ((array) $r["remaining"] as $p) {
                $remaining[] = $r["id"] . ": " . $p;
            }
        }
        $changed = (int) ($result["changes"] ?? 0);
        $message = $changed === 0 ? "Nothing needed changing: those entries are already right." : ($result["ok"]
            ? "Repaired " . $changed . " permission(s) and checked them again; all are right now. Undo id " . $result["undo"] . "."
            : "Changed " . $changed . " permission(s) but the check still finds problems: " . implode(" ", array_slice($remaining, 0, 5)) . " Undo id " . $result["undo"] . ".");
        $this->response->setContent(json_encode(["result" => $result["ok"] ? "success" : "error", "message" => $message, "content" => $result]));
        return $this->response;
    }

    public function permissionsrollbackAction()
    {
        $ctx = $this->permissionsWriteRequest();
        if (!is_array($ctx)) {
            return $ctx;
        }
        $fail = $ctx["fail"];
        $undo = $ctx["body"]["undo"] ?? null;
        if (!is_string($undo) || !preg_match('/^\d{8}T\d{6}-[0-9a-f]{8}$/D', $undo)) {
            return $fail(400, "undo must be the undo id permissions.repair returned.");
        }
        $result = $this->permissionsScript(["rollback", $undo], 300);
        if ($result === null) {
            return $fail(502, "The permission repair is not on this server yet or did not answer, so nothing was changed.");
        }
        if (isset($result["error"])) {
            return $fail($result["error"] === "not_found" ? 404 : ($result["error"] === "busy" ? 409 : 400), (string) $result["message"]);
        }
        $this->response->setContent(json_encode([
            "result" => $result["ok"] ? "success" : "error",
            "message" => $result["ok"] ? "Put back " . $result["restored"] . " permission(s) exactly as they were before repair " . $undo . "." : "Some permissions could not be put back: " . implode(", ", (array) $result["failed"]) . ".",
            "content" => $result,
        ]));
        return $this->response;
    }

    private function accountOwnerEmail(string $domainUuid): string
    {
        try {
            $mode = $this->db->fetchOne(
                "SELECT permission1 FROM q_company_modes WHERE domain_uuid = CAST(:domain AS uuid) LIMIT 1",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["domain" => $domainUuid]
            );
            foreach (array_filter(array_map("trim", explode(",", (string) ($mode["permission1"] ?? "")))) as $extension) {
                $row = $this->db->fetchOne(
                    "SELECT u.user_email FROM v_extensions e
                       JOIN v_extension_users eu ON eu.extension_uuid = e.extension_uuid
                       JOIN v_users u ON u.user_uuid = eu.user_uuid
                      WHERE e.domain_uuid = CAST(:domain AS uuid) AND e.extension = :extension AND coalesce(u.user_email, '') <> ''
                      LIMIT 1",
                    \Phalcon\Db\Enum::FETCH_ASSOC,
                    ["domain" => $domainUuid, "extension" => $extension]
                );
                $email = trim((string) ($row["user_email"] ?? ""));
                if (filter_var($email, FILTER_VALIDATE_EMAIL)) {
                    return $email;
                }
            }
        } catch (\Throwable $e) {
            error_log("accountOwnerEmail: " . $e->getMessage());
        }
        return "";
    }

    private function mailWorkerState(): string
    {
        $out = trim((string) @shell_exec("/usr/bin/sudo -n /usr/bin/supervisorctl status ringq-worker 2>/dev/null"));
        if ($out === "" || !preg_match('/^ringq-worker\s+([A-Z]+)/', $out, $m)) {
            return "unknown";
        }
        return $m[1];
    }

    private function mailReachable(string $host, int $port): ?bool
    {
        if ($host === "" || $port <= 0 || !preg_match('/^[A-Za-z0-9.-]+$/D', $host)) {
            return null;
        }
        $socket = @fsockopen($host, $port, $errno, $errstr, 3);
        if ($socket === false) {
            return false;
        }
        fclose($socket);
        return true;
    }

    private function mailHealth(string $subdomain, string $domainUuid): array
    {
        $now = time();
        $shared = substr_count($subdomain, ".") >= 3;
        $problems = [];
        $notes = [];
        $iso = function (int $at): ?string {
            return $at > 0 ? gmdate("Y-m-d\TH:i:s\Z", $at) : null;
        };
        $ago = function (int $seconds): string {
            if ($seconds < 120) {
                return $seconds . " seconds";
            }
            if ($seconds < 7200) {
                return intdiv($seconds, 60) . " minutes";
            }
            if ($seconds < 172800) {
                return intdiv($seconds, 3600) . " hours";
            }
            return intdiv($seconds, 86400) . " days";
        };
        $json = function ($value): array {
            $decoded = json_decode((string) $value, true);
            return is_array($decoded) ? $decoded : [];
        };

        $queue = null;
        $keys = [];
        try {
            $queue = (int) $this->redis->llen("email_queue");
            foreach (["meet:smtp:providers", "meet:smtp:providers:lkg", "meet:smtp:providers:backoff", "meetMail:lastSuccess", "meetMail:lastFailure", "meetMail:lastFallback", "mailTest:" . $subdomain, "mailTest:pending:" . $subdomain, "smtp:" . $subdomain . ":enabled"] as $key) {
                $value = $this->redis->get($key);
                $keys[$key] = ($value === null || $value === false) ? null : (string) $value;
            }
            $smtpSettings = (array) $this->redis->hgetall("smtp:" . $subdomain . ":settings");
        } catch (\Throwable $e) {
            return ["working" => false, "problems" => ["Could not read Redis, which holds the mail queue."], "notes" => []];
        }

        $worker = $this->mailWorkerState();
        if ($worker !== "RUNNING" && $worker !== "unknown") {
            $problems[] = "The worker that sends queued emails (ringq-worker) is " . $worker . ", so meeting, booking, webinar and verification-code emails are not sent. RingQ support must start it (supervisorctl start ringq-worker).";
        } elseif ($worker === "unknown") {
            $notes[] = "Could not read the state of the email worker (ringq-worker).";
        }
        if ($queue !== null && $queue > 50) {
            $problems[] = $queue . " emails are waiting in the queue on this server, so new emails are sent late or not at all.";
        }

        $cached = $json($keys["meet:smtp:providers"]);
        $lastKnown = $json($keys["meet:smtp:providers:lkg"]);
        if (!empty($cached["providers"])) {
            $source = "apiringq";
            $plan = $cached;
        } elseif (!empty($lastKnown["providers"])) {
            $source = $keys["meet:smtp:providers:backoff"] !== null ? "last-known (apiringq not answering)" : "last-known";
            $plan = $lastKnown;
        } else {
            $source = "built-in relay";
            $plan = ["providers" => []];
            $code = @file_get_contents(dirname(__DIR__) . "/jobs/meetJob.php");
            if (is_string($code) && preg_match("/define\('MEET_SMTP_HOST',\s*'([^']*)'\)/", $code, $h) && preg_match("/define\('MEET_SMTP_PORT',\s*(\d+)\)/", $code, $p)) {
                $plan["providers"][] = ["name" => "built-in", "host" => $h[1], "port" => (int) $p[1]];
            }
            if ($keys["meet:smtp:providers:backoff"] !== null) {
                $problems[] = "This server cannot get the SMTP provider list from apiringq (through licensekey.ringq.com) and has never had one, so it sends through the built-in relay only.";
            }
        }
        $providers = [];
        $reachable = 0;
        foreach (array_slice((array) $plan["providers"], 0, 4) as $provider) {
            $host = (string) ($provider["host"] ?? "");
            $port = (int) ($provider["port"] ?? 0);
            $ok = $this->mailReachable($host, $port);
            if ($ok) {
                $reachable++;
            }
            $providers[] = ["name" => (string) ($provider["name"] ?? ""), "host" => $host, "port" => $port, "reachable" => $ok];
        }
        if ($providers !== [] && $reachable === 0) {
            $problems[] = "This server cannot connect to any SMTP provider (" . implode(", ", array_map(function ($p) {
                return $p["host"] . ":" . $p["port"];
            }, $providers)) . "); outbound mail ports are blocked or the providers are down.";
        }

        $success = $json($keys["meetMail:lastSuccess"]);
        $failure = $json($keys["meetMail:lastFailure"]);
        $fallback = $json($keys["meetMail:lastFallback"]);
        $successAt = (int) ($success["at"] ?? 0);
        $failureAt = (int) ($failure["at"] ?? 0);
        $fallbackAt = (int) ($fallback["at"] ?? 0);
        if ($failureAt > $successAt) {
            $problems[] = "The last email attempt failed on " . (string) ($failure["provider"] ?? "a provider") . " " . $ago(max(0, $now - $failureAt)) . " ago"
                . ($shared ? "." : ": " . (string) ($failure["error"] ?? "") . ".");
        }
        if ($fallbackAt > $successAt) {
            $problems[] = "Every SMTP provider failed for the last email, so it went out through the old relay (Library\\Email), which drops calendar invitations' .ics files.";
        }

        $custom = null;
        if ($keys["smtp:" . $subdomain . ":enabled"] === "1") {
            $customHost = preg_replace('#^[a-z][a-z0-9+.-]*://#i', '', trim((string) ($smtpSettings["smtpHost"] ?? "")));
            $customPort = intval($smtpSettings["smtpPort"] ?? 0) ?: 25;
            $custom = [
                "host" => $customHost,
                "port" => $customPort,
                "from" => (string) ($smtpSettings["smtpEmail"] ?? ""),
                "passwordSaved" => (string) ($smtpSettings["smtpPassword"] ?? "") !== "",
                "reachable" => $this->mailReachable($customHost, $customPort),
            ];
            if ($custom["host"] === "" || !$custom["passwordSaved"] || $custom["from"] === "") {
                $problems[] = "This account's own SMTP server is turned on but its host, sender address or password is missing, so system emails (alerts, sign-in) fail.";
            } elseif ($custom["reachable"] === false) {
                $problems[] = "This account's own SMTP server " . $custom["host"] . ":" . $custom["port"] . " cannot be reached from this server, so system emails (alerts, sign-in) fail.";
            }
        }

        $test = null;
        $pending = $json($keys["mailTest:pending:" . $subdomain]);
        $result = $json($keys["mailTest:" . $subdomain]);
        if ($pending !== [] && ($result["id"] ?? "") !== ($pending["id"] ?? "")) {
            $age = max(0, $now - (int) ($pending["requestedAt"] ?? $now));
            $test = ["state" => "queued", "to" => (string) ($pending["to"] ?? ""), "queuedAt" => $iso((int) ($pending["requestedAt"] ?? 0))];
            if ($age > 120) {
                $problems[] = "The test email queued " . $ago($age) . " ago has not been picked up, so the worker is not reading the mail queue.";
            }
        } elseif ($result !== []) {
            $via = (string) ($result["via"] ?? "");
            $test = ["state" => $via === "smtp" ? "sent" : ($via === "library" ? "sent through the old relay" : "failed"), "to" => (string) ($result["to"] ?? ""), "provider" => (string) ($result["provider"] ?? ""), "at" => $iso((int) ($result["at"] ?? 0))];
            if ($via !== "smtp" && $via !== "library") {
                $problems[] = "The last test email could not be sent" . ($shared || empty($result["error"]) ? "." : ": " . (string) $result["error"] . ".");
            }
        }

        if ($problems === []) {
            $notes[] = $successAt > 0 ? "Emails are being sent; the last one was accepted " . $ago(max(0, $now - $successAt)) . " ago." : "No problem found, but no email has been recorded as sent yet; mail.test_send sends one to the account owner.";
        }

        return [
            "working" => $problems === [],
            "problems" => $problems,
            "notes" => $notes,
            "worker" => $worker,
            "queue" => $queue,
            "providerSource" => $source,
            "providers" => $providers,
            "lastSuccess" => $successAt > 0 ? ["at" => $iso($successAt), "provider" => (string) ($success["provider"] ?? ""), "source" => (string) ($success["source"] ?? "")] : null,
            "lastFailure" => $failureAt > 0 ? ["at" => $iso($failureAt), "provider" => (string) ($failure["provider"] ?? ""), "error" => $shared ? "" : (string) ($failure["error"] ?? "")] : null,
            "lastFallbackAt" => $iso($fallbackAt),
            "accountSmtp" => $custom,
            "test" => $test,
        ];
    }

    private function cdrPipelineScript(): array
    {
        $script = dirname(__DIR__) . "/scripts/cdr-pipeline.sh";
        if (!is_file($script)) {
            return [];
        }
        $run = "/bin/bash " . escapeshellarg($script) . " status";
        if (is_dir("/run/systemd/system") && is_executable("/usr/bin/systemd-run")) {
            $run = "/usr/bin/systemd-run --quiet --wait --collect --pipe -p RuntimeMaxSec=60 " . $run;
        }
        $out = json_decode(trim((string) @shell_exec("/usr/bin/sudo -n " . $run . " 2>/dev/null")), true);
        return is_array($out) && !empty($out["ok"]) ? $out : [];
    }

    private function cdrPipelineHealth(string $subdomain, string $domainUuid): array
    {
        require_once __DIR__ . "/../library/ServiceHealth.php";
        $now = time();
        $problems = [];
        $notes = [];
        $ago = function (int $seconds): string {
            if ($seconds < 120) {
                return $seconds . " seconds";
            }
            if ($seconds < 7200) {
                return intdiv($seconds, 60) . " minutes";
            }
            if ($seconds < 172800) {
                return intdiv($seconds, 3600) . " hours";
            }
            return intdiv($seconds, 86400) . " days";
        };
        $iso = function (int $at): ?string {
            return $at > 0 ? gmdate("Y-m-d\TH:i:s\Z", $at) : null;
        };
        $shared = substr_count($subdomain, ".") >= 3;

        $waiting = null;
        $oldestAt = 0;
        $serverWaiting = null;
        $beat = [];
        try {
            $queue = "callLogs-" . $subdomain;
            $waiting = (int) $this->redis->llen($queue);
            if ($waiting > 0) {
                $first = json_decode((string) $this->redis->lindex($queue, 0), true);
                if (is_array($first)) {
                    $oldestAt = (int) ($first["end_epoch"] ?? 0) ?: (int) ($first["start_epoch"] ?? 0);
                }
            }
            foreach (["lastStart", "lastFinish", "lastError", "lastRejected"] as $key) {
                $value = $this->redis->get("cdrPipeline:" . $key);
                $beat[$key] = ($value === null || $value === false) ? null : (string) $value;
            }
        } catch (\Throwable $e) {
            $problems[] = "Could not read Redis, where finished calls wait to be imported.";
        }

        $newest = null;
        $serverNewestAt = 0;
        $domainNames = [];
        try {
            $row = $this->db->fetchOne(
                "SELECT insert_date::text AS saved, coalesce(end_epoch, start_epoch)::bigint AS at
                   FROM q_ringq_cdr WHERE domain_uuid = CAST(:domain AS uuid) AND insert_date IS NOT NULL
                  ORDER BY insert_date DESC LIMIT 1",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["domain" => $domainUuid]
            );
            if ($row) {
                $at = (int) $row["at"];
                $newest = ["savedAt" => (string) $row["saved"], "callEndedAt" => $iso($at), "ageSeconds" => $at > 0 ? max(0, $now - $at) : null];
            }
            $server = $this->db->fetchOne(
                "SELECT max(x.at)::bigint AS at FROM v_domains d
                  CROSS JOIN LATERAL (SELECT coalesce(c.end_epoch, c.start_epoch) AS at FROM q_ringq_cdr c
                                       WHERE c.domain_uuid = d.domain_uuid AND c.insert_date IS NOT NULL
                                       ORDER BY c.insert_date DESC LIMIT 1) x",
                \Phalcon\Db\Enum::FETCH_ASSOC
            );
            $serverNewestAt = (int) ($server["at"] ?? 0);
            foreach ($this->db->fetchAll("SELECT domain_name FROM v_domains WHERE domain_enabled::text IN ('true', 't', '1')", \Phalcon\Db\Enum::FETCH_ASSOC) as $d) {
                if (preg_match('/^[A-Za-z0-9.-]+$/D', (string) $d["domain_name"])) {
                    $domainNames[] = (string) $d["domain_name"];
                }
            }
        } catch (\Throwable $e) {
            error_log("cdrPipelineHealth: " . $e->getMessage());
            $problems[] = "Could not read the call logs in the database.";
        }
        if ($domainNames !== [] && $waiting !== null) {
            try {
                $serverWaiting = 0;
                foreach ($domainNames as $name) {
                    $serverWaiting += (int) $this->redis->llen("callLogs-" . $name);
                }
            } catch (\Throwable $e) {
                $serverWaiting = null;
            }
        }

        $node = \ServiceHealth::nodeServices();
        $recorderState = "unknown";
        if (empty($node["error"])) {
            $recorderState = "missing";
            foreach ((array) ($node["services"] ?? []) as $svc) {
                if (($svc["name"] ?? "") === "server") {
                    $recorderState = (string) ($svc["state"] ?? "unknown");
                }
            }
        }
        if ($recorderState === "missing") {
            $problems[] = "The service that records finished calls (pm2 app server) is not running in pm2, so new calls are not recorded. Run services.restart_node.";
        } elseif ($recorderState !== "online" && $recorderState !== "unknown") {
            $problems[] = "The service that records finished calls (pm2 app server) is " . $recorderState . ", so new calls are not recorded. Run services.restart_node.";
        } elseif ($recorderState === "unknown") {
            $notes[] = "Could not read pm2, so whether finished calls are being recorded is unknown.";
        }

        $script = $this->cdrPipelineScript();
        $scheduledBy = "unknown";
        $lastRunAt = 0;
        if ($script === []) {
            $notes[] = "Could not check how the import is scheduled (the check is missing or did not answer); update the server.";
        } else {
            $env = (array) ($script["env"] ?? []);
            if (empty($env["present"])) {
                $problems[] = "/etc/ringq/.env is missing, so the call recorder cannot reach the database. RingQ support must restore it.";
            } elseif (!empty($env["missing"])) {
                $problems[] = "/etc/ringq/.env lacks " . implode(", ", (array) $env["missing"]) . ", so the call recorder cannot reach the database. RingQ support must complete it.";
            }
            $timer = (array) ($script["timer"] ?? []);
            $service = (array) ($script["service"] ?? []);
            $lastRunAt = (int) ($service["lastExit"] ?? 0);
            if (!empty($script["systemd"])) {
                if (!empty($timer["active"])) {
                    $scheduledBy = !empty($script["watcher"]["active"]) ? "systemd timer and hang-up watcher" : "systemd timer";
                } elseif (!empty($script["cron"]["scheduled"])) {
                    $scheduledBy = "cron";
                } elseif (empty($timer["installed"])) {
                    $scheduledBy = "none";
                    $problems[] = "Nothing imports finished calls: calldetailrecord.timer is not installed, so calls wait in Redis and never reach the call logs. Update the server (the update installs it).";
                } else {
                    $scheduledBy = "none";
                    $problems[] = "Nothing imports finished calls: calldetailrecord.timer is stopped, so calls wait in Redis and never reach the call logs. Start it (systemctl start calldetailrecord.timer) or update the server.";
                }
                $result = (string) ($service["result"] ?? "");
                if ($result !== "" && $result !== "success") {
                    $problems[] = "The last import run failed (" . $result . ", exit status " . intval($service["exitStatus"] ?? 0) . ")" . (!$shared && !empty($script["recentErrors"]) ? ": " . end($script["recentErrors"]) : ".");
                }
            } elseif (!empty($script["cron"]["scheduled"])) {
                $scheduledBy = "cron";
            } else {
                $scheduledBy = "none";
                $problems[] = "Nothing imports finished calls on this server: it has no systemd (a Docker server) and no calldetailrecord line in its crontab, so calls wait in Redis and never reach the call logs. RingQ support must schedule the import.";
            }
            $rejected = (int) ($script["rejected"] ?? 0);
            if ($rejected > 0) {
                $problems[] = $rejected . " call record(s) on this server were refused by the database in the last 6 hours and dropped; they cannot be recovered.";
            }
        }

        $lastStart = (int) ($beat["lastStart"] ?? 0);
        $lastFinish = (int) ($beat["lastFinish"] ?? 0);
        $lastError = json_decode((string) ($beat["lastError"] ?? ""), true);
        if ($lastStart > 0) {
            $lastRunAt = max($lastRunAt, $lastFinish);
            if (is_array($lastError) && (int) ($lastError["at"] ?? 0) >= $lastFinish) {
                $problems[] = "The import job fails before it finishes" . ($shared ? "." : ": " . (string) ($lastError["message"] ?? "unknown error") . ".");
            }
        }
        $rejectedHere = json_decode((string) ($beat["lastRejected"] ?? ""), true);
        if (is_array($rejectedHere) && ($rejectedHere["domain"] ?? "") === $subdomain && $now - (int) ($rejectedHere["at"] ?? 0) < 86400) {
            $problems[] = "A call record of this account was refused by the database " . $ago(max(0, $now - (int) $rejectedHere["at"])) . " ago and dropped: " . (string) ($rejectedHere["message"] ?? "") . ".";
        }

        if ($waiting !== null && $waiting > 0 && $oldestAt > 0 && $now - $oldestAt > 120) {
            $problems[] = $waiting . " finished call(s) of this account are waiting to be imported; the oldest ended " . $ago($now - $oldestAt) . " ago, so the import is not running or keeps failing.";
        }

        if ($problems === []) {
            $notes[] = "Finished calls are recorded and imported.";
            if ($newest === null) {
                $notes[] = "This account has no call records yet.";
            } elseif (($newest["ageSeconds"] ?? null) !== null && $serverNewestAt > 0 && count($domainNames) > 1 && $now - $serverNewestAt < 3600 && $newest["ageSeconds"] > 86400) {
                $notes[] = "Other accounts on this server got call records in the last hour, so the import works; this account's newest call ended " . $ago((int) $newest["ageSeconds"]) . " ago.";
            }
        }

        return [
            "working" => $problems === [],
            "problems" => $problems,
            "notes" => $notes,
            "newestCallRecord" => $newest,
            "serverNewestCallAgeSeconds" => $serverNewestAt > 0 ? max(0, $now - $serverNewestAt) : null,
            "waiting" => ["account" => $waiting, "oldestEndedAt" => $iso($oldestAt), "server" => $serverWaiting],
            "recorder" => ["service" => "server", "state" => $recorderState],
            "importer" => [
                "scheduledBy" => $scheduledBy,
                "lastRunAt" => $iso($lastRunAt),
                "lastResult" => (string) ($script["service"]["result"] ?? ""),
            ],
            "recentErrors" => $shared ? [] : array_values((array) ($script["recentErrors"] ?? [])),
            "recentErrorCount" => count((array) ($script["recentErrors"] ?? [])),
        ];
    }

    private function pushScript(string $command, string $arg = ""): string
    {
        $script = dirname(__DIR__) . "/scripts/push-health.sh";
        if (!is_file($script)) {
            return "";
        }
        $run = "/bin/bash " . escapeshellarg($script) . " " . $command . ($arg !== "" ? " " . escapeshellarg($arg) : "");
        if (is_dir("/run/systemd/system") && is_executable("/usr/bin/systemd-run")) {
            $run = "/usr/bin/systemd-run --quiet --wait --collect --pipe -p RuntimeMaxSec=60 " . $run;
        }
        return trim((string) @shell_exec("/usr/bin/sudo -n " . $run . " 2>/dev/null"));
    }

    private function pushHealth(string $subdomain, string $domainUuid, ?string $onlyExtension = null): array
    {
        $problems = [];
        $notes = [];
        $placeholder = "693aa721556325f440a886";

        $server = json_decode($this->pushScript("status", $subdomain), true);
        if (!is_array($server) || empty($server["ok"])) {
            $server = null;
            $problems[] = "Could not check the push setup on this server (the push check is missing or did not answer); update the server.";
        }

        $moduleLoaded = (string) $this->redis->get("ringPush:modLoaded") === "1";
        $mode = (string) ($this->redis->get("ringPush:mode:" . $subdomain) ?: ($this->redis->get("ringPush:mode:*") ?: "off"));
        $newPush = $moduleLoaded && $mode === "wake";

        if ($server !== null) {
            $fw = (array) ($server["firewall"] ?? []);
            if (($fw["state"] ?? "") === "closed") {
                $missing = (array) ($fw["missingInterfaces"] ?? []);
                $problems[] = "Port 9999 is closed by the server firewall"
                    . ($missing !== [] ? " (its rule is bound to " . implode(", ", $missing) . ", which this server does not have)" : "")
                    . ", so Android phones cannot keep their connection to the server and do not ring"
                    . ($newPush ? " when the old push path is used" : "") . ". Run push.repair to open it.";
            }
            if (empty($server["listening"])) {
                $problems[] = "Nothing is listening on port 9999 (nginx), so Android phones cannot connect for calls.";
            }
            if ($newPush && !empty($server["apns"]["configured"]) && empty($server["apns"]["keyFilePresent"])) {
                $problems[] = "Direct Apple push is configured but its key file is missing, so iPhone pushes go through the relay instead.";
            }
            $errors = (array) ($server["recentErrors"] ?? []);
            if ($errors !== []) {
                $problems[] = count($errors) . " recent push error(s) for this account (see recentErrors): Apple or Firebase refused some pushes.";
            }
            if ($newPush && empty($server["fcmKey"]["present"])) {
                $notes[] = "No server Firebase key is installed; Android ring pushes use the shared Firebase app.";
            }
            if ($newPush && empty($server["apns"]["configured"])) {
                $notes[] = "Direct Apple push is not configured; iPhone pushes go through the relay.";
            }
        }
        if (!$moduleLoaded && $mode === "wake") {
            $notes[] = "Push mode is wake but the FreeSWITCH push module is not loaded, so the old push path is in charge.";
        }

        $rows = [];
        try {
            $rows = $this->db->fetchAll(
                "SELECT q.id, q.extension, q.device_type, coalesce(q.enabled, 1) AS enabled, coalesce(q.push_token, '') AS push_token,
                        coalesce(q.device_name, '') AS device_name, coalesce(q.device_version, '') AS device_version,
                        greatest(q.insert_date, q.update_login)::text AS last_seen,
                        (SELECT o.extension || '@' || coalesce(od.domain_name, '') FROM q_devices o LEFT JOIN v_domains od ON od.domain_uuid = o.domain_uuid
                          WHERE o.push_token = q.push_token AND o.id <> q.id
                            AND (greatest(o.insert_date, o.update_login), o.id) > (greatest(q.insert_date, q.update_login), q.id)
                          ORDER BY greatest(o.insert_date, o.update_login) DESC LIMIT 1) AS token_now_on,
                        EXISTS (SELECT 1 FROM q_devices n
                                 WHERE n.domain_uuid = q.domain_uuid AND n.extension = q.extension AND n.device_type IN (1, 2)
                                   AND coalesce(n.enabled, 1) <> 0 AND coalesce(n.push_token, '') <> ''
                                   AND n.push_token <> q.push_token
                                   AND (greatest(n.insert_date, n.update_login), n.id) > (greatest(q.insert_date, q.update_login), q.id))::text AS newer_phone
                   FROM q_devices q
                  WHERE q.domain_uuid = CAST(:domain AS uuid) AND q.device_type IN (1, 2)" . ($onlyExtension !== null ? " AND q.extension = :ext" : "") . "
                  ORDER BY q.extension, greatest(q.insert_date, q.update_login) DESC NULLS LAST
                  LIMIT 300",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                $onlyExtension !== null ? ["domain" => $domainUuid, "ext" => $onlyExtension] : ["domain" => $domainUuid]
            );
        } catch (\Throwable $e) {
            error_log("pushHealth: " . $e->getMessage());
            $problems[] = "Could not read the account's devices.";
        }

        $byExtension = [];
        if ($onlyExtension !== null) {
            $byExtension[$onlyExtension] = [];
        }
        foreach ($rows as $row) {
            $byExtension[(string) $row["extension"]][] = $row;
        }
        $extensions = [];
        $notPushed = 0;
        foreach ($byExtension as $extension => $deviceRows) {
            $extension = (string) $extension;
            $appDisabled = (bool) $this->redis->exists("disableapp:" . $extension . ":" . $subdomain);
            $extensionDisabled = (bool) $this->redis->exists("extoff:" . $extension . ":" . $subdomain);
            $keyType = strval($this->redis->type($extension . "@" . $subdomain));
            $sockets = (int) $this->redis->scard("sockets-" . $extension . "@" . $subdomain);
            $registered = $keyType === "set" ? (array) $this->redis->smembers($extension . "@" . $subdomain) : [];
            $devices = [];
            foreach ($deviceRows as $row) {
                $token = (string) $row["push_token"];
                $tokenState = "valid";
                if ($token === "") {
                    $tokenState = "missing";
                } elseif (strpos($token, $placeholder) === 0) {
                    $tokenState = "placeholder";
                } elseif (in_array(strtolower($token), ["null", "undefined", "nil", "(null)"], true)) {
                    $tokenState = "invalid";
                }
                $ios = (int) $row["device_type"] === 2;
                $reason = null;
                if ((int) $row["enabled"] === 0) {
                    $reason = "Receive calls is off for this device.";
                } elseif (!$newPush && !$ios) {
                    if ($sockets === 0) {
                        $reason = "The app is not connected to the server right now (closed, battery saving or no network); with the old push an Android phone only rings while the app keeps its connection.";
                    }
                } elseif ($tokenState === "missing" || $tokenState === "invalid") {
                    $reason = "The app never sent a push token (notifications not allowed on the phone, or the app could not register); sign in again on the phone and allow notifications.";
                } elseif ($tokenState === "placeholder") {
                    $reason = $ios
                        ? "The app has no real push token (it signed in without one); sign in again on the phone and allow notifications."
                        : "The app signed in without a Firebase token (an app version older than the ring push), so the ring push cannot reach it; update the app and sign in again.";
                } elseif (!$newPush) {
                    $known = false;
                    foreach ($registered as $member) {
                        $member = (string) $member;
                        if ($member === $token || strpos($member, $token . ":") === 0) {
                            $known = true;
                            break;
                        }
                    }
                    if (!$known) {
                        $reason = "Its push token is not registered on the server for this extension, so the iPhone push cannot reach it; sign in again on the phone.";
                    }
                } elseif ((string) $row["token_now_on"] !== "") {
                    $reason = "This phone has since signed in as " . $row["token_now_on"] . ", so this sign-in is not pushed.";
                } elseif (in_array(strtolower((string) $row["newer_phone"]), ["true", "t", "1"], true)) {
                    $reason = "A newer phone signed in to this extension and takes the pushes (one mobile app per extension).";
                }
                if ($reason === null && ($appDisabled || $extensionDisabled)) {
                    $reason = $extensionDisabled ? "The extension is disabled." : "The mobile app is turned off for this extension in its settings.";
                }
                if ($reason !== null) {
                    $notPushed++;
                }
                $devices[] = [
                    "id" => (int) $row["id"],
                    "platform" => (int) $row["device_type"] === 2 ? "ios" : "android",
                    "name" => (string) $row["device_name"],
                    "version" => (string) $row["device_version"],
                    "lastSeen" => (string) $row["last_seen"],
                    "receiveCalls" => (int) $row["enabled"] !== 0,
                    "pushTokenState" => $tokenState,
                    "via" => $newPush ? ($ios ? "ring push to Apple" : "ring push to Firebase") : ($ios ? "VoIP push through the relay" : "the app's connection to the server"),
                    "pushed" => $reason === null,
                    "reason" => $reason,
                ];
            }
            if (!in_array($keyType, ["set", "none", ""], true)) {
                $problems[] = "Extension " . $extension . ": its push registration key in Redis has the wrong type (" . $keyType . "), so its phone cannot register for pushes. Run push.repair to clear it; the next sign-in recreates it.";
            }
            if ($onlyExtension !== null && $devices === []) {
                $problems[] = "Extension " . $extension . " has no mobile app signed in, so there is nothing to push to.";
            } elseif ($onlyExtension !== null) {
                $pushedCount = count(array_filter($devices, function ($d) { return $d["pushed"]; }));
                if ($pushedCount === 0) {
                    $problems[] = "Extension " . $extension . ": no phone would get a push. " . implode(" ", array_unique(array_filter(array_column($devices, "reason"))));
                }
            }
            $extensions[] = [
                "extension" => $extension,
                "appDisabled" => $appDisabled,
                "extensionDisabled" => $extensionDisabled,
                "pushKeyType" => $keyType === "" ? "none" : $keyType,
                "connectedSockets" => $sockets,
                "devices" => $devices,
            ];
        }
        if ($onlyExtension === null && $notPushed > 0) {
            $notes[] = $notPushed . " mobile sign-in(s) on this account would not be pushed; each device says why.";
        }

        return [
            "working" => $problems === [],
            "problems" => $problems,
            "notes" => $notes,
            "pushPath" => [
                "mode" => $mode,
                "moduleLoaded" => $moduleLoaded,
                "inCharge" => $newPush ? "ring push (mod_ringq)" : "old push",
            ],
            "server" => $server,
            "recentErrors" => $server !== null ? (array) ($server["recentErrors"] ?? []) : [],
            "extensions" => $extensions,
        ];
    }

    public function pushrepairAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isPost()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "POST required."]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        if (!is_file(dirname(__DIR__) . "/scripts/push-health.sh")) {
            $this->response->setStatusCode(502, "Bad Gateway");
            $this->response->setContent(json_encode(["result" => "error", "message" => "The push repair is not on this server yet."]));
            return $this->response;
        }
        $subdomain = (string) $session["subdomain"];
        $domainUuid = (string) $session["domain_uuid"];
        $before = $this->pushHealth($subdomain, $domainUuid);
        $done = [];
        if (($before["server"]["firewall"]["state"] ?? "") === "closed") {
            $this->pushScript("heal");
            $done[] = "opened port 9999";
        }
        foreach ($before["extensions"] as $extension) {
            if (!in_array($extension["pushKeyType"], ["set", "none"], true)) {
                $this->redis->del($extension["extension"] . "@" . $subdomain);
                $done[] = "cleared the push key of extension " . $extension["extension"];
            }
        }
        $after = $this->pushHealth($subdomain, $domainUuid);
        $fixable = function (array $h): array {
            return array_values(array_filter($h["problems"], function ($p) {
                return strpos($p, "Run push.repair") !== false;
            }));
        };
        $left = $fixable($after);
        $ok = $left === [];
        $message = $done === [] ? "Nothing push.repair can fix was found." : ucfirst(implode(", ", $done)) . ".";
        if (!$ok) {
            $message .= " Still not fixed: " . implode(" ", $left) . " Details are in /var/log/ringq-push.log on the server.";
        } elseif ($after["problems"] !== []) {
            $message .= " Other problems need someone at the phone or in settings: see after.problems.";
        }
        $this->response->setContent(json_encode([
            "result" => $ok ? "success" : "error",
            "message" => $message,
            "content" => ["done" => $done, "before" => $before, "after" => $after],
        ]));
        return $this->response;
    }

    private function resetNonLocalSipIps(array $health): array
    {
        $reset = [];
        $localIps = (array) ($health["localIps"] ?? []);
        if (empty($health["fsUp"]) || $localIps === []) {
            return $reset;
        }
        foreach ((array) ($health["profiles"] ?? []) as $profile) {
            if (empty($profile["enabled"]) || !empty($profile["running"])) {
                continue;
            }
            $name = (string) ($profile["name"] ?? "");
            if (!preg_match('/^[A-Za-z0-9_.-]{1,64}$/', $name)) {
                continue;
            }
            foreach (["sip-ip" => (string) ($profile["sipIp"] ?? ""), "rtp-ip" => (string) ($profile["rtpIp"] ?? "")] as $setting => $value) {
                if (!filter_var($value, FILTER_VALIDATE_IP, FILTER_FLAG_IPV4) || in_array($value, $localIps, true)) {
                    continue;
                }
                try {
                    $this->db->execute(
                        "UPDATE v_sip_profile_settings s SET sip_profile_setting_value = ?
                           FROM v_sip_profiles p
                          WHERE s.sip_profile_uuid = p.sip_profile_uuid
                            AND p.sip_profile_name = ?
                            AND s.sip_profile_setting_name = ?
                            AND s.sip_profile_setting_value = ?
                            AND s.sip_profile_setting_enabled::text = 'true'",
                        ['$${local_ip_v4}', $name, $setting, $value]
                    );
                    if ($this->db->affectedRows() > 0) {
                        $reset[] = ["profile" => $name, "setting" => $setting, "from" => $value, "to" => '$${local_ip_v4}'];
                    }
                } catch (\Throwable $e) {
                    error_log("resetNonLocalSipIps: " . $e->getMessage());
                }
            }
        }
        return $reset;
    }

    // Starts SIP profiles that are not running, after pointing TLS files that no longer match
    // all.pem at it. Server-wide; never restarts a running profile. MCP: sip.repair (owner, approval).
    public function siprepairAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isPost()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "POST required."]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $script = dirname(__DIR__) . "/scripts/fs-sip-profiles.sh";
        if (!is_file($script)) {
            $this->response->setStatusCode(502, "Bad Gateway");
            $this->response->setContent(json_encode(["result" => "error", "message" => "The SIP repair script is not on this server yet."]));
            return $this->response;
        }
        $before = $this->sipProfileHealth();
        $ipReset = $this->resetNonLocalSipIps($before);
        $heal = "/bin/bash " . escapeshellarg($script) . " heal " . implode(" ", array_map("escapeshellarg", $before["enabled"]));
        if (is_dir("/run/systemd/system") && is_executable("/usr/bin/systemd-run")) {
            $heal = "/usr/bin/systemd-run --quiet --wait --collect -p RuntimeMaxSec=120 " . $heal;
        }
        @shell_exec("/usr/bin/sudo -n " . $heal . " 2>&1");
        $after = $this->sipProfileHealth();
        $down = [];
        foreach ($after["profiles"] as $profile) {
            if ($profile["enabled"] && !$profile["running"]) {
                $down[] = $profile["name"];
            }
        }
        $ok = $after["fsUp"] && $down === [] && $after["enabled"] !== [];
        if ($ok) {
            $message = "Every enabled SIP profile is running.";
        } elseif (!$after["fsUp"]) {
            $message = "FreeSWITCH is not answering; it has to be restarted on the server.";
        } else {
            $message = "Still not running: " . implode(", ", $down) . ". " . implode(" ", $after["problems"])
                . " Details are in /var/log/ringq-fs-sip.log on the server.";
        }
        if ($ipReset !== []) {
            $message .= ' SIP IP set back to $${local_ip_v4} for: ' . implode(", ", array_map(function ($r) {
                return $r["profile"] . " " . $r["setting"] . " (was " . $r["from"] . ")";
            }, $ipReset)) . ".";
        }
        $this->response->setContent(json_encode([
            "result" => $ok ? "success" : "error",
            "message" => $message,
            "content" => ["before" => $before, "after" => $after, "ipReset" => $ipReset],
        ]));
        return $this->response;
    }

    public function hangupAction()
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");
        $this->response->setHeader("Cache-Control", "no-store");
        $session = $this->session->get("auth");
        if (!$session || empty($session["subdomain"]) || !isset($session["extension"])) {
            $this->response->setStatusCode(401, "Unauthorized");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]));
            return $this->response;
        }
        if (!$this->request->isPost()) {
            $this->response->setStatusCode(405, "Method Not Allowed");
            $this->response->setContent(json_encode(["result" => "error", "message" => "POST required."]));
            return $this->response;
        }
        if ($this->isPlainUser($session)) {
            return $this->forbiddenForUser();
        }
        $body = json_decode((string) file_get_contents("php://input"), true);
        $uuid = strtolower(trim((string) (is_array($body) ? ($body["uuid"] ?? "") : "")));
        if (!preg_match('/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/D', $uuid)) {
            $this->response->setStatusCode(400, "Bad Request");
            $this->response->setContent(json_encode(["result" => "error", "message" => "Give the call uuid from the live calls list."]));
            return $this->response;
        }
        $found = false;
        foreach ($this->tenantChannels((string) $session["subdomain"]) as $row) {
            if (strtolower((string) ($row["uuid"] ?? "")) === $uuid) {
                $found = true;
                break;
            }
        }
        if (!$found) {
            $this->response->setStatusCode(404, "Not Found");
            $this->response->setContent(json_encode(["result" => "error", "message" => "No live call with that uuid on this account."]));
            return $this->response;
        }
        $output = trim((string) @shell_exec("/usr/bin/fs_cli -x " . escapeshellarg("uuid_kill " . $uuid) . " 2>&1"));
        $ok = strpos($output, "+OK") === 0;
        $this->response->setContent(json_encode($ok
            ? ["result" => "success", "message" => "Call ended."]
            : ["result" => "error", "message" => "FreeSWITCH did not end the call: " . mb_substr($output, 0, 120)]));
        return $this->response;
    }

    public function userAction($resource = "")
    {
        $this->view->setRenderLevel(View::LEVEL_NO_RENDER);
        $this->response->setHeader("Content-Type", "application/json");

        $session = $this->session->get("auth");
        if (!$session || empty($session["domain_uuid"]) || empty($session["user_uuid"])) {
            return $this->userPreferencesReply(["result" => "error", "message" => "Unauthorized. (Code AI1001)"]);
        }
        if ($resource !== "preferences") {
            return $this->userPreferencesReply(["result" => "error", "message" => "Unknown resource. (Code AU1000)"]);
        }

        try {
            $method = strtoupper((string) $this->request->getMethod());
            if ($method === "GET") {
                return $this->userPreferencesReply([
                    "result" => "success",
                    "content" => $this->loadUserPreferences($session),
                ]);
            }
            if ($method !== "PUT" && $method !== "POST" && $method !== "PATCH") {
                return $this->userPreferencesReply(["result" => "error", "message" => "Method not allowed. (Code AU1001)"]);
            }

            $changes = $this->readUserPreferenceChanges($method);
            if (is_string($changes)) {
                return $this->userPreferencesReply(["result" => "error", "message" => $changes]);
            }
            $saved = $this->mergeUserPreferences($session, $changes["set"], $changes["delete"]);
            if (is_string($saved)) {
                return $this->userPreferencesReply(["result" => "error", "message" => $saved]);
            }
            return $this->userPreferencesReply(["result" => "success"]);
        } catch (\Throwable $e) {
            error_log("user preferences: " . $e->getMessage());
            return $this->userPreferencesReply(["result" => "error", "message" => "Preferences are unavailable. (Code AU1009)"]);
        }
    }

    private function userPreferencesReply(array $payload)
    {
        $this->response->setContent(json_encode($payload));
        return $this->response;
    }

    // Returns ["set" => stdClass, "delete" => string[]], or an error message.
    // The body is decoded to objects, not arrays, so an empty object value
    // such as {"sizes": {}} is stored as {} and not turned into [].
    private function readUserPreferenceChanges($method)
    {
        $contentType = strtolower((string) $this->request->getContentType());
        $isForm = strpos($contentType, "application/x-www-form-urlencoded") !== false
            || strpos($contentType, "multipart/form-data") !== false;
        if ($isForm && $method === "POST") {
            $raw = (string) $this->request->getPost("preferences");
        } elseif ($isForm) {
            $fields = [];
            parse_str((string) $this->request->getRawBody(), $fields);
            $raw = isset($fields["preferences"]) ? (string) $fields["preferences"] : "";
        } else {
            $raw = (string) $this->request->getRawBody();
        }

        if (strlen($raw) > self::USER_PREFERENCES_MAX_BYTES) {
            return "Preferences are too large. (Code AU1002)";
        }
        $decoded = json_decode($raw);
        if (!($decoded instanceof \stdClass)) {
            return "Preferences must be a JSON object. (Code AU1003)";
        }

        $set = new \stdClass();
        $delete = [];
        foreach (get_object_vars($decoded) as $key => $value) {
            $key = (string) $key;
            if ($key === "" || strlen($key) > self::USER_PREFERENCES_MAX_KEY_LENGTH) {
                return "Invalid preference key. (Code AU1004)";
            }
            if ($value === null) {
                $delete[] = $key;
            } else {
                $set->{$key} = $value;
            }
        }
        return ["set" => $set, "delete" => $delete];
    }

    private function loadUserPreferences(array $session)
    {
        try {
            $row = $this->db->fetchOne(
                "SELECT CAST(preferences AS text) AS preferences FROM q_user_preferences
                  WHERE domain_uuid = :d AND user_uuid = :u",
                \Phalcon\Db\Enum::FETCH_ASSOC,
                ["d" => (string) $session["domain_uuid"], "u" => (string) $session["user_uuid"]]
            );
        } catch (\Throwable $e) {
            if ($this->isMissingUserPreferencesTable($e)) {
                return new \stdClass();
            }
            throw $e;
        }
        if (!$row || !isset($row["preferences"])) {
            return new \stdClass();
        }
        $document = json_decode((string) $row["preferences"]);
        return $document instanceof \stdClass ? $document : new \stdClass();
    }

    // For api/index: never let a preferences failure break the login payload.
    private function userPreferencesForIndex($session)
    {
        try {
            if (!is_array($session) || empty($session["domain_uuid"]) || empty($session["user_uuid"])) {
                return new \stdClass();
            }
            return $this->loadUserPreferences($session);
        } catch (\Throwable $e) {
            error_log("user preferences (index): " . $e->getMessage());
            return new \stdClass();
        }
    }

    // Returns true, or an error message. Retries once after creating the
    // table, for a host whose update has not yet run queries.sql.
    private function mergeUserPreferences(array $session, \stdClass $set, array $delete)
    {
        try {
            return $this->mergeUserPreferencesOnce($session, $set, $delete);
        } catch (\Throwable $e) {
            if (!$this->isMissingUserPreferencesTable($e)) {
                throw $e;
            }
            $this->db->execute(
                "CREATE TABLE IF NOT EXISTS public.q_user_preferences (
                    domain_uuid VARCHAR(64) NOT NULL,
                    user_uuid VARCHAR(64) NOT NULL,
                    preferences JSONB NOT NULL DEFAULT '{}',
                    update_date TIMESTAMPTZ NOT NULL DEFAULT now(),
                    PRIMARY KEY (domain_uuid, user_uuid)
                )"
            );
            return $this->mergeUserPreferencesOnce($session, $set, $delete);
        }
    }

    private function mergeUserPreferencesOnce(array $session, \stdClass $set, array $delete)
    {
        $setJson = json_encode($set);
        $deleteJson = json_encode(array_values($delete));
        // Each placeholder is used once: native PDO prepares refuse a
        // repeated named parameter.
        $sql = "INSERT INTO q_user_preferences (domain_uuid, user_uuid, preferences, update_date)
                VALUES (:d, :u,
                        CAST(:set1 AS jsonb) - ARRAY(SELECT jsonb_array_elements_text(CAST(:del1 AS jsonb))),
                        now())
                ON CONFLICT (domain_uuid, user_uuid) DO UPDATE
                   SET preferences = (q_user_preferences.preferences || CAST(:set2 AS jsonb))
                                     - ARRAY(SELECT jsonb_array_elements_text(CAST(:del2 AS jsonb))),
                       update_date = now()
                RETURNING octet_length(CAST(preferences AS text)) AS size";
        $params = [
            "d" => (string) $session["domain_uuid"],
            "u" => (string) $session["user_uuid"],
            "set1" => $setJson,
            "del1" => $deleteJson,
            "set2" => $setJson,
            "del2" => $deleteJson,
        ];

        $this->db->begin();
        try {
            $row = $this->db->fetchOne($sql, \Phalcon\Db\Enum::FETCH_ASSOC, $params);
            if ($row && isset($row["size"]) && (int) $row["size"] > self::USER_PREFERENCES_MAX_BYTES) {
                $this->db->rollback();
                return "Preferences are too large. (Code AU1002)";
            }
            $this->db->commit();
            return true;
        } catch (\Throwable $e) {
            if ($this->db->isUnderTransaction()) {
                $this->db->rollback();
            }
            throw $e;
        }
    }

    private function isMissingUserPreferencesTable(\Throwable $e)
    {
        $code = (string) $e->getCode();
        $message = ControllerBase::safeErrorMessage($e);
        return $code === "42P01"
            || (strpos($message, "q_user_preferences") !== false && strpos($message, "does not exist") !== false);
    }
}
